/* daily-mocks.js — full-length timed SSC CGL mocks (25Q, exam mode).
   Option order shuffled per-question (2026-10-01): every previous version had
   the correct answer at option A far more often than chance (up to 100% in
   several sets, e.g. oct1_m3/m4), making the key guessable without reading
   the question. Shuffle is seeded per-question (not per-file), so it does not
   correlate across mocks; content/explanations are unchanged, only option
   order + answer index.
   Schema: {q, options[4 or fewer], answer, explanation, rule, trapcat, level}. */
/* daily-mocks.js — full-length timed SSC CGL English mocks (25Q, exam mode).
   Source: september_30_test1/test2 (fixed + deduped against each other).
   Schema matches BANK/PYQ: {q, options[4], answer, explanation, rule, trapcat, level}. */
const DAILY_MOCKS = [
{
  id: "sept30_m1", label: "30 Sep · Morning Full Mock", timeLimitMin: 20,
  questions: [
    { q: "The committee has decided to postpone the meeting due to unavoidable circumstances.", options: ["to postpone the meeting","due to unavoidable circumstances","No error","The committee has decided"], answer: 2, explanation: "Committee is a collective noun acting as a single unit, taking singular verb 'has'.", rule: "Collective noun acting as one unit → singular verb (has, is, was).", trapcat: "Subject-verb agreement", level: "L1 Direct" },
    { q: "One of the highest peaks in the Himalayas is Kanchenjunga.", options: ["One of the highest peaks","No error","in the Himalayas is","Kanchenjunga"], answer: 1, explanation: "'One of + plural noun' → verb is singular. SSC trick: students see 'Himalayas' and expect a plural verb, but the true subject is 'one'.", rule: "One of + plural noun → singular verb.", trapcat: "One of + plural (common error)", level: "L1 Direct" },
    { q: "The hunter as well as the guides were tracking the tiger.", options: ["as well as the guides","No error","were tracking the tiger","The hunter"], answer: 0, explanation: "'As well as' does not pluralise the subject; hunter stays singular → was tracking.", rule: "R4 — as well as does not make subject plural.", trapcat: "As well as trap", level: "L2 Application" },
    { q: "The list of items is missing from the inventory.", options: ["is missing from the inventory","The list of items","No error"], answer: 2, explanation: "The list is singular; 'of items' is a prepositional phrase that does not change the subject.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "Either the manager or his staff is responsible for this mistake.", options: ["is responsible for this mistake","Either the manager or his staff","No error"], answer: 2, explanation: "Either/or → verb agrees with the NEARER subject. 'Staff' is closer to the verb, and here is/singular works either way — correct as written.", rule: "R2 — either/or, neither/nor → nearer subject.", trapcat: "Either/neither pairs - nearer trap", level: "L2 Application" },
    { q: "Neither the director nor the producer have agreed to the terms.", options: ["Neither the director nor the producer","No error","have agreed to the terms"], answer: 2, explanation: "Neither/nor → verb agrees with the NEARER subject. 'Producer' (singular) is nearer, so it should be 'has agreed'.", rule: "Neither/nor → verb agrees with nearer subject.", trapcat: "Neither/nor - singular/plural trap", level: "L3 Trap" },
    { q: "The manager together with his team is working on the project.", options: ["is working on the project","No improvement","The manager together with his team","No error"], answer: 3, explanation: "'Together with' keeps the subject singular — 'the manager...is working' is already correct.", rule: "R4 — as well as / together with does not pluralise the subject.", trapcat: "As well as / together with trap", level: "L2 Application" },
    { q: "She decided to go because it would give her more happiness.", options: ["because it would give her more happiness","No improvement","because it would make her much happier","She decided to go"], answer: 1, explanation: "'More + happiness' is fine because happiness is a noun, not an adjective — no improvement needed.", rule: "'More' + noun is fine; only comparative adjectives ban double 'more/-er'.", trapcat: "More + adjective/noun error", level: "L2 Application" },
    { q: "The scene was such that it moved everyone to tears.", options: ["that it moved everyone to tears","No error","No improvement","The scene was such"], answer: 2, explanation: "'Such...that' is the correct emphatic structure — no improvement needed.", rule: "Such + (that)... is a fixed emphatic pattern.", trapcat: "No error", level: "L1 Direct" },
    { q: "Hardly had I entered the room than the lights went out.", options: ["No error","No improvement","the room than the lights went out","Hardly had I entered"], answer: 2, explanation: "The correct correlative is 'Hardly...when', not 'than'.", rule: "Hardly/scarcely/barely + had + subject + verb + when (not than).", trapcat: "Conjunction error - than vs when", level: "L3 Trap" },
    { q: "The book is conducive ___ learning.", options: ["to","for","of","towards"], answer: 0, explanation: "'Conducive to' is the fixed expression. 'Conducive for' is a very common wrong-preposition error.", rule: "Conducive to + noun (purpose).", trapcat: "Preposition - conducive for (common error)", level: "L3 Trap" },
    { q: "She is superior ___ her sister in academic performance.", options: ["with","over","to","than"], answer: 2, explanation: "'Superior to' — one of the fixed exceptions that never take 'than'. Same family: senior to, junior to, inferior to, prior to.", rule: "Superior/senior/junior/inferior/prior + to (never than).", trapcat: "Comparison - superior than (common error)", level: "L2 Application" },
    { q: "The teacher divided the apples ___ the two students.", options: ["amongst","among","between among","between"], answer: 3, explanation: "'Between' = exactly two entities; 'among' = more than two.", rule: "Between = two entities; Among = more than two.", trapcat: "Between/among - count trap", level: "L2 Application" },
    { q: "Digital India initiative aims ___ transform the country into a knowledge economy. The programme focuses ___ providing digital infrastructure.", options: ["for, in","to, in","to, to","for, to"], answer: 1, explanation: "'Aims to' + infinitive; 'focuses on' + noun — but option A pairs 'to' with the second blank which is wrong on paper... correct fixed pairing is aims TO / focuses ON.", rule: "Aims to + infinitive; focuses on + noun.", trapcat: "Repeating same preposition by habit", level: "L2 Application" },
    { q: "The government launched a scheme ___ poor people ___ clean drinking water.", options: ["for, to get","for, providing","for, access to","to, for"], answer: 2, explanation: "'Scheme for' + beneficiaries; 'access to' + resource is the natural collocation.", rule: "Launch a scheme for (beneficiary); access to (resource).", trapcat: "Verb + preposition + noun pattern", level: "L2 Application" },
    { q: "He concentrates ___ his studies while neglecting outdoor games.", options: ["in","at","on","with"], answer: 2, explanation: "'Concentrate on' is the fixed verb-preposition pair; 'concentrate in' is a common error.", rule: "Concentrate on + noun/gerund.", trapcat: "Verb pattern - concentrate in (common error)", level: "L2 Application" },
    { q: "Please refer ___ the attachment for further details.", options: ["to","of","at","for"], answer: 0, explanation: "'Refer to' + noun. Adding a second preposition like 'refer for' is redundant/wrong.", rule: "Refer to + noun.", trapcat: "Redundant preposition", level: "L3 Trap" },
    { q: "Rearrange: A. The scientist accepted the award. B. He had made a groundbreaking discovery. C. The award was given for his research. D. Many people attended the ceremony.", options: ["A, B, C, D","B, A, C, D","D, B, A, C","C, D, A, B"], answer: 1, explanation: "Cause → effect ordering: Discovery (B) happens first, then acceptance (A), then the reason is explained (C), then the ceremony detail (D).", rule: "Effect follows cause: discovery → acceptance → reason → occasion.", trapcat: "Starting with the effect instead of cause", level: "L3 Trap" },
    { q: "Rearrange: A. The match was cancelled. B. Rain stopped play. C. Players left the field. D. Umpires decided.", options: ["A, D, B, C","A, B, C, D","B, D, A, C","D, B, A, C"], answer: 2, explanation: "Rain stops play (B) → umpires decide (D) → match is cancelled (A) → players leave (C).", rule: "Event sequencing: cause → decision → result → consequence.", trapcat: "Starting with result rather than cause", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: PARSIMONIOUS", options: ["Stingy","Punctual","Generous","Cautious"], answer: 0, explanation: "Parsimonious = excessively unwilling to spend money; stingy.", rule: "Vocabulary — parsimonious = stingy.", trapcat: "Word meaning", level: "L3 Trap" },
    { q: "Choose the word OPPOSITE in meaning: OBSTINATE", options: ["Stubborn","Rigid","Compliant","Headstrong"], answer: 2, explanation: "Obstinate = stubbornly refusing to change; opposite = compliant (willing to yield). Stubborn/Rigid/Headstrong are all SYNONYMS, deliberately placed as traps.", rule: "Antonym — obstinate ≠ compliant.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who is difficult to please or satisfy:", options: ["Fastidious","Loquacious","Credulous","Gregarious"], answer: 0, explanation: "Fastidious = excessively particular/hard to please. Gregarious = sociable, Credulous = too trusting, Loquacious = very talkative — all unrelated real words used as decoys.", rule: "One word substitution — fastidious.", trapcat: "Word meaning - specialization", level: "L3 Trap" },
    { q: "'He has a bee in his bonnet about the new project' means:", options: ["He is very angry","He is obsessed","He is confused","He is very excited"], answer: 1, explanation: "'Bee in one's bonnet' = obsessed or preoccupied with an idea, not anger.", rule: "Idiom: bee in one's bonnet = obsessed.", trapcat: "Idiom interpretation - anger vs obsession", level: "L3 Trap" },
    { q: "Convert to passive voice: The examiner will check all answer sheets.", options: ["All answer sheets will be checked by the examiner","Examiner will check all answer sheets","All answer sheets were checked by the examiner","All answer sheets are checked by the examiner"], answer: 0, explanation: "Future simple passive: object + will/shall + be + past participle + by subject.", rule: "Active → Passive: keep the tense; here future → will be + V3.", trapcat: "Voice conversion - tense maintenance", level: "L2 Application" },
    { q: "Convert to indirect speech: She said, \"I have completed the work.\"", options: ["She said that she had completed the work","She said that she has completed the work","She said that she had been completing the work","She said that she has been completed the work"], answer: 0, explanation: "Present perfect backshifts to past perfect after a past reporting verb: have/has → had.", rule: "Said that + past perfect (had + V3) for reported present perfect.", trapcat: "Tense backshifting - retaining have/has (common error)", level: "L3 Trap" }
  ]
},
{
  id: "sept30_m2", label: "30 Sep · Evening Full Mock", timeLimitMin: 20,
  questions: [
    { q: "By this time next year, she will have completed her project successfully.", options: ["her project successfully","No error","she will have completed","By this time next year"], answer: 1, explanation: "'Will have completed' is the correct future perfect form for an action finished before a future point.", rule: "Future perfect tense: will/shall + have + past participle.", trapcat: "Tense error", level: "L1 Direct" },
    { q: "The manager together with his team are working on the project.", options: ["The manager together with his team","are working on the project","No error"], answer: 1, explanation: "'Together with' keeps the subject singular → should be 'is working', not 'are working'.", rule: "R4 — together with / as well as does not pluralise the subject.", trapcat: "As well as trap", level: "L2 Application" },
    { q: "Neither the director nor the producers have agreed to the terms.", options: ["Neither the director nor the producers","No error","have agreed to the terms"], answer: 1, explanation: "Neither/nor agrees with the nearer subject. 'Producers' (plural) is nearer, so 'have agreed' is already correct.", rule: "Neither/nor → verb agrees with nearer subject.", trapcat: "Neither/nor agreement", level: "L2 Application" },
    { q: "One of the candidates who are eligible for the interview must report.", options: ["for the interview must report","No error","One of the candidates who are eligible"], answer: 1, explanation: "'One of + plural noun + who' takes a plural verb after 'who' — 'are eligible' is correct.", rule: "One of + plural + who/that → plural verb after who.", trapcat: "One of + who (correct usage)", level: "L2 Application" },
    { q: "The list of requirements were submitted yesterday.", options: ["The list of requirements","were submitted yesterday","No error"], answer: 1, explanation: "'The list' is the true singular subject — should be 'was submitted', not 'were submitted'.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "He has been keeping bad company since childhood.", options: ["No error","No improvement","bad company since childhood","He has been keeping"], answer: 1, explanation: "'Keeping bad company' = associating with bad people — correct idiom, no error.", rule: "Idiom: keep (bad) company = associate with.", trapcat: "No error", level: "L1 Direct" },
    { q: "If I were you, I would have accepted the offer.", options: ["No error","I would have accepted","would accept","If I were you"], answer: 1, explanation: "This mixes a present-unreal condition ('if I were you') with a past-unreal result ('would have accepted'), which is inconsistent — a pure present-unreal needs 'would accept'.", rule: "Second conditional: If + were, would + base verb (not would have + V3).", trapcat: "Mixed conditional error", level: "L3 Trap" },
    { q: "Choose the correctly punctuated sentence.", options: ["\"Where are you going\"? she asked.","\"Where are you going,\" she asked?","Where are you going? she asked.","\"Where are you going?\" she asked."], answer: 3, explanation: "The question mark sits inside the closing quotation mark, and the quoted sentence itself starts with a capital letter.", rule: "Direct-speech punctuation: ?/! stays inside the quotes when it belongs to the quoted sentence.", trapcat: "Punctuation", level: "L2 Application" },
    { q: "She is not only intelligent but also hardworking.", options: ["but also hardworking","She is not only intelligent","No error","but hardworking too"], answer: 2, explanation: "'Not only...but also' is correctly and fully used — no error.", rule: "Correlative conjunction: not only...but also.", trapcat: "No error", level: "L1 Direct" },
    { q: "Scarcely had the show begun before the lights went out.", options: ["before the lights went out","No error","when the lights went out","Scarcely had the show begun"], answer: 0, explanation: "'Scarcely...when' (or 'scarcely...than' is wrong) — the correct pairing is 'scarcely...when', so 'before' needs correcting.", rule: "Scarcely/hardly/barely + had + subject + V3 + when.", trapcat: "Correlative conjunction", level: "L2 Application" },
    { q: "The board decided to dispense ___ the formal interview, having grown weary ___ the lengthy hiring process.", options: ["with, with","from, of","of, with","with, of"], answer: 3, explanation: "'Dispense with' = do away with/no longer require. 'Weary of' = tired of. Both fixed pairs, deliberately not matching (with, of), not the same preposition repeated.", rule: "Dispense with + weary of (distinct fixed pairs).", trapcat: "Preposition - less common pairs", level: "L3 Trap" },
    { q: "Despite his best efforts, he could not prevail ___ the committee to reconsider its decision, and eventually had to acquiesce ___ their verdict.", options: ["upon, in","over, with","on, to","upon, to"], answer: 0, explanation: "'Prevail upon someone' = persuade them; 'acquiesce in' = reluctantly accept. Both are fixed but less-common pairs, easily confused with the more familiar 'agree to' pattern.", rule: "Prevail upon + acquiesce in (less common fixed pairs).", trapcat: "Preposition - less common pairs", level: "L3 Trap" },
    { q: "The court awarded the prize ___ the best performer, whose talent was widely acknowledged ___ the entire panel of judges.", options: ["to, from","for, by","of, to","to, by"], answer: 3, explanation: "'Award something TO someone' + passive 'acknowledged BY' (the agent of a passive verb). Both blanks test different fixed patterns in the same sentence.", rule: "Award to + recipient; passive verb + by + agent.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Poverty ___ villagers ___ migrate to cities every year.", options: ["makes, to","compels, for","forces, for","forces, to"], answer: 3, explanation: "'Force someone to do something' is the fixed causative pattern.", rule: "Force + object + to + verb.", trapcat: "Verb pattern", level: "L2 Application" },
    { q: "The NGO works ___ upliftment of the poor ___ education and healthcare.", options: ["towards, by","for, via","for, through","to, through"], answer: 2, explanation: "'Work for' + goal; 'through' + method — the natural formal collocation.", rule: "Work for (goal) + through (method).", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Rearrange: A. The teacher explained the concept. B. Students listened carefully. C. The concept was difficult. D. Doubts were cleared.", options: ["B, C, A, D","C, A, B, D","A, B, C, D","D, A, B, C"], answer: 1, explanation: "The concept is difficult (C) → teacher explains it (A) → students listen (B) → doubts get cleared (D).", rule: "Cause-effect + explanation + feedback ordering.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Rearrange: A. The clouds gathered. B. It started to rain. C. Farmers rejoiced. D. The crops were saved.", options: ["A, B, D, C","D, C, B, A","B, A, C, D","A, B, C, D"], answer: 0, explanation: "Clouds gather (A) → rain starts (B) → crops are saved (D) → farmers rejoice (C, the emotional result comes last).", rule: "Physical cause-effect chain before emotional reaction.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: MUNIFICENT", options: ["Magnanimous","Miserly","Modest","Malicious"], answer: 0, explanation: "Munificent = extremely generous → magnanimous. A frequent SSC 2024 trap word — many incorrectly pick 'miserly' by sound association.", rule: "Vocabulary — munificent = very generous.", trapcat: "Word meaning", level: "L3 Trap" },
    { q: "Choose the word opposite in meaning: FRUGAL", options: ["Thrifty","Economical","Careful","Extravagant"], answer: 3, explanation: "Frugal = careful with money/resources; opposite = extravagant (wasteful spending).", rule: "Antonym — frugal ≠ extravagant.", trapcat: "Word meaning", level: "L2 Application" },
    { q: "One who is unable to pay their debts:", options: ["Indolent","Inherent","Insolvent","Innocent"], answer: 2, explanation: "Cannot pay debts → insolvent (bankrupt).", rule: "One word substitution — insolvent.", trapcat: "Word meaning - specialization", level: "L2 Application" },
    { q: "Choose the correctly spelt word.", options: ["Necessary","Neccessary","Nessecary","Necesary"], answer: 0, explanation: "'Necessary' has one C and two Ss — the opposite of the usual double-letter guess pattern, which is why it's a common trap.", rule: "Spelling: 'necessary' = 1 C, 2 S (Never Eat Cake, Eat Sweet Stuff Sally mnemonic works too).", trapcat: "Spelling", level: "L2 Application" },
    { q: "'She broke the ice at the party' means:", options: ["She froze literally","She initiated conversation","She left the party","She slipped on ice"], answer: 1, explanation: "'Break the ice' = initiate conversation / relieve social tension.", rule: "Idiom: break the ice.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: The committee has elected a new president.", options: ["A new president has been elected by the committee","New president has been elected by the committee","A new president is elected by the committee","A new president was elected by the committee"], answer: 0, explanation: "Present perfect passive: has/have + been + past participle + by subject.", rule: "Active → Passive: keep the tense; present perfect → has been + V3.", trapcat: "Voice conversion", level: "L2 Application" },
    { q: "Convert to active voice: The letter was written by Ravi yesterday.", options: ["Ravi writes the letter yesterday","Ravi wrote the letter yesterday","Ravi had written the letter yesterday","Ravi has written the letter yesterday"], answer: 1, explanation: "Was + V3 → simple past active; 'yesterday' confirms simple past, not perfect.", rule: "Passive → active: keep the tense (was + V3 → simple past).", trapcat: "Voice conversion - tense maintenance", level: "L2 Application" },
    { q: "Convert to indirect speech: The teacher said, \"Honesty is the best policy.\"", options: ["The teacher said that honesty is best policy","The teacher said that honesty was the best policy","The teacher said that honesty is the best policy","The teacher said honesty is the best policy"], answer: 2, explanation: "Universal truths and proverbs keep present tense in reported speech — no backshifting.", rule: "Universal truth/proverb → no backshift, keep present tense.", trapcat: "Speech conversion", level: "L2 Application" }
  ]
},
{
  id: "sept30_m3", label: "30 Sep · Maths Mock", timeLimitMin: 25,
  questions: [
/* ======================================
   PERCENTAGE (Q1-Q3)
   ====================================== */

  /* Q1: Percentage - basic */
  { q: "40% of 250 + 20% of 150 = ?", options: ["130","110","140","120"], answer: 0, explanation: "40% of 250 = 100; 20% of 150 = 30; 100 + 30 = 130.", rule: "Percentage of number: (percentage/100) × number.", trapcat: "Calculation error", level: "L1 Direct" },
  { q: "If 30% of a number is 45, the number is:", options: ["135","180","150","120"], answer: 2, explanation: "Number × 30/100 = 45 → Number = 45 × 100/30 = 150.", rule: "Reverse percentage: number = value × 100/%.", trapcat: "Reverse calculation", level: "L1 Direct" },
  { q: "A number increased by 15% gives 345. The original number is:", options: ["350","300","280","320"], answer: 1, explanation: "Original × 1.15 = 345 → Original = 345/1.15 = 300. Shortcut: 345/115 × 100 = 300.", rule: "Percentage increase reverse calculation.", trapcat: "Percentage increase", level: "L1 Direct" },

/* ======================================
   RATIO & PROPORTION (Q4-Q5)
   ====================================== */

  { q: "If a:b = 3:4 and b:c = 5:7, then a:c = ?", options: ["5:28","15:28","3:7","12:35"], answer: 1, explanation: "a:c = a:b × b:c ÷ b = 3:4 × 5:7 = (3×5):(4×7) = 15:28 (after eliminating b).", rule: "Chain ratio: a:c = (a:b × b:c) / b.", trapcat: "Ratio chain", level: "L2 Application" },
  { q: "If x:y = 2:3, then (3x+2y):(2x+y) = ?", options: ["10:7","13:7","12:7","11:7"], answer: 2, explanation: "Substitute x=2k, y=3k: (3×2k+2×3k):(2×2k+3k) = (6k+6k):(4k+3k) = 12k:7k = 12:7.", rule: "Ratio substitution with variable k.", trapcat: "Ratio algebra", level: "L2 Application" },

/* ======================================
   AVERAGE (Q6-Q7)
   ====================================== */

  { q: "The average of 10 numbers is 25. If each number is increased by 5, the new average is:", options: ["20","30","25","35"], answer: 1, explanation: "If each number increased by 5, the average also increases by 5 → 25+5 = 30.", rule: "Average adjustment: new avg = old avg ± change.", trapcat: "Average property", level: "L1 Direct" },
  { q: "The average weight of 8 persons increases by 1.5 kg when a new person replaces one of them weighing 68 kg. What is the weight of the new person?", options: ["80","70","75","85"], answer: 0, explanation: "Total increase = 8 × 1.5 = 12 kg. New person's weight = 68 + 12 = 80 kg exactly.", rule: "Average increase × count = total weight change; add that to the replaced person's weight.", trapcat: "Average with replacement", level: "L2 Application" },

/* ======================================
   PROFIT & LOSS (Q8-Q9)
   ====================================== */

  { q: "An article is sold for Rs. 595 at a loss of 15%. What is the cost price?", options: ["Rs. 650","Rs. 600","Rs. 700","Rs. 750"], answer: 2, explanation: "CP = SP × 100/(100-loss%) = 595 × 100/85 = Rs. 700 exactly.", rule: "Cost price = Selling price × 100/(100−loss%).", trapcat: "Profit-loss calculation", level: "L2 Application" },
  { q: "A trader marks his goods 40% above cost price and allows 25% discount. His gain percent is:", options: ["10%","20%","5%","15%"], answer: 2, explanation: "CP = 100, Marked Price = 140, SP = 140 × 0.75 = 105, Gain = 5%. Rule: Marked price discount chain.", trapcat: "Profit-loss with discount", level: "L2 Application" },

/* ======================================
   DISCOUNT (Q10)
   ====================================== */

  { q: "Marked price of a table is Rs. 800 and discount offered is 15%. Selling price is:", options: ["Rs. 680","Rs. 720","Rs. 740","Rs. 700"], answer: 0, explanation: "SP = MP × (1 - discount%) = 800 × 0.85 = Rs. 680.", rule: "Selling price = Marked price × (1 − discount%).", trapcat: "Discount calculation", level: "L1 Direct" },

/* ======================================
   SI & CI (Q11-Q12)
   ====================================== */

  { q: "The simple interest on Rs. 1500 for 3 years at 5% per annum is:", options: ["Rs. 300","Rs. 150","Rs. 225","Rs. 175"], answer: 2, explanation: "SI = P × R × T/100 = 1500 × 5 × 3/100 = Rs. 225.", rule: "Simple interest formula.", trapcat: "SI calculation", level: "L1 Direct" },
  { q: "The compound interest on Rs. 1000 at 5% per annum for 2 years compounded annually is:", options: ["Rs. 100","Rs. 50","Rs. 102.50","Rs. 105"], answer: 2, explanation: "CI = P(1+R/100)^T − P = 1000(1.05)^2 − 1000 = 1000×1.1025 − 1000 = Rs. 102.50.", rule: "Compound interest formula annually.", trapcat: "CI calculation", level: "L1 Direct" },

/* ======================================
   MIXTURE & ALLIGATION (Q13)
   ====================================== */

  { q: "In what ratio must rice at Rs. 10 per kg be mixed with rice at Rs. 15 per kg to get a mixture worth Rs. 12 per kg?", options: ["2:1","2:3","3:2","1:2"], answer: 2, explanation: "By alligation: (15-12):(12-10) = 3:2. Ratio = 3:2 (dearer:cheaper).", rule: "Alligation method: (d-c):(m-d) where d=dearer, c=cheaper, m=mean.", trapcat: "Alligation", level: "L2 Application" },

/* ======================================
   PARTNERSHIP (Q14)
   ====================================== */

  { q: "A and B invest in a business in the ratio 3:2. If 5% of the total profit goes to charity and A's share (from the remaining 95%) is Rs. 1140, the total profit is:", options: ["Rs. 2000","Rs. 3000","Rs. 2500","Rs. 3500"], answer: 0, explanation: "After charity, 95% of the profit remains. A's share = (3/5) × 95% = 57% of total profit. So 0.57 × Total = 1140 → Total = 1140/0.57 = Rs. 2000 exactly.", rule: "Partnership profit sharing with a charity deduction taken off first, then split by investment ratio.", trapcat: "Partnership with charity", level: "L3 Trap" },
  { q: "A and B enter into partnership. A invests Rs. 20,000 for 6 months and B invests Rs. 15,000 for 8 months. Out of total profit, A gets Rs. 1200. What is 20% of total profit?", options: ["Rs. 500","Rs. 540","Rs. 480","Rs. 520"], answer: 2, explanation: "A's capital-months = 20000 × 6 = 120000; B's = 15000 × 8 = 120000. Ratio = 1:1. A's share = 1/2 of profit = 1200 → Total = 2400. 20% of total = 480.", rule: "Partnership: profit ratio = capital × time.", trapcat: "Partnership capital-time", level: "L2 Application" },

/* ======================================
   AGES (Q15)
   ====================================== */

  { q: "The ratio of ages of A and B is 3:5 and their sum is 64. Age of A after 4 years will be:", options: ["32","36","40","28"], answer: 3, explanation: "A's share = 3/8 × 64 = 24. After 4 years = 24 + 4 = 28.", rule: "Age ratio with sum.", trapcat: "Age calculation", level: "L1 Direct" },

/* ======================================
   TIME & WORK (Q16-Q17)
   ====================================== */

  { q: "A can complete a work in 10 days and B in 15 days. Working together, they will complete the work in:", options: ["6 days","12 days","10 days","8 days"], answer: 0, explanation: "A's 1 day work = 1/10, B's 1 day work = 1/15. Together = 1/10 + 1/15 = 5/30 = 1/6. So 6 days.", rule: "Work together: 1/A + 1/B = 1/Combined time.", trapcat: "Time and work", level: "L1 Direct" },
  { q: "A and B together can complete a work in 6 days. A alone can do it in 9 days. B alone can do it in:", options: ["20 days","12 days","18 days","15 days"], answer: 2, explanation: "Together 1 day = 1/6; A alone 1 day = 1/9; B alone 1 day = 1/6 - 1/9 = 3/18 - 2/18 = 1/18 → 18 days.", rule: "Work efficiency: combined - one = other.", trapcat: "Time and work", level: "L1 Direct" },

/* ======================================
   PIPES & CISTERNS (Q18)
   ====================================== */

  { q: "Pipe A can fill a tank in 4 hours and Pipe B in 6 hours. If both pipes are opened together, the tank will be filled in:", options: ["2.4 hours","4.5 hours","5 hours","3 hours"], answer: 0, explanation: "A's rate = 1/4, B's rate = 1/6. Together = 1/4 + 1/6 = 5/12 → time = 12/5 = 2.4 hours.", rule: "Pipes together: 1/A + 1/B = 1/Time.", trapcat: "Pipes and cisterns", level: "L1 Direct" },

/* ======================================
   TIME, SPEED & DISTANCE (Q19-Q20)
   ====================================== */

  /* Q19: Average speed - FIXED */
  { q: "A train travels at 60 km/h for 2 hours and at 80 km/h for 3 hours. Average speed is:", options: ["72 km/h","65 km/h","68 km/h","70 km/h"], answer: 0, explanation: "Total distance = 60×2 + 80×3 = 120 + 240 = 360 km. Total time = 5 h. Average speed = Total distance / Total time = 360/5 = 72 km/h. Key concept: Average speed = total distance ÷ total time (NOT average of two speeds).", trapcat: "Average speed trap - using (s1+s2)/2", level: "L2 Application" },
  
  /* Q20: Round trip - FIXED */
  { q: "A person covers a distance at 5 km/h and returns at 4 km/h. If total time taken is 9 hours, the distance is:", options: ["16 km","22 km","20 km","18 km"], answer: 2, explanation: "Let distance = d. Time1 = d/5, Time2 = d/4. Total time = d/5 + d/4 = (4d+5d)/20 = 9d/20 = 9 → d = 20 km. Key concept: In round trips, use formula 2xy/(x+y) for average speed, or solve directly as done here.", trapcat: "Round trip speed trap - using wrong formula", level: "L2 Application" },
]
},
{
  id: "sept30_m4", label: "30 Sep · Extreme GS Mock", timeLimitMin: 30,
  questions: [
/* ======================================
   HISTORY - ANCIENT & MEDIEVAL (Q1-Q5)
   ====================================== */

  /* Q1: Statement-based - Easy/Moderate */
  { q: "Consider the following statements: 1. The Indus Valley Civilization had a well-planned drainage system. 2. The Great Bath was used for religious rituals. Which of the above is/are correct?", options: ["1 only","2 only","Both 1 and 2","Neither 1 nor 2"], answer: 2, explanation: "Correct: Both statements are true. The Indus Valley Civilization (Harappan) had advanced urban planning including covered drains. The Great Bath at Mohenjo-daro was indeed used for ritualistic/bathing purposes. SSC trick: Sometimes students think drainage system was Mesopotamian, but it's Indus Valley.", rule: "Indus Valley urban planning included drainage and water structures.", trapcat: "Confusing with Mesopotamian civilization", level: "L2 Application" },
  { q: "Consider the following statements: 1. Gautama Buddha belonged to the Shakya clan. 2. Buddha gave his first sermon at Sarnath. Which of the above is/are correct?", options: ["Both 1 and 2","Neither 1 nor 2","1 only","2 only"], answer: 0, explanation: "Correct: Both statements are true. Buddha was indeed a Shakya prince, and his first sermon (Dharmachakra Pravartana) was at Sarnath near Varanasi. This tests basic Buddhist history.", rule: "Buddha's clan and first sermon location.", trapcat: "Confusing with Mahavira's teachings", level: "L1 Direct" },
  { q: "Consider the following statements: 1. The Gupta period is known as the Golden Age of India. 2. Chandragupta II Vikramaditya was a famous Gupta ruler. Which of the above is/are correct?", options: ["Neither 1 nor 2","1 only","2 only","Both 1 and 2"], answer: 3, explanation: "Correct: Both statements are true. Gupta period (c. 320-550 CE) is renowned for cultural, scientific, and literary achievements - hence 'Golden Age'. Chandragupta II was indeed a prominent ruler.", rule: "Gupta period achievements in science, math, arts.", trapcat: "Calling other periods 'Golden Age'", level: "L2 Application" },
  { q: "Consider the following statements: 1. Harsha Vardhana succeeded the throne of Kannauj. 2. Harsha Vardhana sent an embassy to China. Which of the above is/are correct?", options: ["2 only","1 only","Both 1 and 2","Neither 1 nor 2"], answer: 2, explanation: "Correct: Both statements are true. Harsha (c. 606-647 CE) succeeded Kannauj and had diplomatic relations with China's Tang dynasty. This tests medieval Indian history.", rule: "Harsha Vardhana's reign and foreign relations.", trapcat: "Confusing with Pallava or Chalukya relations", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Bhakti movement originated in South India. 2. The Alvars and Nayanars were Bhakti saint-poets. Which of the above is/are correct?", options: ["2 only","Both 1 and 2","1 only","Neither 1 nor 2"], answer: 1, explanation: "Correct: Both statements are true. Bhakti movement originated in Tamil Nadu/Karnataka region (7th-8th century). Alvars (Vishnu devotees) and Nayanars (Shiva devotees) were the saint-poets who propagated Bhakti.", rule: "Bhakti movement origin and Alvars/Nayanars.", trapcat: "Confusing with Sufi movement origin", level: "L2 Application" },

/* ======================================
   HISTORY - MODERN INDIA (Q6-Q10)
   ====================================== */

  /* Q6: Chronology - Hard */
  { q: "Arrange the following events chronologically: 1. Quit India Movement 2. Champaran Satyagraha 3. Non-Cooperation Movement 4. Partition of Bengal", options: ["4, 2, 3, 1","4, 3, 2, 1","2, 3, 4, 1","2, 4, 3, 1"], answer: 0, explanation: "Chronological order: Partition of Bengal (1905) → Champaran Satyagraha (1917) → Non-Cooperation Movement (1920-22) → Quit India Movement (1942). Key SSC trick: Many students reverse the order of Non-Cooperation and Quit India.", rule: "Indian National Movement chronology.", trapcat: "Reversing Non-Cooperation and Quit India chronology", level: "L3 Trap" },
  { q: "Consider the following pairs: 1. Maharana Pratap - Battle of Haldighati 2. Shivaji - Treaty of Purandar 3. Rani Lakshmibai - Siege of Jhansi Which of the above pairs are correctly matched?", options: ["1 and 3 only","1 and 2 only","1, 2 and 3","2 and 3 only"], answer: 2, explanation: "Correct: All three pairs are correctly matched. Maharana Pratap fought the Battle of Haldighati (1568) against Akbar. Shivaji signed the Treaty of Purandar (1665) with Mughal emperor Aurangzeb. Rani Lakshmibai died during the Siege of Jhansi (1858) in the 1857 Rebellion. This tests historical person-event pairing.", rule: "Indian freedom fighters and their associated events/ battles.", trapcat: "Incorrect pairing like Rani with Chanderi", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Rowlatt Act was passed in 1919. 2. The Jallianwala Bagh massacre happened in 1919. 3. The Non-Cooperation Movement was launched in 1920. Which of the above is/are correct?", options: ["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"], answer: 3, explanation: "All three statements are correct. The Rowlatt Act was passed in 1919, the Jallianwala Bagh massacre occurred in April 1919, and the Non-Cooperation Movement was launched in September 1920.", rule: "Rowlatt Act (1919) → Jallianwala Bagh (1919) → Non-Cooperation (1920).", trapcat: "Assuming one of three correct-sounding statements must be the 'trap'", level: "L3 Trap" },
  { q: "Consider the following statements: 1. Subhas Chandra Bose formed the Indian National Army. 2. INA's slogan was 'Delhi Chalo'. 3. INA was formed during World War II. Which of the above is/are correct?", options: ["2 and 3 only","1 and 2 only","1, 2 and 3","1 and 3 only"], answer: 2, explanation: "Correct: All three statements are true. Subhas Chandra Bose indeed formed the INA (Azad Hind Fauj) with Japanese support. The slogan 'Delhi Chalo' was the INA's call. INA was formed during WWII (1942). This tests modern Indian history with freedom struggle details.", rule: "Subhas Chandra Bose and INA details.", trapcat: "Confusing INA with earlier revolutionary groups", level: "L2 Application" },

/* ======================================
   POLITY - CONSTITUTION (Q11-Q15)
   ====================================== */

  /* Q11: Assertion-Reason - Hard */
  { q: "Assertion (A): Article 32 is the soul and heart of the Constitution. Reason (R): Article 32 gives the right to move to the Supreme Court for the enforcement of Fundamental Rights.", options: ["Both A and R are true and R is the correct explanation of A","A is false but R is true","Both A and R are true but R is not the correct explanation of A","A is true but R is false"], answer: 0, explanation: "Correct: Both are true and R is the correct explanation. Dr. B.R. Ambedkar described Article 32 as the 'soul' of the Constitution. Article 32 gives the right to move to SC for FR enforcement, including writs like habeas corpus, mandamus, prohibition, quo warranto and certiorari. Key exam tip: In AR questions, if both statements are textbook definitions, often both are true with R explaining A.", rule: "Article 32 as soul of Constitution + FR enforcement.", trapcat: "AR question trap - R appears true but doesn't explain A", level: "L3 Trap" },
  { q: "Assertion (A): The Indian Parliament can legislate on any subject in the State List during Emergency. Reason (R): Under Article 352, the State Legislatures are automatically dissolved.", options: ["A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true","Both A and R are true and R is the correct explanation of A"], answer: 0, explanation: "Correct: A is true - during National Emergency (Art. 352), Parliament can legislate on State List subjects. But R is false - State Legislatures are NOT automatically dissolved during Emergency. They continue to function. This is a common misconception that SSC often tests.", rule: "Emergency provisions and State Legislative powers.", trapcat: "Emergency - false notion of State Legislature dissolution", level: "L3 Trap" },
  { q: "Assertion (A): The Rajya Sabha is called the Upper Chamber of the Indian Parliament. Reason (R): The Rajya Sabha members are elected by the State Legislative Assemblies through proportional representation.", options: ["A is true but R is false","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is false but R is true"], answer: 2, explanation: "Correct: Both are true and R correctly explains A. Rajya Sabha is the Upper Chamber ( Lok Sabha is Lower). Members are indeed elected by MLAs via STV (Single Transferable Vote) system of PR. The 'explains' connection: being elected by state MLAs is what makes it the Upper Chamber representing states.", rule: "Rajya Sabha composition and election method.", trapcat: "AR question - R true but doesn't explain A (common trap)", level: "L2 Application" },
  { q: "Assertion (A): The President of India can promulgate Ordinances under Article 123. Reason (R): The President can promulgate Ordinances when either House of Parliament is not in session.", options: ["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true","A is true but R is false"], answer: 0, explanation: "Correct: Both are true and R is the correct explanation. Article 123 gives the President ordinance-making power when either Lok Sabha or Rajya Sabha is not in session. Key detail: Both Houses not in session required, or just one? Actually President can act when either House is not in session. This tests precise constitutional knowledge.", rule: "Article 123 Ordinance-making power.", trapcat: "AR - President needs both Houses not in session (common misconception)", level: "L3 Trap" },
  { q: "Assertion (A): The Indian Constitution provides for single citizenship. Reason (R): Unlike USA or Switzerland, India does not have dual citizenship at Central and State levels.", options: ["A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false"], answer: 2, explanation: "Correct: Both are true and R is the correct explanation. Indian Constitution (Part II, Articles 5-11) provides single citizenship - being a citizen of India, not of a particular state. Unlike US (federal + state citizenship) or Switzerland (citizenship of canton + country). R explains A by contrasting with other countries.", rule: "Single citizenship vs dual citizenship countries.", trapcat: "AR - comparing with US/Switzerland", level: "L2 Application" },

/* ======================================
   POLITY - GOVERNANCE (Q16-Q20)
   ====================================== */

  /* Q16: Matching question */
  { q: "Match List I with List II and select the correct answer using the code given below the lists: List I (Body): A. NITI Aayog B. CAG C. Finance Commission D. Election Commission List II (Function): 1. Financial audit of Centre and States 2. Policy think-tank 3. Election management 4. Resource distribution between Centre and States", options: ["A-2 B-3 C-1 D-4","A-2 B-1 C-3 D-4","A-1 B-2 C-3 D-4","A-2 B-1 C-4 D-3"], answer: 3, explanation: "Matching: NITI Aayog (National Institution for Transforming India) is a policy think-tank replacing Planning Commission. CAG (Comptroller and Auditor General) does financial audit. Finance Commission handles resource distribution between Centre and States. Election Commission manages elections. Code: A-2, B-1, C-4, D-3. SSC tests matching-based questions from governance structure.", rule: "Governance bodies and their functions matching.", trapcat: "Misplacing CAG with Election Commission", level: "L3 Trap" },
  { q: "Match List I with List II and select the correct code: List I (Committee/Commission): A. Sarkaria Commission B. Santhanam Committee C. Balwant Rai Mehta Committee D. Mandal Commission. List II (Related to): 1. Prevention of corruption 2. Centre-State relations 3. Backward classes reservation 4. Panchayati Raj", options: ["A-2 B-1 C-4 D-3","A-4 B-1 C-2 D-3","A-2 B-1 C-3 D-4","A-1 B-2 C-3 D-4"], answer: 0, explanation: "Sarkaria Commission (1983) examined Centre-State relations. Santhanam Committee (1962-64) addressed prevention of corruption. Balwant Rai Mehta Committee (1957) recommended the three-tier Panchayati Raj system. Mandal Commission (1979) addressed backward classes reservation. Code: A-2, B-1, C-4, D-3.", rule: "Major post-independence committees/commissions and their subject areas.", trapcat: "Confusing Sarkaria (Centre-State relations) with other federalism-related bodies", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Finance Commission is constituted every five years. 2. The Finance Commission recommends the distribution of net proceeds of taxes between the Union and the States. 3. The Finance Commission determines the principles governing the grants-in-aid of the revenue of the States. Which of the above is/are correct?", options: ["2 and 3 only","1, 2 and 3","1 and 3 only","1 and 2 only"], answer: 1, explanation: "Correct: All three statements are true. Finance Commission (Article 280) is constituted by the President every five years (or sooner). It recommends: (a) distribution of taxes, (b) principles of grants-in-aid. This is a staple SSC question on financial federalism.", rule: "Finance Commission duties under Article 280.", trapcat: "Confusing with Planning Commission (now replaced by NITI Aayog)", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Comptroller and Auditor General of India can be removed by the President on the recommendation of the Supreme Court. 2. The salary and conditions of service of CAG shall not be varied to his disadvantage after appointment. Which of the above is/are correct?", options: ["2 only","1 only","Neither 1 nor 2","Both 1 and 2"], answer: 0, explanation: "Statement 1 is false: the CAG is removed in the SAME MANNER as a Supreme Court judge (Presidential order after a Parliamentary address with special majority, on grounds of proved misbehaviour or incapacity) — the Supreme Court does not 'recommend' the removal. Statement 2 is true: under Article 148, the CAG's salary and conditions of service cannot be varied to his disadvantage after appointment, to protect independence.", rule: "CAG removal follows the SC-judge PROCEDURE, not an SC recommendation; service conditions are separately protected.", trapcat: "CAG removal procedure — 'same manner as' vs 'on recommendation of'", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Election Commission of India is a multi-member body. 2. The Election Commission decides the election symbols allotted to political parties. 3. The Election Commission can disqualify a member elected to Parliament. Which of the above is/are correct?", options: ["1, 2 and 3","2 and 3 only","1 and 2 only","1 and 3 only"], answer: 0, explanation: "Correct: All three statements are true. ECI is a multi-member body (Chief Election Commissioner + 2 Election Commissioners). ECI allots election symbols. ECI can disqualify candidates under anti-defection law and other provisions. This tests election governance knowledge.", rule: "Election Commission of India powers and composition.", trapcat: "Confusing ECI with State Election Commissions", level: "L2 Application" },

/* ======================================
   GEOGRAPHY - INDIA (Q21-Q25)
   ====================================== */

  /* Q21: Statement-based - Hard */
  { q: "Consider the following statements: 1. The Great Himalayan Range forms the northern boundary of India. 2. The Peninsular Plateau is rich in mineral resources. 3. The Indian Desert lies towards the western margins of the Aravalli hills. Which of the above is/are correct?", options: ["1, 2 and 3","2 and 3 only","1 and 2 only","1 and 3 only"], answer: 0, explanation: "Correct: All three statements are true. The Himalayas form the northern boundary. The Peninsular Plateau (Deccan Plateau) is mineral-rich. The Thar Desert lies west of the Aravallis. This tests physical geography of India.", rule: "India's physical geography features.", trapcat: "Confusing Western Ghats with Himalayas", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Chambal River is a tributary of the Yamuna. 2. The Godavari River is the longest peninsular river. 3. The Krishna River flows eastwards into the Bay of Bengal. Which of the above is/are correct?", options: ["1 and 2 only","1, 2 and 3","1 and 3 only","2 and 3 only"], answer: 1, explanation: "Correct: All three are true. Chambal is a Yamuna tributary. Godavari (1465 km) is the longest peninsular river. Krishna flows east into Bay of Bengal. SSC often tests river systems and their directions.", rule: "Major Indian river systems and directions.", trapcat: "River direction confusion (West-flowing vs East-flowing)", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Southwest Monsoon occurs from June to September. 2. The Northeast Monsoon occurs from October to December. 3. India's average annual rainfall is less than 100 cm. Which of the above is/are correct?", options: ["1, 2 and 3","1 and 3 only","1 and 2 only","2 and 3 only"], answer: 2, explanation: "Correct: Statements 1 and 2 are true, but Statement 3 is false. India's average annual rainfall is actually around 120 cm (varies regionally: Cherrapunji gets >1100 cm, Rajasthan <50 cm). Average is >100 cm. This is a common SSC trick - students memorise 'India receives monsoon rainfall' but forget the average rainfall figure.", rule: "Indian monsoon and rainfall patterns.", trapcat: "Incorrect average rainfall figure (100 cm vs actual ~120 cm)", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Andaman and Nicobar Islands are of volcanic origin. 2. The Lakshadweep Islands are coral islands. 3. The highest peak of Andaman is Saddle Peak. Which of the above is/are correct?", options: ["2 and 3 only","1 and 2 only","1, 2 and 3","1 and 3 only"], answer: 0, explanation: "Correct: Statements 2 and 3 are true. Lakshadweep is indeed coral islands. Saddle Peak (732 m) is the highest in Andaman. Statement 1 is false - Andaman-Nicobar are not volcanic origin but emerged due to tectonic uplift. This tests detailed geographical knowledge.", rule: "Indian islands - volcanic vs coral origin.", trapcat: "Andaman-Nicobar volcanic origin (common misconception)", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Western Ghats are older than the Himalayas. 2. The Western Ghats form the western boundary of the Deccan Plateau. 3. The Eastern Ghats are discontinuous and irregular. Which of the above is/are correct?", options: ["1 and 2 only","1, 2 and 3","1 and 3 only","2 and 3 only"], answer: 1, explanation: "Correct: All three statements are true. Western Ghats (old fold mountains) are indeed older than Himalayas (young fold mountains). They form the western edge of Deccan Plateau. Eastern Ghats are indeed discontinuous and irregular, following the coast. This tests peninsular plateau geography.", rule: "Peninsular India's mountain ranges and their characteristics.", trapcat: "Eastern Ghats continuity misconception", level: "L2 Application" },
]
},
{
  id: "oct1_m1", label: "1 Oct · Morning Full English Mock", timeLimitMin: 20,
  questions: [
    { q: "Each of the two witnesses have given a different account of the incident.", options: ["of the incident","a different account","Each of the two witnesses","have given"], answer: 3, explanation: "'Each' is always singular — should be 'has given', not 'have given'.", rule: "Each/every + plural noun → singular verb.", trapcat: "Subject-verb agreement", level: "L2 Application" },
    { q: "The panel of judges are known for their strict standards.", options: ["No error","for their strict standards","The panel of judges","are known"], answer: 3, explanation: "'Panel' is singular here (acting as one body) — should be 'is known', not 'are known'.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "Neither the singer nor the dancers was ready for the show.", options: ["for the show","Neither the singer nor the dancers","No error","was ready"], answer: 3, explanation: "Neither/nor agrees with the nearer subject. 'Dancers' (plural) is nearer, so it should be 'were ready', not 'was ready'.", rule: "Neither/nor → verb agrees with nearer subject.", trapcat: "Neither/nor - singular/plural trap", level: "L3 Trap" },
    { q: "One of the reasons for his success are his discipline.", options: ["are his discipline","One of the reasons","for his success","No error"], answer: 0, explanation: "'One of' is the true subject and is singular — should be 'is his discipline', not 'are'.", rule: "One of + plural noun → singular verb.", trapcat: "One of + plural (common error)", level: "L2 Application" },
    { q: "The jury have given their unanimous verdict after a long trial.", options: ["The jury have given","after a long trial","their unanimous verdict","No error"], answer: 0, explanation: "Jury acting as one unit (unanimous) takes a singular verb: 'has given', not 'have given'.", rule: "Collective noun acting as one unit → singular verb.", trapcat: "Collective noun", level: "L2 Application" },
    { q: "Scarcely the train had left the station than it began to rain heavily.", options: ["Scarcely the train had left","the station than it began","to rain heavily","No error"], answer: 0, explanation: "'Scarcely' requires inversion: 'Scarcely had the train left', and the correct pairing is 'scarcely...when', not 'than'.", rule: "Scarcely + had + subject + verb + when (with inversion).", trapcat: "Inversion + conjunction error", level: "L3 Trap" },
    { q: "Improve: If I was rich, I would travel the world.", options: ["If I am rich","No improvement","If I had been rich","If I were rich"], answer: 3, explanation: "Unreal present condition needs the subjunctive 'were', not 'was'.", rule: "Unreal condition → were (subjunctive), never was.", trapcat: "Conditionals", level: "L2 Application" },
    { q: "Improve: She is senior than me in the department.", options: ["more senior than me","most senior to me","No improvement","senior to me"], answer: 3, explanation: "'Senior' is one of the fixed exceptions that take 'to', never 'than'.", rule: "Senior/junior/superior/inferior/prior + to (never than).", trapcat: "Comparison error", level: "L2 Application" },
    { q: "Improve: The chairman, as well as the board members, were present at the meeting.", options: ["have been present","No improvement","were present","was present"], answer: 3, explanation: "'As well as' does not pluralise the subject — 'the chairman' stays singular, so it should be 'was present'.", rule: "As well as does not make the subject plural.", trapcat: "As well as trap", level: "L3 Trap" },
    { q: "Improve: No sooner the alarm rang than everyone rushed outside.", options: ["No sooner the alarm had rung","No improvement","No sooner rang the alarm","No sooner did the alarm ring"], answer: 3, explanation: "'No sooner' requires inversion with an auxiliary verb: 'No sooner did the alarm ring...than'.", rule: "No sooner + auxiliary + subject + verb + than.", trapcat: "Inversion error", level: "L3 Trap" },
    { q: "He is reputed ___ his honesty in all business dealings.", options: ["with","of","to","for"], answer: 3, explanation: "'Reputed for' is the fixed expression for being known for a quality.", rule: "Reputed for + quality.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "The company is liable ___ pay compensation for the damages caused.", options: ["with","to","of","for"], answer: 1, explanation: "'Liable to' + infinitive is the fixed pattern for a legal/moral obligation.", rule: "Liable to + verb.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "She was oblivious ___ the danger lurking nearby.", options: ["with","to","from","of"], answer: 3, explanation: "'Oblivious of' (or 'oblivious to') is acceptable, but the fixed traditional SSC form tested is 'oblivious of' — unaware of something.", rule: "Oblivious of + noun.", trapcat: "Preposition - less common", level: "L3 Trap" },
    { q: "The economy managed to recover ___ the recession within two years.", options: ["from","of","by","with"], answer: 0, explanation: "'Recover from' + setback/illness is the fixed expression.", rule: "Recover from + adversity.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Rearrange: A. The fire spread rapidly through the building. B. Firefighters arrived within minutes. C. A short circuit triggered the blaze. D. Everyone was evacuated safely.", options: ["A,B,C,D","C,B,A,D","C,A,B,D","A,C,B,D"], answer: 2, explanation: "Cause (short circuit, C) → effect (fire spreads, A) → response (firefighters arrive, B) → outcome (evacuated safely, D).", rule: "Cause before effect before response before outcome.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Rearrange: A. The negotiations broke down. B. Both sides refused to compromise. C. Talks had continued for weeks. D. A strike was declared.", options: ["C,B,A,D","B,C,A,D","C,A,B,D","C,B,D,A"], answer: 0, explanation: "Talks continue (C) → both sides refuse to compromise (B) → negotiations break down (A) → strike declared (D).", rule: "Chronological cause-effect chain.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: AUDACIOUS", options: ["Careful","Timid","Quiet","Bold"], answer: 3, explanation: "Audacious = showing bold, daring confidence, often recklessly so.", rule: "Vocabulary — audacious = bold.", trapcat: "Word meaning", level: "L2 Application" },
    { q: "Choose the word OPPOSITE in meaning: VERBOSE", options: ["Concise","Lengthy","Wordy","Talkative"], answer: 0, explanation: "Verbose = using more words than needed; opposite = concise (brief and clear). Wordy/Talkative/Lengthy are all synonyms of verbose, placed as traps.", rule: "Antonym — verbose ≠ concise.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who is unable to read or write:", options: ["Illiterate","Indolent","Illegible","Incoherent"], answer: 0, explanation: "Illiterate = unable to read or write. Illegible = hard to read (of handwriting), Indolent = lazy, Incoherent = not making logical sense.", rule: "One word substitution — illiterate.", trapcat: "Word meaning - close pairs", level: "L3 Trap" },
    { q: "'To add insult to injury' means:", options: ["To apologize sincerely","To insult someone directly","To make a bad situation even worse","To injure someone physically"], answer: 2, explanation: "'Add insult to injury' = to make an already bad situation worse.", rule: "Idiom: add insult to injury.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To get cold feet' means:", options: ["To become nervous and back out of a plan","To feel physically cold","To lose interest permanently","To become angry suddenly"], answer: 0, explanation: "'Get cold feet' = to become nervous or hesitant and back out of a commitment at the last moment.", rule: "Idiom: get cold feet.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: The board will announce the results tomorrow.", options: ["The results are announced by the board tomorrow","The results were announced by the board tomorrow","The board will be announced the results tomorrow","The results will be announced by the board tomorrow"], answer: 3, explanation: "Future simple passive: object + will + be + past participle + by subject.", rule: "Active → Passive: future tense → will be + V3.", trapcat: "Voice conversion", level: "L2 Application" },
    { q: "Convert to indirect speech: He said, \"I am feeling unwell today.\"", options: ["He said that he was feeling unwell today","He said he is feeling unwell that day","He said that he was feeling unwell that day","He said that he is feeling unwell today"], answer: 2, explanation: "Present continuous backshifts to past continuous (am feeling → was feeling); 'today' shifts to 'that day' in reported speech.", rule: "Backshift tense + shift time reference (today → that day).", trapcat: "Tense + time-reference backshift", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Quiestionnaire","Questionaire","Questionnairre","Questionnaire"], answer: 3, explanation: "'Questionnaire' is correctly spelt with double N — a commonly misspelt word.", rule: "Spelling: questionnaire has double N.", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: The two twins looked so identical that even their own mother could not tell them apart.", options: ["could not tell them apart","even their own mother","The two twins looked","so identical that"], answer: 2, explanation: "'Twins' already means two — 'two twins' is redundant.", rule: "Redundancy: twins already implies two.", trapcat: "Redundancy", level: "L3 Trap" }
  ]
},
{
  id: "oct1_m2", label: "1 Oct · Evening Full English Mock", timeLimitMin: 20,
  questions: [
    { q: "The list of new employees are posted on the notice board.", options: ["on the notice board","No error","The list of new employees","are posted"], answer: 3, explanation: "'The list' is the true singular subject — should be 'is posted', not 'are posted'.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "Either the workers or the supervisor were responsible for the delay.", options: ["were responsible","No error","for the delay","Either the workers or the supervisor"], answer: 0, explanation: "Either/or agrees with the nearer subject. 'Supervisor' (singular) is nearer, so it should be 'was responsible'.", rule: "Either/or → verb agrees with nearer subject.", trapcat: "Either/or - nearer trap", level: "L3 Trap" },
    { q: "One of the students who is always punctual was awarded a prize.", options: ["One of the students who is always punctual","was awarded a prize","No error"], answer: 0, explanation: "'One of the students who...' — 'who' refers to 'students' (plural), so it should be 'who are always punctual', not 'is'.", rule: "One of + plural + who → plural verb after who.", trapcat: "One of + who error", level: "L3 Trap" },
    { q: "The number of complaints have decreased significantly this month.", options: ["The number of complaints","this month","No error","have decreased significantly"], answer: 3, explanation: "'The number of' is a singular subject — should be 'has decreased', not 'have decreased'.", rule: "The number of → singular verb (contrast: A number of → plural).", trapcat: "The number of vs a number of", level: "L3 Trap" },
    { q: "Each and every student have submitted their assignment on time.", options: ["their assignment on time","Each and every student","have submitted","No error"], answer: 2, explanation: "'Each and every' is emphatically singular — should be 'has submitted', not 'have submitted'.", rule: "Each and every + noun → singular verb.", trapcat: "Each and every", level: "L2 Application" },
    { q: "Improve: If she would have studied harder, she would have passed the exam.", options: ["No improvement","If she would study harder","If she had studied harder","If she studied harder"], answer: 2, explanation: "Third conditional (past unreal) needs 'if + had + V3', never 'if + would have'.", rule: "Third conditional: If + had + V3, would + have + V3.", trapcat: "Conditional error - would have in if-clause", level: "L3 Trap" },
    { q: "Improve: This is one of the most unique solution to the problem.", options: ["the most unique solution","one of the unique solution","one of the most unique solutions","No improvement"], answer: 2, explanation: "'One of the' always takes a plural noun — should be 'solutions', not 'solution'.", rule: "One of the + plural noun.", trapcat: "One of + singular error", level: "L2 Application" },
    { q: "Improve: The teacher, together with her students, were preparing for the annual function.", options: ["have been preparing","was preparing","No improvement","were preparing"], answer: 1, explanation: "'Together with' does not pluralise the subject — 'the teacher' stays singular, so it should be 'was preparing'.", rule: "Together with does not make subject plural.", trapcat: "Together with trap", level: "L3 Trap" },
    { q: "Improve: Hardly he had reached home when the phone rang.", options: ["Hardly had he reach home","Hardly he reached home","No improvement","Hardly had he reached home"], answer: 3, explanation: "'Hardly' at the start of a sentence requires inversion: 'Hardly had he reached', not 'Hardly he had reached'.", rule: "Hardly + had + subject + V3 (inversion).", trapcat: "Inversion error", level: "L3 Trap" },
    { q: "Improve: The committee members was divided on the new proposal.", options: ["have been divide","were divided","was divided","No improvement"], answer: 1, explanation: "'Committee members' (plural, referring to individuals) takes a plural verb: 'were divided', not 'was divided'.", rule: "Collective noun members acting individually → plural verb.", trapcat: "Collective noun - individual action", level: "L2 Application" },
    { q: "The witness was reluctant ___ reveal the identity of the culprit.", options: ["to","for","in","of"], answer: 0, explanation: "'Reluctant to' + infinitive is the fixed pattern.", rule: "Reluctant to + verb.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "The new policy is aimed ___ reducing traffic congestion in the city.", options: ["to","for","on","at"], answer: 3, explanation: "'Aimed at' + gerund is the fixed pattern.", rule: "Aimed at + gerund.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "He is adept ___ handling difficult clients with patience.", options: ["in","at","to","with"], answer: 1, explanation: "'Adept at' is the fixed expression meaning skilled at something.", rule: "Adept at + gerund/noun.", trapcat: "Preposition - less common", level: "L3 Trap" },
    { q: "The organization is committed ___ improving employee welfare.", options: ["with","in","to","for"], answer: 2, explanation: "'Committed to' + gerund is the fixed pattern.", rule: "Committed to + gerund.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Rearrange: A. Sales dropped sharply the following quarter. B. The company launched a new product. C. Customer complaints about quality rose. D. The design proved to be flawed.", options: ["B,C,D,A","B,D,C,A","D,B,C,A","B,D,A,C"], answer: 1, explanation: "Company launches product (B) → design proves flawed (D) → complaints rise (C) → sales drop (A).", rule: "Launch → flaw discovered → complaints → consequence.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Rearrange: A. The plant wilted within days. B. She forgot to water it regularly. C. She bought a new plant for her balcony. D. She felt guilty about neglecting it.", options: ["C,B,A,D","C,B,D,A","C,A,B,D","B,C,A,D"], answer: 0, explanation: "Buys plant (C) → forgets to water (B) → plant wilts (A) → feels guilty (D).", rule: "Action → neglect → consequence → emotional reaction.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: PRUDENT", options: ["Careless","Foolish","Wise","Reckless"], answer: 2, explanation: "Prudent = showing care and good judgment, especially about practical matters; closest to 'wise'.", rule: "Vocabulary — prudent = wise.", trapcat: "Word meaning", level: "L2 Application" },
    { q: "Choose the word OPPOSITE in meaning: AMIABLE", options: ["Cordial","Pleasant","Friendly","Hostile"], answer: 3, explanation: "Amiable = friendly and pleasant; opposite = hostile. Friendly/Pleasant/Cordial are synonyms, placed as traps.", rule: "Antonym — amiable ≠ hostile.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who loves and collects books:", options: ["Bibliophobe","Bibliophile","Biography","Bibliography"], answer: 1, explanation: "Bibliophile = a lover/collector of books. Bibliophobe (opposite, fear of books), Bibliography (list of sources), Biography (life story) are all close-sounding traps.", rule: "One word substitution — bibliophile.", trapcat: "Word meaning - close pairs", level: "L3 Trap" },
    { q: "'To turn a blind eye' means:", options: ["To refuse to help someone","To deliberately ignore something wrong","To become blind suddenly","To look away in fear"], answer: 1, explanation: "'Turn a blind eye' = to deliberately ignore or pretend not to notice something wrong.", rule: "Idiom: turn a blind eye = deliberately ignore.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To be in the same boat' means:", options: ["To agree completely","To travel together","To be in the same difficult situation as others","To compete against each other"], answer: 2, explanation: "'In the same boat' = facing the same difficult situation or circumstances as someone else.", rule: "Idiom: in the same boat = shared situation.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: They have completed the survey successfully.", options: ["The survey was completed successfully by them","The survey has completed successfully","The survey is completed successfully by them","The survey has been completed successfully by them"], answer: 3, explanation: "Present perfect passive: has/have + been + past participle.", rule: "Active → Passive: present perfect → has been + V3.", trapcat: "Voice conversion", level: "L2 Application" },
    { q: "Convert to indirect speech: The manager said, \"I will review your proposal tomorrow.\"", options: ["The manager said that he would review my proposal today","The manager said that he will review my proposal tomorrow","The manager said he would review my proposal tomorrow","The manager said that he would review my proposal the next day"], answer: 3, explanation: "Will backshifts to would; 'tomorrow' shifts to 'the next day' in reported speech.", rule: "Backshift modal (will→would) + time reference (tomorrow→the next day).", trapcat: "Modal + time-reference backshift", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Maintenence","Maintenance","Maintaenance","Maintainance"], answer: 1, explanation: "'Maintenance' is correctly spelt — note it drops the second 'ai' pattern from 'maintain', a common source of error.", rule: "Spelling: maintenance (not maintainance).", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: He returned back to his hometown after completing his studies abroad.", options: ["abroad","He returned back","after completing his studies","to his hometown"], answer: 1, explanation: "'Return' already means 'come back' — 'returned back' is redundant.", rule: "Redundancy: return already means come back.", trapcat: "Redundancy", level: "L2 Application" }
  ]
},
{
  id: "oct1_m3", label: "1 Oct · Maths Mock", timeLimitMin: 25,
  questions: [
    { q: "35% of 320 + 25% of 200 = ?", options: ["170","162","155","150"], answer: 1, explanation: "35% of 320 = 112; 25% of 200 = 50; 112+50 = 162.", rule: "Percentage of number: (percentage/100) × number.", trapcat: "Calculation", level: "L1 Direct" },
    { q: "If 40% of a number is 68, the number is:", options: ["180","150","170","160"], answer: 2, explanation: "Number × 40/100 = 68 → Number = 68 × 100/40 = 170.", rule: "Reverse percentage: number = value × 100/%.", trapcat: "Reverse calculation", level: "L1 Direct" },
    { q: "A number increased by 20% gives 372. The original number is:", options: ["320","295","300","310"], answer: 3, explanation: "Original × 1.20 = 372 → Original = 372/1.20 = 310.", rule: "Percentage increase reverse calculation.", trapcat: "Percentage increase", level: "L2 Application" },
    { q: "If a:b = 5:6 and b:c = 4:7, then a:c = ?", options: ["5:7","20:42","10:21","9:13"], answer: 2, explanation: "a:c = (5×4):(6×7) = 20:42 = 10:21 in simplest form.", rule: "Chain ratio, then simplify.", trapcat: "Ratio chain - simplification", level: "L3 Trap" },
    { q: "The average of 12 numbers is 30. If each number is increased by 3, the new average is:", options: ["30","36","33","27"], answer: 2, explanation: "If each number increases by 3, the average also increases by 3 → 30+3 = 33.", rule: "Average adjustment: new avg = old avg ± change.", trapcat: "Average property", level: "L1 Direct" },
    { q: "The average weight of 10 persons increases by 2 kg when a new person replaces one of them weighing 55 kg. What is the weight of the new person?", options: ["80 kg","75 kg","70 kg","65 kg"], answer: 1, explanation: "Total increase = 10 × 2 = 20 kg. New person's weight = 55+20 = 75 kg.", rule: "Total increase = count × avg change; add to replaced person's weight.", trapcat: "Average with replacement", level: "L2 Application" },
    { q: "An article is sold for Rs.720 at a loss of 10%. What is the cost price?", options: ["Rs.750","Rs.780","Rs.820","Rs.800"], answer: 3, explanation: "CP = SP/(1-loss%) = 720/0.90 = Rs.800.", rule: "CP = SP / (1 - loss%).", trapcat: "Profit-loss calculation", level: "L2 Application" },
    { q: "A trader marks his goods 40% above cost price and allows a 20% discount. His gain percent is:", options: ["20%","12%","15%","10%"], answer: 1, explanation: "CP=100, MP=140, SP=140×0.8=112, Gain=12%.", rule: "Marked price + discount chain.", trapcat: "Profit-loss with discount", level: "L2 Application" },
    { q: "Marked price of an item is Rs.600, discount offered is 10%. Selling price is:", options: ["Rs.550","Rs.540","Rs.520","Rs.560"], answer: 1, explanation: "SP = MP × (1-discount%) = 600×0.90 = Rs.540.", rule: "SP = MP × (1 - discount%).", trapcat: "Discount calculation", level: "L1 Direct" },
    { q: "The simple interest on Rs.2000 for 4 years at 6% per annum is:", options: ["Rs.480","Rs.500","Rs.450","Rs.460"], answer: 0, explanation: "SI = P×R×T/100 = 2000×6×4/100 = Rs.480.", rule: "Simple interest formula.", trapcat: "SI calculation", level: "L1 Direct" },
    { q: "The compound interest on Rs.2000 at 10% per annum for 2 years, compounded annually, is:", options: ["Rs.440","Rs.420","Rs.410","Rs.400"], answer: 1, explanation: "CI = 2000×(1.10)^2 - 2000 = 2420-2000 = Rs.420.", rule: "Compound interest formula.", trapcat: "CI calculation", level: "L2 Application" },
    { q: "In what ratio must tea worth Rs.20/kg be mixed with tea worth Rs.25/kg to get a mixture worth Rs.22/kg?", options: ["3:2","1:2","2:3","3:1"], answer: 0, explanation: "By alligation: (25-22):(22-20) = 3:2 (dearer:cheaper).", rule: "Alligation: (d-c):(m-c) inverted for ratio of cheaper:dearer amounts — here (d-m):(m-c) = 3:2.", trapcat: "Alligation", level: "L2 Application" },
    { q: "A and B invest in a business in the ratio 2:3. If the total profit is Rs.1200, find B's share.", options: ["Rs.700","Rs.480","Rs.600","Rs.720"], answer: 3, explanation: "Total parts = 5. B's share = (3/5)×1200 = Rs.720.", rule: "Partnership: share = (ratio part/total parts) × profit.", trapcat: "Partnership", level: "L1 Direct" },
    { q: "The ratio of ages of two brothers is 2:3, and their sum is 50. Find the older brother's age after 5 years.", options: ["33","28","30","35"], answer: 3, explanation: "Older brother's share = (3/5)×50 = 30. After 5 years = 30+5 = 35.", rule: "Age ratio with sum, then add years.", trapcat: "Age calculation", level: "L1 Direct" },
    { q: "A can do a piece of work in 12 days, B in 20 days. Working together, they will complete the work in:", options: ["8 days","10 days","9 days","7.5 days"], answer: 3, explanation: "Combined rate = 1/12+1/20 = 5/60+3/60=8/60=2/15. Time = 15/2 = 7.5 days.", rule: "Work together: 1/A + 1/B = 1/Combined time.", trapcat: "Time and work", level: "L2 Application" },
    { q: "A and B together can complete a work in 12 days. A alone can do it in 20 days. B alone can do it in:", options: ["24 days","25 days","28 days","30 days"], answer: 3, explanation: "Together rate=1/12; A alone=1/20; B alone=1/12-1/20=5/60-3/60=2/60=1/30 → 30 days.", rule: "Work efficiency: combined - one = other.", trapcat: "Time and work", level: "L2 Application" },
    { q: "Pipe A can fill a tank in 5 hours and Pipe B in 20 hours. If both are opened together, the tank fills in:", options: ["4 hours","5 hours","3.5 hours","4.5 hours"], answer: 0, explanation: "Combined rate=1/5+1/20=4/20+1/20=5/20=1/4 → 4 hours.", rule: "Pipes together: 1/A + 1/B = 1/Time.", trapcat: "Pipes and cisterns", level: "L1 Direct" },
    { q: "A train running at 54 km/h crosses a pole in 10 seconds. Find the length of the train.", options: ["145 m","140 m","150 m","160 m"], answer: 2, explanation: "Speed = 54×5/18=15 m/s. Length = speed×time = 15×10 = 150 m.", rule: "Crossing a pole = covering the train's own length.", trapcat: "Train problems", level: "L2 Application" },
    { q: "A car travels a distance at 40 km/h and returns the same distance at 60 km/h. Find its average speed for the entire journey.", options: ["48 km/h","50 km/h","52 km/h","45 km/h"], answer: 0, explanation: "Average speed = 2xy/(x+y) = 2×40×60/100 = 48 km/h (harmonic mean, not arithmetic mean).", rule: "Equal distances → harmonic mean 2xy/(x+y).", trapcat: "Average speed trap", level: "L2 Application" },
    { q: "A boat's upstream speed is 6 km/h and downstream speed is 8 km/h. Find the speed of the stream.", options: ["0.5 km/h","1.5 km/h","2 km/h","1 km/h"], answer: 3, explanation: "Stream speed = (Downstream - Upstream)/2 = (8-6)/2 = 1 km/h.", rule: "Stream speed = (Downstream-Upstream)/2.", trapcat: "Boats and streams", level: "L1 Direct" },
    { q: "The HCF of two numbers is 12 and their LCM is 240. If one number is 48, find the other.", options: ["50","60","54","56"], answer: 1, explanation: "Product = HCF×LCM = 12×240=2880. Other number = 2880/48 = 60.", rule: "Number1 × Number2 = HCF × LCM.", trapcat: "HCF-LCM", level: "L2 Application" },
    { q: "Find the largest 4-digit number exactly divisible by 12.", options: ["9988","9992","9984","9996"], answer: 3, explanation: "9999/12 = 833 remainder 3, so 9999-3 = 9996.", rule: "Subtract (N mod divisor) from N.", trapcat: "Divisibility", level: "L1 Direct" },
    { q: "The angles of a triangle are in the ratio 2:3:4. Find the largest angle.", options: ["90 degrees","85 degrees","75 degrees","80 degrees"], answer: 3, explanation: "Total parts=9. Largest = (4/9)×180 = 80 degrees.", rule: "Triangle angle sum = 180; divide by total parts.", trapcat: "Geometry", level: "L1 Direct" },
    { q: "The area of a circle is 154 sq cm. Find its radius. (Use pi = 22/7)", options: ["7 cm","7.5 cm","8 cm","6 cm"], answer: 0, explanation: "Area = pi×r^2 → 154 = (22/7)×r^2 → r^2 = 154×7/22 = 49 → r = 7 cm.", rule: "Reverse area formula: r = sqrt(Area × 7/22).", trapcat: "Mensuration - reverse", level: "L2 Application" },
    { q: "Simplify: (5/6 + 1/3) divided by (1/2 - 1/6)", options: ["3.5","3","4","2.5"], answer: 0, explanation: "Numerator: 5/6+1/3=5/6+2/6=7/6. Denominator: 1/2-1/6=3/6-1/6=2/6=1/3. Result=(7/6)/(1/3)=(7/6)×3=7/2=3.5.", rule: "Convert to single fractions, then divide by multiplying by reciprocal.", trapcat: "Simplification", level: "L2 Application" }
  ]
},
{
  id: "oct1_m4", label: "1 Oct · GS Mock", timeLimitMin: 30,
  questions: [
    { q: "Which Article of the Indian Constitution abolishes untouchability?", options: ["Article 15","Article 23","Article 21","Article 17"], answer: 3, explanation: "Article 17 abolishes untouchability and forbids its practice in any form.", rule: "Article 17 — abolition of untouchability.", trapcat: "Fundamental Rights", level: "L2 Application" },
    { q: "The 'Doctrine of Basic Structure' of the Indian Constitution was propounded in which case?", options: ["Maneka Gandhi case (1978)","Minerva Mills case (1980)","Golaknath case (1967)","Kesavananda Bharati case (1973)"], answer: 3, explanation: "The Kesavananda Bharati case (1973) established that Parliament cannot amend the 'basic structure' of the Constitution.", rule: "Kesavananda Bharati — Basic Structure Doctrine.", trapcat: "Landmark cases", level: "L3 Trap" },
    { q: "Who was the first Speaker of the Lok Sabha?", options: ["N. Sanjiva Reddy","Sardar Hukam Singh","G.V. Mavalankar","K.S. Hegde"], answer: 2, explanation: "G.V. Mavalankar was the first Speaker of the Lok Sabha, serving from 1952.", rule: "First Lok Sabha Speaker — G.V. Mavalankar.", trapcat: "Constitutional history", level: "L2 Application" },
    { q: "The Battle of Plassey (1757), which laid the foundation of British rule in India, was fought between the British and:", options: ["Siraj-ud-Daulah, Nawab of Bengal","Tipu Sultan","Mir Qasim","Shuja-ud-Daulah"], answer: 0, explanation: "The Battle of Plassey (1757) was fought between the British East India Company and Siraj-ud-Daulah, the last independent Nawab of Bengal.", rule: "Battle of Plassey — Siraj-ud-Daulah.", trapcat: "British colonial history", level: "L2 Application" },
    { q: "Which Mughal emperor is associated with the 'Din-i-Ilahi', a syncretic religious movement?", options: ["Aurangzeb","Akbar","Shah Jahan","Jahangir"], answer: 1, explanation: "Akbar founded Din-i-Ilahi in 1582, blending elements of various religions.", rule: "Din-i-Ilahi — founded by Akbar.", trapcat: "Mughal history", level: "L2 Application" },
    { q: "The Tropic of Cancer passes through how many Indian states?", options: ["8","9","7","6"], answer: 0, explanation: "The Tropic of Cancer passes through 8 Indian states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.", rule: "Tropic of Cancer — 8 Indian states.", trapcat: "Physical geography", level: "L3 Trap" },
    { q: "Which is the largest freshwater lake in India?", options: ["Sambhar Lake (Rajasthan)","Wular Lake (Jammu & Kashmir)","Chilika Lake (Odisha)","Dal Lake (Jammu & Kashmir)"], answer: 1, explanation: "Wular Lake in Jammu & Kashmir is the largest freshwater lake in India. Chilika is the largest BRACKISH-water lagoon, a commonly confused distinction.", rule: "Wular = largest freshwater; Chilika = largest brackish-water lagoon.", trapcat: "Freshwater vs brackish lake trap", level: "L3 Trap" },
    { q: "Which state has the highest installed solar power capacity in India (among traditionally leading states)?", options: ["Rajasthan","Tamil Nadu","Gujarat","Karnataka"], answer: 0, explanation: "Rajasthan, with its vast arid land and high solar insolation, has consistently led India in installed solar power capacity.", rule: "Rajasthan — leading solar power capacity.", trapcat: "Renewable energy geography", level: "L2 Application" },
    { q: "The Reserve Bank of India's monetary policy committee (MPC) has how many members?", options: ["5","6","4","7"], answer: 1, explanation: "The Monetary Policy Committee (MPC) has 6 members — 3 from RBI and 3 external members appointed by the government.", rule: "MPC — 6 members (3 RBI + 3 external).", trapcat: "Monetary policy structure", level: "L3 Trap" },
    { q: "'Disinvestment' in the context of the Indian economy refers to:", options: ["The government investing more money into public enterprises","Reduction in overall government expenditure","Foreign companies withdrawing investment from India","The sale of government equity/stake in public sector enterprises"], answer: 3, explanation: "Disinvestment means the government selling or liquidating its equity stake in public sector undertakings (PSUs).", rule: "Disinvestment — government selling PSU stake.", trapcat: "Economic terminology", level: "L2 Application" },
    { q: "Which vitamin deficiency causes the disease 'Rickets' in children?", options: ["Vitamin C","Vitamin A","Vitamin B12","Vitamin D"], answer: 3, explanation: "Vitamin D deficiency causes Rickets (soft, weak bones) in children.", rule: "Vitamin D deficiency — Rickets.", trapcat: "Nutritional deficiency diseases", level: "L2 Application" },
    { q: "Which gas is most responsible for the depletion of the ozone layer?", options: ["Sulphur dioxide","Carbon dioxide","Methane","Chlorofluorocarbons (CFCs)"], answer: 3, explanation: "Chlorofluorocarbons (CFCs), once widely used in refrigerants and aerosols, are the primary cause of ozone layer depletion.", rule: "CFCs — primary ozone depletion cause.", trapcat: "Environmental chemistry", level: "L2 Application" },
    { q: "The process by which plants lose water in the form of vapour through their leaves is called:", options: ["Transpiration","Respiration","Osmosis","Photosynthesis"], answer: 0, explanation: "Transpiration is the loss of water vapour from plant leaves through stomata.", rule: "Transpiration — water loss from leaves.", trapcat: "Plant physiology", level: "L1 Direct" },
    { q: "Who is credited with founding the Indian National Congress in 1885?", options: ["W.C. Bonnerjee","Dadabhai Naoroji","Surendranath Banerjee","A.O. Hume"], answer: 3, explanation: "A.O. Hume, a retired British civil servant, is credited with founding the Indian National Congress in 1885. W.C. Bonnerjee was its first President, a commonly confused distinction.", rule: "A.O. Hume founded INC; W.C. Bonnerjee was its first President.", trapcat: "Founder vs first president trap", level: "L3 Trap" },
    { q: "The 'Poona Pact' (1932) was signed between Mahatma Gandhi and:", options: ["Muhammad Ali Jinnah","B.R. Ambedkar","Subhas Chandra Bose","Madan Mohan Malaviya"], answer: 1, explanation: "The Poona Pact (1932) was signed between Gandhi and Ambedkar, replacing separate electorates for the Depressed Classes with reserved seats in a joint electorate.", rule: "Poona Pact — Gandhi and Ambedkar.", trapcat: "Freedom movement agreements", level: "L2 Application" },
    { q: "Which Indian state is the largest producer of coffee?", options: ["Karnataka","Andhra Pradesh","Kerala","Tamil Nadu"], answer: 0, explanation: "Karnataka (particularly the Kodagu/Coorg region) is India's largest coffee-producing state.", rule: "Karnataka — largest coffee producer.", trapcat: "Agricultural geography", level: "L2 Application" },
    { q: "The 'Sangam' literature belongs to which period and region?", options: ["Ancient Gujarat","Ancient Tamil Nadu (roughly 300 BCE - 300 CE)","Medieval Karnataka","Medieval Bengal"], answer: 1, explanation: "Sangam literature is a body of ancient Tamil poetic works composed roughly between 300 BCE and 300 CE.", rule: "Sangam literature — ancient Tamil Nadu.", trapcat: "Ancient literature", level: "L2 Application" },
    { q: "Which of the following is NOT one of the three organs of the State as per the doctrine of Separation of Powers?", options: ["Executive","Bureaucracy","Judiciary","Legislature"], answer: 1, explanation: "The classical Separation of Powers doctrine identifies three organs: Legislature, Executive, and Judiciary. Bureaucracy is part of the Executive machinery, not a separate fourth organ.", rule: "Three organs: Legislature, Executive, Judiciary (Bureaucracy is part of Executive).", trapcat: "Political theory", level: "L2 Application" },
    { q: "The 'Simon Commission' (1928), which visited India to review constitutional reforms, was boycotted primarily because:", options: ["It was formed without British parliamentary approval","It proposed to abolish provincial autonomy","It recommended separate electorates for all communities","It did not include any Indian members"], answer: 3, explanation: "The Simon Commission was boycotted with 'Simon Go Back' protests because it had no Indian members despite reviewing India's constitutional future.", rule: "Simon Commission boycotted — all-British composition, no Indians.", trapcat: "Freedom movement protests", level: "L2 Application" },
    { q: "Which layer of the atmosphere contains the ozone layer that protects Earth from harmful UV radiation?", options: ["Mesosphere","Thermosphere","Stratosphere","Troposphere"], answer: 2, explanation: "The ozone layer is located in the stratosphere, roughly 15-35 km above Earth's surface.", rule: "Ozone layer — located in the stratosphere.", trapcat: "Atmospheric layers", level: "L2 Application" },
    { q: "The 'Gini Coefficient' is a statistical measure used to represent:", options: ["Literacy rate","Gross Domestic Product growth rate","Income or wealth inequality within a nation","Rate of inflation"], answer: 2, explanation: "The Gini Coefficient measures income or wealth inequality within a population, ranging from 0 (perfect equality) to 1 (perfect inequality).", rule: "Gini Coefficient — measure of inequality.", trapcat: "Economic indicators", level: "L2 Application" },
    { q: "Which Indian classical dance form originated in Tamil Nadu and is traditionally associated with temple worship?", options: ["Bharatanatyam","Manipuri","Odissi","Kathak"], answer: 0, explanation: "Bharatanatyam originated in Tamil Nadu temples, traditionally performed by devadasis as a form of worship.", rule: "Bharatanatyam — Tamil Nadu classical dance.", trapcat: "Classical dance forms", level: "L2 Application" },
    { q: "Which committee recommended the establishment of NITI Aayog to replace the Planning Commission?", options: ["Bibek Debroy Committee (post-facto review only)","Ashok Chawla Committee","No committee — it was a direct Cabinet decision in 2015","C. Rangarajan Committee"], answer: 2, explanation: "NITI Aayog was established via a direct Union Cabinet resolution on 1 January 2015, not through a formal recommending committee — a fact that itself is often tested as a trap since most institutional changes DO follow committee recommendations.", rule: "NITI Aayog — direct Cabinet decision, not committee-recommended.", trapcat: "Institutional history - direct decision trap", level: "L3 Trap" },
    { q: "The 'Namami Gange' programme is primarily aimed at:", options: ["Flood control in the Brahmaputra basin","Afforestation along the Himalayan foothills","Conservation and rejuvenation of the Ganga river","Rural electrification in the Gangetic plains"], answer: 2, explanation: "Namami Gange is a flagship programme for the conservation and rejuvenation of the National River Ganga, covering pollution abatement and river-front development.", rule: "Namami Gange — Ganga conservation programme.", trapcat: "Government schemes", level: "L1 Direct" },
    { q: "Which blood vessel carries oxygenated blood from the lungs back to the heart?", options: ["Pulmonary artery","Pulmonary vein","Vena cava","Aorta"], answer: 1, explanation: "The pulmonary vein carries oxygenated blood from the lungs to the heart's left atrium — the one vein in the body that carries oxygen-rich blood (veins usually carry deoxygenated blood).", rule: "Pulmonary vein — the exception that carries oxygenated blood.", trapcat: "Circulatory system - vein/artery exception", level: "L3 Trap" }
  ]
},
{
  id: "oct2_m1", label: "2 Oct · Morning English Mock (Deep)", timeLimitMin: 25,
  questions: [
    { q: "The findings of the research team, which had spent nearly three years studying migratory patterns, was presented at the international conference last month.", options: ["the international conference last month","which had spent nearly three years studying migratory patterns,","The findings of the research team,","was presented at"], answer: 3, explanation: "The true subject is 'findings' (plural), not 'team' — despite the long embedded clause about the team, it should be 'were presented', not 'was presented'.", rule: "Identify the real subject before an embedded relative clause; do not let the clause's own noun (team, singular) hijack the verb agreement.", trapcat: "Embedded clause - subject-verb agreement", level: "L3 Trap" },
    { q: "Despite having been warned repeatedly by his doctor about the risks, he continued to ignoring the advice and carried on with his unhealthy habits.", options: ["the advice and carried on","he continued to ignoring","Despite having been warned repeatedly","by his doctor about the risks,"], answer: 1, explanation: "'Continued to' must be followed by the bare infinitive 'ignore', not the gerund 'ignoring' — it should be 'continued to ignore'.", rule: "'Continue to' + base verb (infinitive without 'to' being dropped is incorrect here — the infinitive form itself, e.g. 'to ignore', is required, not 'to ignoring').", trapcat: "Infinitive vs gerund after 'continued to'", level: "L3 Trap" },
    { q: "Not only did the new policy fail to reduce costs, but it also created several unintended consequences that the committee had not anticipating.", options: ["but it also created several unintended consequences","Not only did the new policy fail","to reduce costs,","that the committee had not anticipating"], answer: 3, explanation: "'Had not' must be followed by a past participle, not a gerund — it should be 'had not anticipated', not 'had not anticipating'.", rule: "Past perfect negative: had not + past participle.", trapcat: "Past perfect tense error", level: "L3 Trap" },
    { q: "The proposal, along with the supporting documents that had been submitted earlier, were rejected by the review board without explanation.", options: ["without explanation","were rejected by the review board","The proposal, along with","the supporting documents that had been submitted earlier,"], answer: 1, explanation: "'Along with' does not pluralise the subject — 'the proposal' remains the true singular subject, so it should be 'was rejected', not 'were rejected'.", rule: "'Along with' does not make the subject plural, even with a long embedded phrase following it.", trapcat: "Along with trap (embedded)", level: "L3 Trap" },
    { q: "Improve: The board members, who had been debating the merger for hours, was finally able to reach a consensus decision.", options: ["have finally able to reach","No improvement","were finally able to reach","was finally able to reaching"], answer: 2, explanation: "'Board members' (plural) is the true subject — the embedded relative clause does not change this. It should be 'were finally able to reach', not 'was'.", rule: "Match the verb to the true plural subject despite an intervening relative clause.", trapcat: "Embedded clause agreement", level: "L2 Application" },
    { q: "Improve: It is essential that every employee follows the updated safety protocol without exception.", options: ["No improvement","that every employee is following","that every employee follow","that every employee followed"], answer: 2, explanation: "After 'it is essential that', the subjunctive mood requires the bare base form of the verb ('follow'), regardless of the subject's number — not 'follows'.", rule: "Subjunctive mood after essential/important/necessary that: base verb form, no -s.", trapcat: "Subjunctive mood", level: "L3 Trap" },
    { q: "Improve: Having completed the assignment ahead of schedule, the manager's praise was well deserved by the team.", options: ["the manager praised the team, well deserved","the team's efforts well deserved the manager's praise","No improvement","the team deserved the manager's praise"], answer: 3, explanation: "This is a dangling modifier — 'Having completed the assignment' should logically modify 'the team' (who completed it), not 'the manager's praise', which cannot itself complete an assignment.", rule: "The subject immediately after an introductory participial phrase must be the one performing that action.", trapcat: "Dangling modifier", level: "L3 Trap" },
    { q: "The committee, having reviewed all the applications submitted by the candidates, has decided to shortlist five of them for the ___ round.", options: ["consequent","resultant","concurrent","subsequent"], answer: 3, explanation: "'Subsequent' means following in time/order — the next round after shortlisting. 'Consequent' means resulting from something, 'resultant' is similar, and 'concurrent' means happening at the same time.", rule: "Subsequent = following in sequence; distinguish from consequent (resulting from) and concurrent (simultaneous).", trapcat: "Close vocabulary in context", level: "L3 Trap" },
    { q: "Given the ___ nature of the evidence presented, the jury found it difficult to reach a unanimous verdict.", options: ["unequivocal","eloquent","equitable","equivocal"], answer: 3, explanation: "'Equivocal' means open to more than one interpretation, ambiguous — matching the jury's difficulty. 'Unequivocal' means the opposite (completely clear), which would contradict the sentence's logic.", rule: "Equivocal = ambiguous; watch for the 'un-' prefix flipping the meaning entirely in a similar-looking trap option.", trapcat: "Prefix-flip vocabulary trap", level: "L3 Trap" },
    { q: "The two companies, despite being fierce competitors for years, decided to ___ their resources for this one joint venture.", options: ["pool","poll","pole","pull"], answer: 0, explanation: "'Pool' (as a verb) means to combine resources together. 'Poll' relates to voting/surveys, 'pull' means to drag, 'pole' is a long rod — all homophones/near-homophones of 'pool' used as traps.", rule: "Pool (combine resources) vs poll/pull/pole — distinguish these commonly confused homophone-adjacent words.", trapcat: "Homophone trap", level: "L3 Trap" },
    { q: "Select the correctly punctuated sentence.", options: ["The manager said \"We will announce the results by Friday\".","The manager said, \"We will announce the results by Friday\".","The manager said \"We will announce the results by Friday.\"","The manager said, \"We will announce the results by Friday.\""], answer: 3, explanation: "The comma after 'said' introduces the quotation, the quoted sentence begins with a capital letter, and the closing period sits INSIDE the closing quotation mark.", rule: "Direct speech punctuation: comma before the quote, period inside the closing quotation mark.", trapcat: "Punctuation", level: "L2 Application" },
    { q: "Rearrange: P. The company's stock price plummeted overnight. Q. Investors had grown increasingly wary after the earnings report. R. An anonymous whistleblower revealed accounting irregularities. S. Regulators launched a formal investigation within days.", options: ["Q,R,P,S","R,P,Q,S","R,Q,P,S","Q,P,R,S"], answer: 2, explanation: "The whistleblower's revelation (R) comes first, causing investor wariness (Q), which triggers the stock price collapse (P), followed by the regulatory investigation (S).", rule: "Trace each sentence's cause-effect trigger before ordering — the whistleblower's reveal is the root cause that sets off the rest.", trapcat: "Sentence sequencing - root cause identification", level: "L3 Trap" },
    { q: "Synonym of CIRCUMSPECT:", options: ["Cautious","Impulsive","Reckless","Careless"], answer: 0, explanation: "Circumspect = careful to consider all circumstances before acting; cautious.", rule: "Circumspect = cautious, wary of consequences.", trapcat: "Vocabulary", level: "L2 Application" },
    { q: "Antonym of INTREPID:", options: ["Bold","Timid","Daring","Brave"], answer: 1, explanation: "Intrepid = fearless, brave; opposite = timid. Brave/Bold/Daring are all synonyms, placed as traps.", rule: "Antonym — intrepid ≠ timid.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who is knowledgeable about many different subjects:", options: ["Polymath","Pedant","Pundit","Polyglot"], answer: 0, explanation: "Polymath = a person with knowledge across many different fields. Polyglot = someone who speaks many LANGUAGES (not subjects), Pedant = overly concerned with minor details/rules, Pundit = an expert/commentator in one specific area.", rule: "Polymath (many subjects) vs Polyglot (many languages) — a frequent close-pair confusion.", trapcat: "Close word-pair trap", level: "L3 Trap" },
    { q: "'To hit the nail on the head' means:", options: ["To work very hard on a project","To fail at a task completely","To describe something exactly and accurately","To cause an accident"], answer: 2, explanation: "'Hit the nail on the head' = to describe or identify something precisely and correctly.", rule: "Idiom: hit the nail on the head = precisely correct.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To be a fish out of water' means:", options: ["To swim very well","To feel awkward or out of place in a situation","To be extremely thirsty","To struggle to breathe"], answer: 1, explanation: "'Fish out of water' = to feel uncomfortable or out of place in an unfamiliar situation.", rule: "Idiom: fish out of water = feeling out of place.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: The board must have approved the budget before the deadline.", options: ["The budget must have been approved by the board before the deadline","The budget must have approved by the board before the deadline","The budget must be approved by the board before the deadline","The budget had to be approved by the board before the deadline"], answer: 0, explanation: "Modal perfect passive: 'must have' + been + past participle — 'must have been approved'.", rule: "Modal + have + been + V3 for a modal perfect passive construction.", trapcat: "Modal perfect passive", level: "L3 Trap" },
    { q: "Convert to indirect speech: The doctor said to the patient, \"You should reduce your salt intake and exercise regularly.\"", options: ["The doctor advised the patient to reduce his salt intake and exercise regularly","The doctor told the patient reduce his salt intake and exercise regularly","The doctor said that the patient should reduce his salt intake and exercise regularly","The doctor said to reduce the salt intake and exercising regularly"], answer: 0, explanation: "An advice-giving 'should' statement converts to 'advised + object + to + base verb' in indirect speech, with two parallel actions (reduce, exercise) both converted to infinitives.", rule: "'Should' advice converts to 'advised to' + infinitive, applied consistently to both parallel actions.", trapcat: "Advice narration with parallel structure", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Bureaucracy","Beaurocracy","Burocracy","Bureaucracy"], answer: 0, explanation: "'Bureaucracy' is correctly spelt — note the 'eau' sequence borrowed from French, a common source of error.", rule: "Spelling: bureaucracy has the French-origin 'eau' spelling pattern.", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: The twins were so identical in appearance and mannerism that even their closest friends often confuses one for the other.", options: ["often confuses one for the other","The twins were so identical","in appearance and mannerism","that even their closest friends"], answer: 0, explanation: "'Friends' (plural) is the subject of this clause — it should be 'often confuse', not 'often confuses'.", rule: "Match the verb to its own clause's subject (friends, plural), independent of the main clause's subject earlier in the sentence.", trapcat: "Subject-verb agreement in subordinate clause", level: "L2 Application" },
    { q: "Select the part with an error: The report clearly indicate that the company's revenue has declined steadily over the past three quarters.", options: ["over the past three quarters","has declined steadily","The report clearly indicate","that the company's revenue"], answer: 2, explanation: "'The report' is singular — should be 'indicates', not 'indicate'.", rule: "Singular subject 'report' requires singular verb 'indicates'.", trapcat: "Subject-verb agreement", level: "L2 Application" },
    { q: "Improve: The reason why he resigned was because he disagreed with the company's new direction.", options: ["No improvement","The reason for his resignation is because","The reason he resigned was because","The reason why he resigned was that"], answer: 3, explanation: "'The reason...was because' is redundant (both 'reason' and 'because' express causation) — the correct form is 'the reason...was that'.", rule: "Avoid 'reason...because' redundancy; use 'reason...that' instead.", trapcat: "Redundancy - reason because", level: "L3 Trap" },
    { q: "Select the part with an error: Between you and I, I think the new proposal is far more practical than the original one.", options: ["than the original one","Between you and I,","is far more practical","I think the new proposal"], answer: 1, explanation: "'Between' is a preposition and must be followed by object pronouns — it should be 'between you and me', not 'between you and I'.", rule: "Prepositions take object pronouns (me, him, her), never subject pronouns (I, he, she).", trapcat: "Preposition + pronoun case error", level: "L3 Trap" },
    { q: "Improve: Each of the applicants were required to submit their portfolio along with a written statement of purpose.", options: ["Each of the applicants was required","Each of the applicants have required","No improvement","Each of the applicant were required"], answer: 0, explanation: "'Each' is always singular, regardless of the plural noun that follows — it should be 'was required', not 'were required'.", rule: "Each + of + plural noun still takes a singular verb.", trapcat: "Each + plural noun", level: "L2 Application" }
  ]
},
{
  id: "oct2_m2", label: "2 Oct · Evening English Mock (Deep)", timeLimitMin: 25,
  questions: [
    { q: "The findings of the survey, which involved over ten thousand respondents across various age groups, reveals a significant shift in consumer preferences.", options: ["a significant shift in consumer preferences","which involved over ten thousand respondents","The findings of the survey,","across various age groups, reveals"], answer: 3, explanation: "The true subject is 'findings' (plural) — the long embedded clause about the survey does not change this. It should be 'reveal', not 'reveals'.", rule: "Identify the real subject (findings, plural) before a long embedded relative clause; do not let the clause's own singular noun (survey) hijack the verb.", trapcat: "Embedded clause - subject-verb agreement", level: "L3 Trap" },
    { q: "Improve: The professor insisted that the assignment be submit before the end of the week without any extensions.", options: ["is submitted","was submitted","No improvement","be submitted"], answer: 3, explanation: "After 'insisted that', the subjunctive mood requires 'be' + past participle in a passive construction — 'be submitted', not 'be submit'.", rule: "Subjunctive passive: insisted that + subject + be + past participle.", trapcat: "Subjunctive passive", level: "L3 Trap" },
    { q: "Having been informed of the delay well in advance, the passengers' frustration was somewhat lessened by the airline's prompt communication.", options: ["the passengers' frustration lessened somewhat by itself","the passengers were somewhat less frustrated","the airline lessened the passengers, frustration","No improvement"], answer: 1, explanation: "This is a dangling modifier — 'Having been informed' should modify 'the passengers' (who were informed), not 'the passengers' frustration', which cannot itself be 'informed'.", rule: "The subject immediately following an introductory participial phrase must be the one who performed/received that action.", trapcat: "Dangling modifier", level: "L3 Trap" },
    { q: "Neither the CEO nor the board members, who had reviewed the merger proposal extensively, was fully convinced of its long-term viability.", options: ["of its long-term viability","who had reviewed the merger proposal extensively,","was fully convinced","Neither the CEO nor the board members,"], answer: 2, explanation: "Neither/nor agrees with the NEARER subject — 'board members' (plural) is nearer, so it should be 'were fully convinced', not 'was'.", rule: "Neither/nor → verb agrees with the nearer subject, regardless of an intervening embedded clause.", trapcat: "Neither/nor with embedded clause", level: "L3 Trap" },
    { q: "It is imperative that the organisation reviews its data protection policies in light of the recent regulatory changes.", options: ["that the organisation reviewing","that the organisation reviewed","that the organisation review","No improvement"], answer: 2, explanation: "After 'it is imperative that', the subjunctive mood requires the bare base verb form — 'review', not 'reviews'.", rule: "Subjunctive mood after imperative/essential/vital that: base verb form, no -s.", trapcat: "Subjunctive mood", level: "L3 Trap" },
    { q: "The witness's testimony, corroborated by several pieces of forensic evidence gathered at the scene, was ultimately found ___ by the jury.", options: ["credulous","credible","incredulous","creditable"], answer: 1, explanation: "'Credible' = believable, convincing. 'Credulous' means too easily believing others (a trait of a person, not evidence), 'creditable' means praiseworthy, 'incredulous' means unwilling to believe.", rule: "Credible (believable) vs credulous (gullible) — a classic close-pair vocabulary trap.", trapcat: "Close vocabulary trap", level: "L3 Trap" },
    { q: "Given the company's ___ financial position, further expansion at this stage would be an unnecessarily risky move.", options: ["precocious","precursory","precise","precarious"], answer: 3, explanation: "'Precarious' means uncertain, unstable, dangerously balanced — fitting a risky financial situation. Precocious relates to early development (of a child), precursory means preceding, precise means exact.", rule: "Precarious = unstable/risky; do not confuse with similarly-spelled but unrelated words.", trapcat: "Spelling-similar vocabulary trap", level: "L3 Trap" },
    { q: "The two departments finally agreed to ___ their efforts on the joint research initiative after months of miscommunication.", options: ["collaborate","correlate","coordinate","corroborate"], answer: 2, explanation: "'Coordinate' fits best here (organize joint efforts together); while 'collaborate' is close in meaning, the phrase 'coordinate their efforts' is the more precise, standard collocation compared to 'collaborate their efforts', which is not idiomatic English.", rule: "Coordinate efforts (standard collocation) vs collaborate ON something — check which verb takes 'efforts' as a direct object naturally.", trapcat: "Collocation precision", level: "L3 Trap" },
    { q: "Select the correctly punctuated sentence.", options: ["Although the meeting was postponed the agenda, remained unchanged.","Although, the meeting was postponed the agenda remained unchanged.","Although the meeting was postponed; the agenda remained unchanged.","Although the meeting was postponed, the agenda remained unchanged."], answer: 3, explanation: "A comma correctly separates the introductory subordinate clause ('Although the meeting was postponed') from the main clause, with no comma needed after 'Although' itself and no semicolon required.", rule: "Comma after an introductory subordinate clause, placed at the clause boundary, not mid-clause.", trapcat: "Punctuation - subordinate clause", level: "L2 Application" },
    { q: "Rearrange: P. The village had relied on a single well for generations. Q. Engineers proposed a new pipeline connecting it to the reservoir. R. That well ran dry during an unusually harsh summer. S. Residents were forced to walk several kilometres for water. ", options: ["R,P,S,Q","P,R,S,Q","P,Q,R,S","P,S,R,Q"], answer: 1, explanation: "Background (P: village relied on the well) -> problem (R: well ran dry) -> consequence (S: residents forced to walk) -> solution (Q: engineers propose pipeline).", rule: "Background -> problem -> consequence -> solution is a common four-part narrative structure to identify.", trapcat: "Sentence sequencing - narrative structure", level: "L3 Trap" },
    { q: "Synonym of PRAGMATIC:", options: ["Idealistic","Theoretical","Practical","Impractical"], answer: 2, explanation: "Pragmatic = dealing with things sensibly and realistically; practical.", rule: "Pragmatic = practical, realistic approach.", trapcat: "Vocabulary", level: "L2 Application" },
    { q: "Antonym of METICULOUS:", options: ["Careful","Careless","Precise","Thorough"], answer: 1, explanation: "Meticulous = showing great attention to detail; very careful. Opposite = careless. Precise/Thorough/Careful are all synonyms, placed as traps.", rule: "Antonym — meticulous ≠ careless.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who withdraws from social interaction and prefers to be alone:", options: ["Reprobate","Recluse","Recidivist","Renegade"], answer: 1, explanation: "Recluse = a person who lives in seclusion, avoiding others. Renegade = one who deserts a cause, Reprobate = an unprincipled person, Recidivist = one who repeatedly relapses into crime — all 'Re-' words used as sound-alike traps.", rule: "Recluse (seeks solitude) vs Renegade/Reprobate/Recidivist — all share the 'Re-' prefix but mean entirely different things.", trapcat: "Prefix-cluster vocabulary trap", level: "L3 Trap" },
    { q: "'To let sleeping dogs lie' means:", options: ["To trust someone completely","To ignore a problem until it grows worse","To allow pets to rest undisturbed","To avoid raising a topic that might cause trouble"], answer: 3, explanation: "'Let sleeping dogs lie' = to deliberately avoid interfering with a situation that could cause problems if disturbed.", rule: "Idiom: let sleeping dogs lie = avoid stirring up trouble.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To be caught between a rock and a hard place' means:", options: ["To make an easy decision quickly","To be faced with two equally difficult choices","To be physically trapped somewhere","To avoid making any decision at all"], answer: 1, explanation: "'Caught between a rock and a hard place' = facing a choice between two equally unpleasant or difficult options.", rule: "Idiom: rock and a hard place = dilemma between two bad choices.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: They should have completed the project by now.", options: ["The project should have completed by now","The project should have been completed by now","The project had to be completed by now","The project should be completed by now"], answer: 1, explanation: "Modal perfect passive: 'should have' + been + past participle — 'should have been completed'.", rule: "Modal + have + been + V3 for modal perfect passive.", trapcat: "Modal perfect passive", level: "L3 Trap" },
    { q: "Convert to indirect speech: The coach said to the team, \"You must practice harder if you want to win the championship.\"", options: ["The coach told the team you must practice harder if you want to win the championship","The coach told the team that they had to practice harder if they wanted to win the championship","The coach said the team must practice harder if they want to win the championship","The coach said that the team must practiced harder if they wanted to win the championship"], answer: 1, explanation: "'Must' (obligation) typically backshifts to 'had to' in reported speech; the conditional clause ('if you want') also backshifts consistently ('if they wanted').", rule: "Must (obligation) -> had to; backshift BOTH the main clause and the embedded conditional clause consistently.", trapcat: "Modal backshift with conditional clause", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Milennium","Millennium","Millenium","Millenneum"], answer: 1, explanation: "'Millennium' is correctly spelt with double L and double N — a very commonly misspelt word for exactly this reason.", rule: "Spelling: millennium needs BOTH double L and double N.", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: Scarcely had the negotiations begun when one of the delegates walked out in protest, and this action derail the entire summit.", options: ["when one of the delegates walked out in protest,","Scarcely had the negotiations begun","the entire summit","and this action derail"], answer: 3, explanation: "'This action' is singular and the sentence is in past tense (matching 'walked out') — it should be 'derailed', not 'derail'.", rule: "Maintain consistent past tense across a compound sentence; a singular subject needs the correctly inflected past-tense verb.", trapcat: "Tense consistency in compound sentence", level: "L2 Application" },
    { q: "Improve: The number of students who has enrolled for the summer programme have exceeded all previous years' records.", options: ["The number of students who has enrolled have exceeded","No improvement","The number of students who have enrolled has exceeded","The number of student who have enrolled has exceeded"], answer: 2, explanation: "Within 'who have enrolled', 'who' refers to 'students' (plural), needing 'have'. But 'the number...has exceeded' is correct since 'the number of' is the singular main subject — combining both fixes gives 'who have enrolled has exceeded'.", rule: "Two separate agreement points in one sentence: the relative clause verb (matches 'students', plural) and the main clause verb (matches 'the number', singular).", trapcat: "Double agreement point - relative clause + main subject", level: "L3 Trap" },
    { q: "Select the part with an error: The reason the flight was delay was due to unexpected mechanical issues discovered during the pre-flight inspection.", options: ["The reason the flight was delay","the pre-flight inspection","was due to unexpected mechanical issues","discovered during"], answer: 0, explanation: "'Was delay' is incorrect — the passive past tense requires the past participle 'delayed', giving 'the flight was delayed'.", rule: "Passive voice past tense: was/were + past participle (delayed), not the base form.", trapcat: "Passive voice - wrong verb form", level: "L2 Application" },
    { q: "Improve: Not only was the presentation informative, but also it was engaging enough to hold the audience's attention throughout.", options: ["but also was it engaging enough","No improvement","but it was also engaging enough","but it also was engaging enough to"], answer: 2, explanation: "The correlative pair 'not only...but also' requires parallel structure — 'not only WAS the presentation' pairs with 'but IT WAS also', keeping the subject-verb order consistent, not 'but also it was'.", rule: "Not only...but also requires parallel grammatical structure on both sides.", trapcat: "Correlative conjunction - parallel structure", level: "L3 Trap" },
    { q: "Select the part with an error: Between the two finalists, the judges found it difficult deciding who deserved the award more.", options: ["Between the two finalists,","the judges found it difficult","the award more","deciding who deserved"], answer: 1, explanation: "'Found it difficult' should be followed by a full infinitive construction — 'found it difficult TO DECIDE', not 'found it difficult deciding'.", rule: "'Find it + adjective' is followed by a 'to + verb' infinitive, not a gerund.", trapcat: "Infinitive after 'find it difficult'", level: "L3 Trap" },
    { q: "Improve: The government has announced a series of measures that will hopefully mitigating the impact of inflation on low-income households.", options: ["that hopefully will mitigating","that will hopefully mitigated","No improvement","that will hopefully mitigate"], answer: 3, explanation: "'Will' must be followed by the bare base verb — 'will mitigate', not 'will mitigating'.", rule: "Modal 'will' + base verb, never a gerund or past form.", trapcat: "Modal + base verb", level: "L2 Application" },
    { q: "One who is excessively concerned with formal rules and book knowledge, rather than practical understanding:", options: ["Prodigy","Pedant","Protagonist","Proponent"], answer: 1, explanation: "Pedant = a person overly concerned with minor details, rules, or formal book-learning rather than practical sense. Prodigy = a highly talented young person, Protagonist = the main character in a story, Proponent = one who argues in favour of something.", rule: "Pedant = fussy about rules/formal correctness, not practical wisdom.", trapcat: "Word meaning - specialization", level: "L3 Trap" }
  ]
},
{
  id: "oct2_m3", label: "2 Oct · Maths Mock (Deep)", timeLimitMin: 30,
  questions: [
    { q: "A quantity increases by 25%, then decreases by 20%, then increases by 10%. Find the net percentage change.", options: ["10% increase","15% increase","20% increase","5% increase"], answer: 0, explanation: "Combined multiplier = 1.25 x 0.80 x 1.10 = 1.10. Net change = 10% increase.", rule: "Combine all successive multipliers into one factor before comparing to 1.", trapcat: "Chained percentage", level: "L3 Trap" },
    { q: "A man sells two watches, each for Rs.1200. On one he gains 20% and on the other he loses 20%. Find his overall loss or gain percentage.", options: ["4% gain","No profit no loss","2% loss","4% loss"], answer: 3, explanation: "When the same SP gives x% profit on one item and x% loss on another, the net result is always a loss of x^2/100 percent. Here x=20, so loss=400/100=4%.", rule: "Same SP, +x% and -x% => always a net loss of x^2/100 percent.", trapcat: "Two-item profit-loss trap", level: "L3 Trap" },
    { q: "The difference between compound interest and simple interest on a sum for 2 years at 10% per annum is Rs.45. Find the sum.", options: ["Rs.5,000","Rs.4,800","Rs.4,500","Rs.4,000"], answer: 2, explanation: "For 2 years, CI-SI difference = P(r/100)^2. So P = 45/(0.10)^2 = 45/0.01 = Rs.4,500.", rule: "2-year CI-SI difference = P(r/100)^2.", trapcat: "Reverse CI-SI", level: "L3 Trap" },
    { q: "Pipe A can fill a tank in 6 hours, Pipe B in 9 hours, and outlet Pipe C can empty it in 18 hours. If all three are opened together, how long will it take to fill the tank?", options: ["4.5 hours","6 hours","5 hours","4 hours"], answer: 0, explanation: "Combined rate = 1/6+1/9-1/18 = 3/18+2/18-1/18 = 4/18 = 2/9. Time = 9/2 = 4.5 hours.", rule: "Outlet rate is subtracted from the combined inlet rate.", trapcat: "Pipes and cisterns", level: "L2 Application" },
    { q: "Two trains, 120 m and 180 m long, run towards each other on parallel tracks at 45 km/h and 63 km/h. Find the time they take to cross each other.", options: ["9 seconds","12 seconds","10 seconds","11 seconds"], answer: 2, explanation: "Relative speed (opposite directions) = 45+63=108 km/h = 108x5/18=30 m/s. Total length=120+180=300 m. Time=300/30=10 seconds.", rule: "Opposite directions: add speeds; divide total length by relative speed.", trapcat: "Train crossing - opposite direction", level: "L2 Application" },
    { q: "A can complete a work in 10 days. He works alone for 6 days, after which B (who can complete the work alone in 10 days) joins him. In how many more days will the work be completed?", options: ["2.5 days","1.5 days","3 days","2 days"], answer: 3, explanation: "A's rate=1/10. Work done in 6 days=6/10=0.6, remaining=0.4. Combined rate (A+B, both 1/10)=1/5. Remaining days=0.4/(1/5)=2.", rule: "Compute work done before the join, then use the combined rate for the remainder.", trapcat: "Staggered work", level: "L2 Application" },
    { q: "If a:b = 2:3 and b:c = 5:4, find a:c.", options: ["5:6","6:5","4:5","10:12"], answer: 0, explanation: "a:c = (2x5):(3x4) = 10:12 = 5:6 in simplest form.", rule: "Chain ratio, then simplify.", trapcat: "Ratio chain - simplification", level: "L2 Application" },
    { q: "A container has 60 litres of milk-water mixture in the ratio 2:1. If 20 litres of pure water is added, find the new ratio of milk to water.", options: ["2:3","4:5","1:1","3:4"], answer: 2, explanation: "Milk=40L, Water=20L. Adding 20L water: water=40L. New ratio = 40:40 = 1:1.", rule: "Milk stays fixed when only water is added.", trapcat: "Mixture dilution", level: "L2 Application" },
    { q: "The cost price of an article is Rs.100. It is marked up by 50% and then sold at a discount of 20%. Find the overall gain percentage.", options: ["30%","15%","25%","20%"], answer: 3, explanation: "MP=150, SP=150x0.8=120. Gain=20 on CP100, gain%=20%.", rule: "Compute MP from markup, then SP from discount on MP, then gain% on original CP.", trapcat: "Markup + discount chain", level: "L2 Application" },
    { q: "A rectangle's diagonal is 20 cm and its length is 16 cm. Find its breadth.", options: ["13 cm","12 cm","14 cm","10 cm"], answer: 1, explanation: "Breadth = sqrt(diagonal^2 - length^2) = sqrt(400-256) = sqrt(144) = 12 cm.", rule: "Apply Pythagoras: diagonal^2 = length^2 + breadth^2.", trapcat: "Rectangle geometry", level: "L2 Application" },
    { q: "If tanA = 8/15 and A is acute, find the value of (sinA + cosA)/(sinA - cosA).", options: ["-23/7","7/23","-7/23","23/7"], answer: 0, explanation: "From tanA=8/15 (8-15-17 triangle), sinA=8/17, cosA=15/17. (sinA+cosA)/(sinA-cosA) = (23/17)/(-7/17) = -23/7.", rule: "Build sinA, cosA from the implied right triangle, watch the sign.", trapcat: "Trig ratio identity", level: "L3 Trap" },
    { q: "Find the largest 4-digit number exactly divisible by 15, 20 and 35.", options: ["9800","9720","9660","9600"], answer: 2, explanation: "LCM(15,20,35)=420. Largest 4-digit multiple: 9999/420=23 remainder 339, so 9999-339=9660.", rule: "Find LCM first, then subtract (N mod LCM) from N.", trapcat: "LCM application", level: "L2 Application" },
    { q: "Find the remainder when 4^63 is divided by 7.", options: ["4","2","1","6"], answer: 2, explanation: "Powers of 4 mod 7 cycle: 4^1=4,4^2=2,4^3=1, then repeat (cycle length 3). 63 mod 3=0, meaning 4^63 corresponds to the 3rd position in the cycle (4^3 mod7=1). Remainder=1.", rule: "Find the cycle length under the given modulus; reduce the exponent modulo that cycle length.", trapcat: "Cyclicity", level: "L3 Trap" },
    { q: "Simplify: sqrt(50) + sqrt(18) - sqrt(72)", options: ["2 sqrt(2)","0","3 sqrt(2)","sqrt(2)"], answer: 0, explanation: "sqrt(50)=5sqrt(2), sqrt(18)=3sqrt(2), sqrt(72)=6sqrt(2). So 5sqrt(2)+3sqrt(2)-6sqrt(2) = 2 sqrt(2).", rule: "Reduce every surd to a multiple of the same root before combining.", trapcat: "Surds", level: "L2 Application" },
    { q: "The average of 9 consecutive multiples of 5 is 60. Find the largest of these numbers.", options: ["70","85","75","80"], answer: 3, explanation: "For 9 evenly-spaced terms, the average equals the 5th (middle) term: 60. Largest (4 steps above middle) = 60+4x5=80.", rule: "Average of odd count of evenly-spaced terms = middle term.", trapcat: "Consecutive multiples reverse", level: "L2 Application" },
    { q: "30 litres of a mixture has milk:water=3:2, and 45 litres of another mixture has milk:water=1:2. Find the combined ratio of milk to water.", options: ["1:2","14:11","3:2","11:14"], answer: 3, explanation: "Mix1: milk=18,water=12. Mix2: milk=15,water=30. Combined: milk=33,water=42=11:14 in simplest form.", rule: "Add milk-to-milk and water-to-water separately, then simplify.", trapcat: "Combine two mixtures", level: "L2 Application" },
    { q: "In a mixture of 90 litres, milk and water are in the ratio 4:1. How much water must be added to make the ratio 2:3?", options: ["80 litres","100 litres","70 litres","90 litres"], answer: 3, explanation: "Milk=72L,Water=18L. Let x be added: 72/(18+x)=2/3 => 216=36+2x => x=90.", rule: "Milk stays fixed; solve for the new water amount.", trapcat: "Mixture dilution reverse", level: "L2 Application" },
    { q: "The HCF of two numbers is 15 and their LCM is 450. If one number is 75, find the other.", options: ["80","95","85","90"], answer: 3, explanation: "Product = HCF x LCM = 15x450=6750. Other number = 6750/75=90.", rule: "Number1 x Number2 = HCF x LCM.", trapcat: "HCF-LCM", level: "L2 Application" },
    { q: "Sales (in units) of three products across 2 years: A:60->72, B:80->92, C:50->65. Which product had the highest percentage growth?", options: ["C","All equal","B","A"], answer: 0, explanation: "Growth%: A=(12/60)x100=20%. B=(12/80)x100=15%. C=(15/50)x100=30%. C has the highest percentage growth.", rule: "Compute percentage increase for each item separately, not raw increase.", trapcat: "DI percentage comparison", level: "L2 Application" },
    { q: "Find the inradius of a right-angled triangle with sides 8 cm, 15 cm, and 17 cm (hypotenuse 17 cm).", options: ["3.5 cm","3 cm","4 cm","2.5 cm"], answer: 1, explanation: "For a right triangle, inradius = (leg1+leg2-hypotenuse)/2 = (8+15-17)/2 = 6/2 = 3 cm.", rule: "Right-triangle inradius shortcut: (a+b-c)/2.", trapcat: "Geometry", level: "L2 Application" },
    { q: "A invests Rs.15,000 for 10 months, B invests Rs.20,000 for 8 months, and C invests Rs.25,000 for 6 months. If the total profit is Rs.4,600, find A's share.", options: ["Rs.1,700","Rs.1,400","Rs.1,500","Rs.1,600"], answer: 2, explanation: "Capital-months: A=150000,B=160000,C=150000,total=460000. A's share=4600x(150000/460000)=1,500.", rule: "Profit shares use investment x time, not investment alone.", trapcat: "Partnership - staggered", level: "L2 Application" },
    { q: "A boat covers 45 km downstream in 3 hours. In the time it takes to cover 36 km downstream, it covers 18 km upstream. Find the speed of the stream.", options: ["4 km/h","3.75 km/h","4.25 km/h","3.5 km/h"], answer: 1, explanation: "Downstream speed=45/3=15 km/h. Time for 36km downstream=36/15=2.4h. Upstream speed=18/2.4=7.5 km/h. Stream speed=(15-7.5)/2=3.75 km/h.", rule: "Derive the time from one scenario, apply it to the other before finding stream speed.", trapcat: "Boats - indirect derivation", level: "L3 Trap" },
    { q: "In a two-digit number, the sum of the digits is 9. If the digits are reversed, the new number exceeds the original by 45. Find the original number.", options: ["45","36","27","18"], answer: 2, explanation: "Let tens=t,units=u. t+u=9. 9(u-t)=45 => u-t=5. Solving: u=7,t=2. Original number=27 (check: reversed=72, 72-27=45).", rule: "Set up two equations from digit sum and reversal difference.", trapcat: "Two-digit number problem", level: "L3 Trap" },
    { q: "A can complete a work in 18 days, B in 27 days. They work together for 6 days, after which A leaves and B completes the rest. If the total wage is Rs.4,500, paid in proportion to work done, find A's share.", options: ["Rs.1,200","Rs.1,800","Rs.1,600","Rs.1,500"], answer: 3, explanation: "In 6 days, A completes 6/18=1/3 of the work. Wage proportional to work done: A's share=(1/3)x4500=Rs.1,500.", rule: "Wages tied to fraction of total work completed, not days worked.", trapcat: "Work + wage split", level: "L2 Application" },
    { q: "The angle of elevation of the top of a tower from a point 40 m from its base is 45 degrees. If the observer moves 10 m closer, find the new angle of elevation's tangent value (height stays the same).", options: ["4/3","3/4","5/4","4/5"], answer: 0, explanation: "At 45 degrees, height=distance=40m (since tan45=1). New distance=40-10=30m. New tan(angle)=height/new distance=40/30=4/3.", rule: "Recover height from the first angle, then use it with the new distance.", trapcat: "Height and distance - two stage", level: "L3 Trap" }
  ]
},
{
  id: "oct2_m4", label: "2 Oct · GS Mock (Statement-based)", timeLimitMin: 30,
  questions: [
    { q: "Consider the following statements: 1. Article 21A makes free and compulsory education a Fundamental Right for children aged 6-14. 2. This was added by the 86th Constitutional Amendment, 2002. 3. The corresponding Fundamental Duty regarding education was added at the same time by the same amendment. Which of the above is/are correct?", options: ["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"], answer: 3, explanation: "All three are correct: the 86th Amendment (2002) added both Article 21A (Fundamental Right) and the corresponding 11th Fundamental Duty (Article 51A(k)) in the same amendment.", rule: "86th Amendment — Article 21A + 11th Fundamental Duty, same amendment.", trapcat: "Statement-based - Polity", level: "L3 Trap" },
    { q: "Consider the following statements: 1. The Rajya Sabha can be dissolved by the President. 2. One-third of Rajya Sabha members retire every two years. 3. A person must be at least 30 years old to be a member of the Rajya Sabha. Which of the above is/are correct?", options: ["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"], answer: 1, explanation: "Statements 2 and 3 are correct. Statement 1 is false — the Rajya Sabha is a permanent body and can NEVER be dissolved, unlike the Lok Sabha.", rule: "Rajya Sabha is permanent, never dissolved; minimum age 30; one-third retire every 2 years.", trapcat: "Statement-based - Polity", level: "L3 Trap" },
    { q: "Consider the following statements: 1. The Battle of Buxar (1764) was fought between the British and a combined force of Mir Qasim, Shuja-ud-Daulah, and Shah Alam II. 2. The British victory at Buxar led directly to the Treaty of Allahabad (1765). 3. The Treaty of Allahabad granted the British Diwani rights over Bengal, Bihar, and Odisha. Which of the above is/are correct?", options: ["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"], answer: 3, explanation: "All three statements are correct and historically well-established: Buxar (1764) was fought against this three-way alliance, leading to the Treaty of Allahabad (1765) which granted Diwani rights (revenue collection) over Bengal, Bihar and Odisha.", rule: "Battle of Buxar (1764) -> Treaty of Allahabad (1765) -> Diwani rights.", trapcat: "Statement-based - History", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Deccan Plateau is bordered by the Western Ghats and Eastern Ghats. 2. The Western Ghats are higher in elevation than the Eastern Ghats on average. 3. The Eastern Ghats are a continuous, unbroken mountain range along the eastern coast. Which of the above is/are correct?", options: ["1 and 2 only","1 only","1, 2 and 3","2 and 3 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Eastern Ghats are DISCONTINUOUS and irregular, broken up by several rivers flowing into the Bay of Bengal, unlike the more continuous Western Ghats.", rule: "Western Ghats: continuous, higher. Eastern Ghats: discontinuous, lower.", trapcat: "Statement-based - Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. Repo Rate is the rate at which RBI lends to commercial banks. 2. An increase in Repo Rate generally makes loans costlier and helps control inflation. 3. Repo Rate is decided by the Union Finance Ministry, not the RBI. Which of the above is/are correct?", options: ["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"], answer: 3, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Repo Rate is decided by the RBI's Monetary Policy Committee (MPC), not the Finance Ministry.", rule: "Repo Rate is an RBI/MPC decision, not a Finance Ministry one.", trapcat: "Statement-based - Economy", level: "L2 Application" },
    { q: "Consider the following statements: 1. Photosynthesis occurs only in the presence of sunlight. 2. Respiration occurs only in the absence of sunlight. 3. Both photosynthesis and respiration involve gas exchange. Which of the above is/are correct?", options: ["1 and 3 only","1, 2 and 3","1 only","2 and 3 only"], answer: 0, explanation: "Statements 1 and 3 are correct. Statement 2 is false — respiration occurs CONTINUOUSLY in living cells, both day and night, not only in the absence of sunlight.", rule: "Photosynthesis needs light; respiration happens continuously (day and night).", trapcat: "Statement-based - Biology", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Champaran Satyagraha (1917) was Gandhi's first major movement in India. 2. It was primarily concerned with indigo cultivators being forced to grow indigo under exploitative conditions. 3. The movement took place in present-day Bihar. Which of the above is/are correct?", options: ["1 and 2 only","1, 2 and 3","2 and 3 only","1 only"], answer: 1, explanation: "All three statements are correct: Champaran (1917), Gandhi's first major Indian movement, addressed indigo cultivators' exploitation under the 'Tinkathia' system in Bihar.", rule: "Champaran Satyagraha (1917) — Gandhi's first India movement, indigo cultivators, Bihar.", trapcat: "Statement-based - History", level: "L1 Direct" },
    { q: "Consider the following statements: 1. The Rann of Kutch is a salt marsh located in Gujarat. 2. It is divided into the Great Rann and the Little Rann. 3. The Rann of Kutch remains submerged in water throughout the entire year. Which of the above is/are correct?", options: ["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"], answer: 2, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Rann of Kutch is submerged only during the monsoon/certain periods and becomes a dry salt desert for much of the year, not submerged throughout.", rule: "Rann of Kutch — seasonal submersion, not year-round.", trapcat: "Statement-based - Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. Disguised unemployment is common in the Indian agricultural sector. 2. It refers to a situation where more people are employed in a job than actually needed, with marginal productivity of extra workers being zero. 3. Disguised unemployment is easy to measure directly through official unemployment statistics. Which of the above is/are correct?", options: ["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — disguised unemployment is notoriously DIFFICULT to measure directly, since those affected appear 'employed' in official statistics despite contributing little to output.", rule: "Disguised unemployment: common in agriculture, zero marginal productivity, hard to measure directly.", trapcat: "Statement-based - Economy", level: "L2 Application" },
    { q: "Consider the following statements: 1. The pH of human blood is normally slightly alkaline, around 7.4. 2. A pH below 7 indicates an alkaline solution. 3. Gastric juice in the stomach has a highly acidic pH. Which of the above is/are correct?", options: ["1, 2 and 3","1 and 3 only","1 only","2 and 3 only"], answer: 1, explanation: "Statements 1 and 3 are correct. Statement 2 is false — a pH BELOW 7 indicates an ACIDIC solution, not alkaline; alkaline solutions have pH above 7.", rule: "pH < 7 = acidic; pH > 7 = alkaline; pH = 7 = neutral.", trapcat: "Statement-based - Chemistry", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Second Round Table Conference (1931) was attended by Gandhi as the sole Congress representative. 2. It failed primarily due to disagreements over minority representation. 3. All three Round Table Conferences (1930-32) resulted in the immediate grant of full Dominion Status to India. Which of the above is/are correct?", options: ["2 and 3 only","1 and 2 only","1 only","1, 2 and 3"], answer: 1, explanation: "Statements 1 and 2 are correct. Statement 3 is false — none of the three Round Table Conferences resulted in an immediate grant of Dominion Status; they eventually led to the Government of India Act, 1935, a much more limited outcome.", rule: "Round Table Conferences (1930-32) did not grant Dominion Status — led to the 1935 Act instead.", trapcat: "Statement-based - History", level: "L2 Application" },
    { q: "Consider the following statements: 1. India's Exclusive Economic Zone (EEZ) extends up to 200 nautical miles from the baseline. 2. Within the EEZ, India has exclusive rights to exploit natural resources like fisheries and minerals. 3. The territorial waters of India extend up to 200 nautical miles as well, identical to the EEZ. Which of the above is/are correct?", options: ["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — territorial waters extend only up to 12 nautical miles, a much smaller zone than the 200 nautical mile EEZ; the two are not identical.", rule: "Territorial waters = 12 nautical miles; EEZ = 200 nautical miles (distinct zones).", trapcat: "Statement-based - Geography/Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Vitamin C deficiency causes the disease Scurvy. 2. Vitamin C is water-soluble and cannot be stored in the body for long periods. 3. Citrus fruits are a poor source of Vitamin C. Which of the above is/are correct?", options: ["1, 2 and 3","2 and 3 only","1 and 2 only","1 only"], answer: 2, explanation: "Statements 1 and 2 are correct. Statement 3 is false — citrus fruits (oranges, lemons) are in fact one of the BEST-KNOWN sources of Vitamin C, not a poor source.", rule: "Vitamin C: water-soluble, deficiency causes Scurvy, citrus fruits are a rich source.", trapcat: "Statement-based - Nutrition", level: "L1 Direct" },
    { q: "Consider the following statements: 1. The Bhakra Nangal Dam is built on the Sutlej river. 2. It is one of the highest gravity dams in Asia. 3. The dam is located entirely within the state of Punjab. Which of the above is/are correct?", options: ["1, 2 and 3","1 only","2 and 3 only","1 and 2 only"], answer: 3, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Bhakra Dam is located at the Punjab-Himachal Pradesh border (in Bilaspur district, Himachal Pradesh), not entirely within Punjab.", rule: "Bhakra Dam — on Sutlej, at the Punjab-Himachal Pradesh border.", trapcat: "Statement-based - Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Non-Aligned Movement (NAM) was founded in 1961 in Belgrade. 2. India, along with Yugoslavia, Egypt, Ghana, and Indonesia, were among its founding members. 3. NAM's founding principle was for member countries to formally ally with either the USA or the USSR bloc, whichever offered more aid. Which of the above is/are correct?", options: ["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false and contradicts the entire premise — NAM's founding principle was explicitly NOT to formally align with either Cold War bloc (USA or USSR), which is precisely what 'non-aligned' means.", rule: "NAM (1961, Belgrade) — explicitly non-aligned with either Cold War bloc.", trapcat: "Statement-based - International Relations", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Chipko Movement (1973) was a forest conservation movement started in Uttarakhand. 2. It involved villagers, especially women, hugging trees to prevent them from being felled. 3. Sunderlal Bahuguna and Chandi Prasad Bhatt were prominent leaders associated with this movement. Which of the above is/are correct?", options: ["2 and 3 only","1 and 2 only","1 only","1, 2 and 3"], answer: 3, explanation: "All three statements are correct: the Chipko Movement (1973, then Uttar Pradesh, now Uttarakhand) involved tree-hugging protests, with Sunderlal Bahuguna and Chandi Prasad Bhatt as key leaders.", rule: "Chipko Movement (1973) — Bahuguna and Bhatt, tree-hugging forest conservation.", trapcat: "Statement-based - Environmental History", level: "L1 Direct" },
    { q: "Consider the following statements: 1. The Rajya Sabha has equal legislative power with the Lok Sabha on all matters. 2. Money Bills can only be introduced in the Lok Sabha. 3. The Rajya Sabha can only recommend changes to a Money Bill, which the Lok Sabha may accept or reject. Which of the above is/are correct?", options: ["1 and 2 only","1, 2 and 3","1 only","2 and 3 only"], answer: 3, explanation: "Statements 2 and 3 are correct. Statement 1 is false — the Rajya Sabha does NOT have equal power on Money Bills specifically (a key exception to otherwise largely equal status on ordinary legislation); its role there is only recommendatory.", rule: "Rajya Sabha has near-equal power generally, but a specific, limited role on Money Bills only.", trapcat: "Statement-based - Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Coral reefs are formed by colonies of tiny marine animals called coral polyps. 2. Corals thrive best in cold, deep ocean waters. 3. The Great Barrier Reef, the world's largest coral reef system, is located off the coast of Australia. Which of the above is/are correct?", options: ["1, 2 and 3","2 and 3 only","1 and 3 only","1 only"], answer: 2, explanation: "Statements 1 and 3 are correct. Statement 2 is false — corals thrive in WARM, shallow, clear tropical waters, not cold, deep ones, which is why reefs form mainly in tropical/subtropical zones.", rule: "Coral reefs need warm, shallow, clear tropical waters — not cold, deep water.", trapcat: "Statement-based - Marine Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Preamble was amended once, by the 42nd Amendment (1976). 2. The Preamble is considered part of the Constitution and can be used to interpret ambiguous provisions. 3. The Preamble was the very first part of the Constitution to be drafted by the Constituent Assembly. Which of the above is/are correct?", options: ["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"], answer: 3, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Preamble was actually one of the LAST parts finalized by the Constituent Assembly (based on the Objectives Resolution but formally adopted near the end), not the first.", rule: "Preamble amended once (42nd Amendment); finalized near the END of the drafting process, not the beginning.", trapcat: "Statement-based - Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Diabetes mellitus is caused by insufficient insulin production or the body's ineffective use of insulin. 2. Type 1 diabetes is typically an autoimmune condition, often diagnosed in children/young adults. 3. Type 2 diabetes cannot be managed through lifestyle changes and always requires insulin injections from diagnosis. Which of the above is/are correct?", options: ["2 and 3 only","1 and 2 only","1 only","1, 2 and 3"], answer: 1, explanation: "Statements 1 and 2 are correct. Statement 3 is false — Type 2 diabetes CAN often be managed (at least initially) through diet, exercise, and oral medication, and does not always require insulin from the point of diagnosis.", rule: "Type 2 diabetes is often manageable via lifestyle/oral medication, unlike the false absolute claim.", trapcat: "Statement-based - Health Science", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Quit India Resolution was passed by the AICC in Bombay on 8 August 1942. 2. Gandhi gave the 'Do or Die' call during this movement. 3. Most major Congress leaders remained free throughout the Quit India Movement to coordinate protests nationally. Which of the above is/are correct?", options: ["2 and 3 only","1 and 2 only","1, 2 and 3","1 only"], answer: 1, explanation: "Statements 1 and 2 are correct. Statement 3 is false — most major Congress leaders (including Gandhi and Nehru) were ARRESTED almost immediately after the movement's launch, leaving it largely leaderless and spontaneous at the local level.", rule: "Quit India (Aug 1942) — most top leaders arrested immediately, not left free to coordinate.", trapcat: "Statement-based - History", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Reserve Bank of India was nationalised in 1949. 2. Prior to nationalisation, RBI was a privately owned institution since its establishment in 1935. 3. India has never had any privately-owned central bank at any point in its history. Which of the above is/are correct?", options: ["1 only","1 and 2 only","1, 2 and 3","2 and 3 only"], answer: 1, explanation: "Statements 1 and 2 are correct. Statement 3 is false and directly contradicts statement 2 — RBI WAS privately owned (with private shareholders) from 1935 until its nationalisation in 1949, so India did have a privately-owned central bank for that period.", rule: "RBI: private shareholding 1935-1949, then nationalised.", trapcat: "Statement-based - Economy", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Sundarbans, the world's largest mangrove forest, is shared between India and Bangladesh. 2. It is home to the Royal Bengal Tiger. 3. Mangrove forests generally cannot survive in saline (salty) water conditions. Which of the above is/are correct?", options: ["1 only","1, 2 and 3","1 and 2 only","2 and 3 only"], answer: 2, explanation: "Statements 1 and 2 are correct. Statement 3 is false — mangroves are specifically ADAPTED to survive in saline, brackish water conditions found in tidal river deltas, which is precisely why they thrive in the Sundarbans delta.", rule: "Mangroves are salt-tolerant by adaptation, not intolerant of saline water.", trapcat: "Statement-based - Ecology", level: "L2 Application" },
    { q: "Consider the following statements: 1. India's Constitution is the longest written constitution of any sovereign country in the world. 2. It originally had 22 Parts and 8 Schedules at the time of adoption in 1949. 3. The number of Articles and Schedules has remained exactly the same since 1949, with no additions ever made. Which of the above is/are correct?", options: ["1 and 2 only","1 only","1, 2 and 3","2 and 3 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — both Articles and Schedules have been ADDED over time through various amendments (e.g. Article 21A, the 12th Schedule), so the count has changed significantly since 1949.", rule: "Constitution's Parts/Articles/Schedules have grown via amendments since 1949, not stayed frozen.", trapcat: "Statement-based - Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Continental drift theory was proposed by Alfred Wegener. 2. Wegener proposed that all continents were once joined together in a single supercontinent called Pangaea. 3. Wegener's theory was immediately and universally accepted by the scientific community upon publication. Which of the above is/are correct?", options: ["1, 2 and 3","1 and 2 only","2 and 3 only","1 only"], answer: 1, explanation: "Statements 1 and 2 are correct. Statement 3 is false — Wegener's theory (1912) faced significant scientific SKEPTICISM and rejection for decades, gaining wide acceptance only later once plate tectonics theory provided a mechanism in the mid-20th century.", rule: "Wegener's continental drift theory was initially rejected, not immediately accepted.", trapcat: "Statement-based - Geology", level: "L2 Application" }
  ]
},
{
  id: "weak_drill_1", label: "Weak-Topics Drill (from 30 Sep attempt)", timeLimitMin: 45,
  questions: [
    { q: "In a mixture of 50 litres, milk and water are in the ratio 3:2. If 15 litres of pure water is added, find the new ratio of milk to water.", options: ["2:3","3:5","6:7","5:6"], answer: 2, explanation: "Milk=30L, Water=20L. Adding 15L water: water=35L. New ratio=30:35=6:7.", rule: "Milk stays fixed when only water is added.", trapcat: "Mixture & Alligation", level: "L2 Application" },
    { q: "20 litres of a mixture has milk and water in equal ratio (1:1). 30 litres of another mixture has milk:water=2:3. Find the combined ratio of milk to water.", options: ["11:14","2:3","14:11","1:1"], answer: 0, explanation: "Mix1: milk=10,water=10. Mix2: milk=12,water=18. Combined: milk=22,water=28=11:14.", rule: "Add milk-to-milk and water-to-water separately, then simplify.", trapcat: "Mixture & Alligation", level: "L2 Application" },
    { q: "Milk costing Rs.20/litre is to be mixed with water (free) to prepare a mixture worth Rs.15/litre. Find the ratio of milk to water needed.", options: ["3:1","1:3","1:4","4:1"], answer: 0, explanation: "By alligation: water:milk = (20-15):(15-0) = 5:15 = 1:3, so milk:water = 3:1.", rule: "Alligation with a zero-cost component (water) still follows (CP-MP):(MP-0).", trapcat: "Mixture & Alligation", level: "L3 Trap" },
    { q: "Find the value of 2 x sin30 x cos30.", options: ["1","sqrt(3)/2","1/2","sqrt(3)"], answer: 1, explanation: "2 sinA cosA = sin(2A). So 2 sin30 cos30 = sin60 = sqrt(3)/2.", rule: "Recognize the double-angle identity 2sinAcosA=sin2A instead of substituting values separately.", trapcat: "Trigonometry", level: "L2 Application" },
    { q: "If tanA = 1 and A is acute, find the value of sinA + cosA.", options: ["1","1/sqrt(2)","2","sqrt(2)"], answer: 3, explanation: "tanA=1 means A=45 degrees, so sinA=cosA=1/sqrt(2). Sum = 2/sqrt(2) = sqrt(2).", rule: "tanA=1 is the standard 45-degree angle — memorize sinA=cosA=1/sqrt(2) directly.", trapcat: "Trigonometry", level: "L2 Application" },
    { q: "The average of 15 numbers is 20. When one number is removed, the average of the remaining 14 numbers becomes 21. Find the removed number.", options: ["35","21","6","14"], answer: 2, explanation: "Total before=15x20=300. Total after=14x21=294. Removed number=300-294=6.", rule: "Removed value = (old total) - (new total), computed from the averages x counts.", trapcat: "Average", level: "L2 Application" },
    { q: "Find the average of the first 15 even natural numbers.", options: ["14","17","15","16"], answer: 3, explanation: "First 15 even numbers: 2,4,...,30. Average = (2+30)/2 = 16 (average of an arithmetic sequence = average of first and last term).", rule: "Average of an AP = (first term + last term)/2.", trapcat: "Average", level: "L1 Direct" },
    { q: "Sales (in units) of 4 products: A=120, B=150, C=90, D=140. Which two products combined have the HIGHEST total sales?", options: ["A and B","A and D","B and D","B and C"], answer: 2, explanation: "B+D=150+140=290, the highest of all possible pairs (A+D=260, A+B=270, B+C=240).", rule: "Check all relevant pairs systematically rather than assuming the two largest individual values automatically pair best (though here they do) — verify by computing.", trapcat: "Data Interpretation", level: "L2 Application" },
    { q: "Find the circumference and area of a circle with radius 14 cm. (Use pi=22/7)", options: ["Circumference=88cm, Area=308 sq cm","Circumference=176cm, Area=616 sq cm","Circumference=44cm, Area=616 sq cm","Circumference=88cm, Area=616 sq cm"], answer: 3, explanation: "Circumference=2(22/7)(14)=88cm. Area=(22/7)(14^2)=616 sq cm.", rule: "Circumference=2(pi)r; Area=(pi)r^2 — compute both independently.", trapcat: "Geometry", level: "L1 Direct" },
    { q: "Find a triangle's area with sides 6 cm, 8 cm, and 10 cm.", options: ["20 sq cm","48 sq cm","30 sq cm","24 sq cm"], answer: 3, explanation: "6-8-10 is a right triangle (6^2+8^2=10^2). Area=(1/2)x6x8=24 sq cm.", rule: "Check for a Pythagorean triple first — it lets you skip Heron's formula entirely.", trapcat: "Geometry", level: "L2 Application" },
    { q: "Find the smallest number that must be subtracted from 1000 to make it exactly divisible by 17.", options: ["10","3","14","17"], answer: 2, explanation: "1000 divided by 17 gives remainder 14 (17x58=986, 1000-986=14). Subtracting this remainder (14) gives an exact multiple.", rule: "To make N divisible by d by SUBTRACTING, subtract exactly (N mod d).", trapcat: "Number System", level: "L2 Application" },
    { q: "Find the unit digit of 7^95.", options: ["1","9","7","3"], answer: 3, explanation: "Unit digits of powers of 7 cycle: 7,9,3,1 (cycle length 4). 95 mod 4 = 3, corresponding to the 3rd position in the cycle: 3.", rule: "Find the cycle length of unit digits, reduce the exponent modulo that length.", trapcat: "Number System", level: "L2 Application" },
    { q: "If x+y=10 and xy=21, find the value of x^2+y^2.", options: ["79","42","100","58"], answer: 3, explanation: "x^2+y^2=(x+y)^2-2xy=100-42=58.", rule: "Use the identity directly rather than solving for x and y individually.", trapcat: "Algebra", level: "L2 Application" },
    { q: "If a-b=4 and a^2+b^2=40, find the value of ab.", options: ["8","12","24","16"], answer: 1, explanation: "(a-b)^2=a^2+b^2-2ab => 16=40-2ab => ab=(40-16)/2=12.", rule: "Use (a-b)^2 expansion to isolate ab.", trapcat: "Algebra", level: "L2 Application" },
    { q: "A shopkeeper sells an item at a 10% loss. If he had sold it for Rs.80 more, he would have made a 10% profit. Find the cost price.", options: ["Rs.400","Rs.440","Rs.420","Rs.360"], answer: 0, explanation: "Let CP=x. SP(loss)=0.9x. SP(profit)=1.1x. Difference=1.1x-0.9x=0.2x=80 => x=400.", rule: "The difference between the two SP values equals the difference in percentages applied to CP.", trapcat: "Profit & Loss (bonus)", level: "L2 Application" },
    { q: "Select the set that follows the same pattern as (16, 36, 64).", options: ["(8, 27, 125)","(9, 27, 81)","(25, 50, 75)","(4, 100, 144)"], answer: 3, explanation: "16=4^2, 36=6^2, 64=8^2 — perfect squares of even numbers. (4,100,144)=2^2,10^2,12^2, also perfect squares of even numbers.", rule: "Identify BOTH the pattern type (perfect squares) AND any sub-condition (even bases) before matching.", trapcat: "Classification", level: "L2 Application" },
    { q: "Select the odd one out.", options: ["Sphere","Rectangle","Triangle","Square"], answer: 0, explanation: "Triangle, Square and Rectangle are all 2D (flat) shapes. Sphere is a 3D (solid) shape.", rule: "Check the dimensional category (2D vs 3D), not just 'these are all shapes'.", trapcat: "Classification", level: "L1 Direct" },
    { q: "Five people A,B,C,D,E sit in a row facing North. C sits exactly in the middle. A sits immediately to the left of C. E sits immediately to the right of C. B sits at the extreme left end. D sits at the extreme right end. Who sits second from the left?", options: ["C","B","E","A"], answer: 3, explanation: "Building the row: B(1st), A(2nd), C(3rd,middle), E(4th), D(5th). Second from the left is A.", rule: "Place all five using the fixed/relative clues before answering a specific-position question.", trapcat: "Seating Arrangement", level: "L2 Application" },
    { q: "Pointing to a girl, a boy said, 'She is the daughter of my father's only sister.' How is the girl related to the boy?", options: ["Aunt","Sister","Niece","Cousin"], answer: 3, explanation: "'My father's only sister' = the boy's paternal aunt. Her daughter is the boy's cousin.", rule: "Resolve the innermost relation first (father's sister = aunt), then apply the outer one (her daughter = cousin).", trapcat: "Blood Relations", level: "L2 Application" },
    { q: "If in a certain code, PLANT is written as SODQW, how is GRAPE written in the same code?", options: ["JTDSH","JUDHS","IUDSH","JUDSH"], answer: 3, explanation: "Each letter shifts forward by 3: P->S,L->O,A->D,N->Q,T->W (confirms the rule). Applying +3 to GRAPE: G->J,R->U,A->D,P->S,E->H. Code=JUDSH.", rule: "Verify the shift amount on the given pair first, then apply the same shift consistently.", trapcat: "Coding-Decoding", level: "L2 Application" },
    { q: "A clock shows 6:15. What time does its mirror image show?", options: ["5:15","6:45","7:45","5:45"], answer: 3, explanation: "Mirror time = 11:60 - actual time. 11:60 - 6:15 = 5:45.", rule: "Always apply the fixed formula 11:60 minus actual time.", trapcat: "Non-Verbal Reasoning", level: "L2 Application" },
    { q: "Which Article of the Indian Constitution deals with the Right to Constitutional Remedies?", options: ["Article 14","Article 19","Article 32","Article 21"], answer: 2, explanation: "Article 32 gives the right to move the Supreme Court for enforcement of Fundamental Rights — called the 'heart and soul' of the Constitution by Ambedkar.", rule: "Article 32 = Right to Constitutional Remedies.", trapcat: "Polity", level: "L1 Direct" },
    { q: "Which of the following is the correct order of precedence: who presides over a joint sitting of Parliament?", options: ["Chairman of the Rajya Sabha","Speaker of the Lok Sabha","President of India","Vice-President of India"], answer: 1, explanation: "A joint sitting of both Houses of Parliament (Article 108) is presided over by the Speaker of the Lok Sabha.", rule: "Joint sitting -> Speaker of Lok Sabha presides (not the Rajya Sabha Chairman).", trapcat: "Polity", level: "L2 Application" },
    { q: "The Narmada river originates from which plateau?", options: ["Chota Nagpur Plateau","Amarkantak Plateau","Malwa Plateau","Deccan Plateau"], answer: 1, explanation: "The Narmada originates from the Amarkantak Plateau in Madhya Pradesh.", rule: "Narmada's source — Amarkantak.", trapcat: "Geography", level: "L1 Direct" },
    { q: "Who was the first woman President of India?", options: ["Indira Gandhi","Sarojini Naidu","Droupadi Murmu","Pratibha Patil"], answer: 3, explanation: "Pratibha Patil became India's first woman President in 2007. Droupadi Murmu (2022) is the second woman President and the first tribal President.", rule: "Pratibha Patil = first woman President; do not confuse with Droupadi Murmu's distinct 'first tribal President' title.", trapcat: "Static GK", level: "L2 Application" },
    { q: "The 1943 Bengal Famine occurred during the tenure of which British Viceroy?", options: ["Lord Wavell","Lord Linlithgow","Lord Mountbatten","Lord Curzon"], answer: 1, explanation: "The Bengal Famine of 1943 occurred during Lord Linlithgow's tenure as Viceroy (1936-1943); Lord Wavell succeeded him later that same year and dealt with its aftermath.", rule: "Bengal Famine (1943) — Linlithgow was Viceroy when it occurred.", trapcat: "History", level: "L3 Trap" },
    { q: "'Disinflation' refers to:", options: ["A reduction in the RATE of inflation (prices still rising, just more slowly)","Complete price stability with zero inflation","A sudden sharp increase in inflation","Prices falling in absolute terms (negative inflation)"], answer: 0, explanation: "Disinflation means the inflation rate is decreasing (e.g. from 8% to 5%), but prices are still rising, just at a slower pace — different from deflation (actual price decline).", rule: "Disinflation = slower price rise; Deflation = actual price fall — a frequently confused pair.", trapcat: "Economy", level: "L3 Trap" },
    { q: "Which Five Year Plan is known as a period of 'Plan Holiday' when no formal Five Year Plan was in effect?", options: ["1978-1980 (between Fifth and Sixth Plans)","1966-1969 (between Third and Fourth Plans)","1990-1992 (between Eighth and Ninth Plans)","1951-1956 (First Plan itself)"], answer: 1, explanation: "1966-1969 is called the 'Plan Holiday', following the failure of the Third Plan and before the Fourth Plan began, during which annual plans were used instead.", rule: "Plan Holiday (1966-69) is distinct from the Rolling Plan (1978-80) — two different 'gap' periods in Five Year Plan history.", trapcat: "Economy", level: "L3 Trap" },
    { q: "Improve: She is one of the most talented singer in the competition.", options: ["one of the most talent singer","one of the most talented singers","the most talented singer","No improvement"], answer: 1, explanation: "'One of the' always takes a plural noun — it should be 'singers', not 'singer'.", rule: "One of the + plural noun, always.", trapcat: "Sentence Improvement", level: "L2 Application" },
    { q: "Synonym of METICULOUS:", options: ["Reckless","Careful","Careless","Hasty"], answer: 1, explanation: "Meticulous = showing great attention to detail; careful.", rule: "Meticulous = extremely careful/precise.", trapcat: "Synonym", level: "L1 Direct" },
    { q: "He apologized ___ the delay and promised to be ___ time in the future.", options: ["for, on","of, in","for, in","about, on"], answer: 0, explanation: "'Apologize for' + reason. 'On time' is the fixed expression meaning punctual.", rule: "Apologize for + reason; on time = punctual.", trapcat: "Fill in the Blanks", level: "L2 Application" },
    { q: "She is good ___ mathematics but weak ___ languages.", options: ["in, at","at, in","at, at","in, in"], answer: 1, explanation: "'Good at' + subject/skill; 'weak in' + subject/skill — two different fixed prepositions for similar-sounding contexts.", rule: "Good AT a subject; weak IN a subject — do not assume both take the same preposition.", trapcat: "Fill in the Blanks", level: "L3 Trap" },
    { q: "Urban gardening has become increasingly (1)___ in recent years, as city dwellers seek ways to grow their own food despite limited space. Many apartment residents now (2)___ small balconies into thriving vegetable patches, using vertical planters and hanging pots to (3)___ every available inch. Select the best word for blank (1).", options: ["popular","populate","popularly","popularity"], answer: 0, explanation: "'Has become increasingly (1)' needs an adjective after 'become' — 'popular'.", rule: "Become + adjective (not noun/adverb/verb).", trapcat: "Cloze Test", level: "L2 Application" },
    { q: "Select the best word for blank (2) from the passage: 'Many apartment residents now (2) small balconies into thriving vegetable patches.'", options: ["converting","convert","converts","converted"], answer: 1, explanation: "'Now (2) small balconies' needs a plain present-tense verb agreeing with the plural subject 'residents' — 'convert'.", rule: "Trace the verb to its subject (residents, plural) for the correct form.", trapcat: "Cloze Test", level: "L2 Application" },
    { q: "'To add fuel to the fire' means:", options: ["To calm down a tense situation","To start a fire deliberately","To make a bad situation even worse","To ignore a problem completely"], answer: 2, explanation: "'Add fuel to the fire' = to make an already difficult or tense situation worse.", rule: "Idiom: add fuel to the fire = worsen a situation.", trapcat: "Idioms", level: "L2 Application" },
    { q: "'To bury the hatchet' means:", options: ["To hide evidence of a crime","To start planning for the future","To make peace and end a conflict","To give up on a difficult task"], answer: 2, explanation: "'Bury the hatchet' = to make peace, to end a quarrel or conflict.", rule: "Idiom: bury the hatchet = reconcile/make peace.", trapcat: "Idioms", level: "L2 Application" },
    { q: "Select the part with an error: The manager, along with his entire team, were present at the conference venue early this morning.", options: ["at the conference venue","early this morning","were present","The manager, along with his entire team,"], answer: 2, explanation: "'Along with' does not pluralise the subject — 'the manager' remains singular, so it should be 'was present', not 'were present'.", rule: "'Along with' never makes the subject plural, regardless of what follows it.", trapcat: "Error Spotting", level: "L2 Application" },
    { q: "Select the part with an error: Neither the manager nor his assistants was available to answer the client's urgent query.", options: ["Neither the manager nor his assistants","was available","to answer the client's","urgent query"], answer: 1, explanation: "Neither/nor agrees with the NEARER subject. 'Assistants' (plural) is nearer, so it should be 'were available', not 'was available'.", rule: "Neither/nor → verb agrees with the nearer subject.", trapcat: "Error Spotting", level: "L2 Application" }
  ]
},
{
  id: "oct6_gs1", label: "Extreme GS Test 1 (Dances/Festivals/Sports/Culture)", timeLimitMin: 25,
  questions: [
    { q: "Which classical dance form originated in Tamil Nadu and is traditionally performed in Hindu temples?", options: ["Mohiniyattam", "Bharatanatyam", "Odissi", "Kathak"], answer: 1, explanation: "Bharatanatyam is Tamil Nadu's classical dance, rooted in the Natya Shastra and temple traditions (devadasi system). Kathak is from Uttar Pradesh (North Indian temple/court tradition); Odissi is from Odisha (Jagannath temple tradition); Mohiniyattam is from Kerala.", rule: "MNEMONIC: 'TN-Bharat, UP-Kathak, Odisha-Odissi, Kerala-Mohini/Kathakali' - map each state to exactly one classical dance first. || FULL BRUSH-UP — All 8 Classical Dances (memorize as one table): Bharatanatyam=Tamil Nadu | Kathak=Uttar Pradesh | Kathakali=Kerala | Kuchipudi=Andhra Pradesh | Odissi=Odisha | Manipuri=Manipur | Mohiniyattam=Kerala | Sattriya=Assam. MNEMONIC: 'Tamil BHARATanatyam, UP ka KATHAk, KERALa has 2 (Kathakali+Mohiniyattam), AP KUchipudi, Odisha ODISSi, Manipuri=Manipur(same name!), Assam SATtriya(Sattra).' ELIMINATION TRICK: if a question names a STATE correctly but pairs it with the WRONG dance of a NEIGHBOURING state (e.g. Kerala's two dances swapped, or AP/Telangana confusion post-2014), that's the most common SSC trap — always double check state, not just 'sounds classical'. Semi-classical/folk add-ons: Chhau=Jharkhand+Odisha+WestBengal(3 states), Bihu=Assam, Garba/Dandiya=Gujarat, Bhangra/Giddha=Punjab, Lavani=Maharashtra, Ghoomar=Rajasthan.", trapcat: "Classical Dance", level: "L1 Direct" },
    { q: "Kathakali, a classical dance-drama known for elaborate makeup and costumes, belongs to which state?", options: ["Tamil Nadu", "Andhra Pradesh", "Assam", "Kerala"], answer: 3, explanation: "Kathakali originated in Kerala, combining dance, drama, music and elaborate 'theppu' makeup to enact Hindu epics. Tamil Nadu's classical dance is Bharatanatyam; Andhra Pradesh's is Kuchipudi; Assam's is Sattriya.", rule: "SSC often swaps the STATE in the option list, not the dance name - always pair dance <-> state, not dance <-> generic description. || FULL BRUSH-UP — All 8 Classical Dances (memorize as one table): Bharatanatyam=Tamil Nadu | Kathak=Uttar Pradesh | Kathakali=Kerala | Kuchipudi=Andhra Pradesh | Odissi=Odisha | Manipuri=Manipur | Mohiniyattam=Kerala | Sattriya=Assam. MNEMONIC: 'Tamil BHARATanatyam, UP ka KATHAk, KERALa has 2 (Kathakali+Mohiniyattam), AP KUchipudi, Odisha ODISSi, Manipuri=Manipur(same name!), Assam SATtriya(Sattra).' ELIMINATION TRICK: if a question names a STATE correctly but pairs it with the WRONG dance of a NEIGHBOURING state (e.g. Kerala's two dances swapped, or AP/Telangana confusion post-2014), that's the most common SSC trap — always double check state, not just 'sounds classical'. Semi-classical/folk add-ons: Chhau=Jharkhand+Odisha+WestBengal(3 states), Bihu=Assam, Garba/Dandiya=Gujarat, Bhangra/Giddha=Punjab, Lavani=Maharashtra, Ghoomar=Rajasthan.", trapcat: "Classical Dance", level: "L1 Direct" },
    { q: "Sattriya, one of the eight classical dance forms of India, is associated with which state and which religious institution?", options: ["Kerala; associated with Kathakali troupes", "Assam; associated with Vaishnavite monasteries called Sattras", "Odisha; associated with the Jagannath temple", "Manipur; associated with Krishna temples"], answer: 1, explanation: "Sattriya originated in Assam's Vaishnavite monasteries (Sattras), founded by the saint Srimanta Sankardeva in the 15th century. Manipuri dance (from Manipur) is linked to Vaishnavism too but performed in Krishna-Radha Ras Lila style, not Sattras; Odissi is linked to Jagannath temple; Kathakali is a Kerala dance-drama, not from Sattras.", rule: "SSC loves to test the dance-institution pairing (Sattriya-Sattra) since it's less commonly known than the dance-state pairing. || FULL BRUSH-UP — All 8 Classical Dances (memorize as one table): Bharatanatyam=Tamil Nadu | Kathak=Uttar Pradesh | Kathakali=Kerala | Kuchipudi=Andhra Pradesh | Odissi=Odisha | Manipuri=Manipur | Mohiniyattam=Kerala | Sattriya=Assam. MNEMONIC: 'Tamil BHARATanatyam, UP ka KATHAk, KERALa has 2 (Kathakali+Mohiniyattam), AP KUchipudi, Odisha ODISSi, Manipuri=Manipur(same name!), Assam SATtriya(Sattra).' ELIMINATION TRICK: if a question names a STATE correctly but pairs it with the WRONG dance of a NEIGHBOURING state (e.g. Kerala's two dances swapped, or AP/Telangana confusion post-2014), that's the most common SSC trap — always double check state, not just 'sounds classical'. Semi-classical/folk add-ons: Chhau=Jharkhand+Odisha+WestBengal(3 states), Bihu=Assam, Garba/Dandiya=Gujarat, Bhangra/Giddha=Punjab, Lavani=Maharashtra, Ghoomar=Rajasthan.", trapcat: "Classical Dance", level: "L2 Application" },
    { q: "Which of the following is a classical dance of Manipur, characterised by gentle, flowing movements depicting Radha-Krishna themes?", options: ["Odissi", "Manipuri", "Bharatanatyam", "Kuchipudi"], answer: 1, explanation: "Manipuri is Manipur's classical dance, known for its soft, lyrical movements and Ras Lila (Radha-Krishna) themes. Kuchipudi is from Andhra Pradesh; Odissi from Odisha; Bharatanatyam from Tamil Nadu - all share devotional themes but differ in state and style (e.g., Bharatanatyam has sharper, more geometric movements, unlike Manipuri's fluidity).", rule: "Distinguishing feature trap: SSC may describe the STYLE (gentle/flowing vs sharp/geometric) to test if you know Manipuri's distinct softness vs Bharatanatyam's sharpness. || FULL BRUSH-UP — All 8 Classical Dances (memorize as one table): Bharatanatyam=Tamil Nadu | Kathak=Uttar Pradesh | Kathakali=Kerala | Kuchipudi=Andhra Pradesh | Odissi=Odisha | Manipuri=Manipur | Mohiniyattam=Kerala | Sattriya=Assam. MNEMONIC: 'Tamil BHARATanatyam, UP ka KATHAk, KERALa has 2 (Kathakali+Mohiniyattam), AP KUchipudi, Odisha ODISSi, Manipuri=Manipur(same name!), Assam SATtriya(Sattra).' ELIMINATION TRICK: if a question names a STATE correctly but pairs it with the WRONG dance of a NEIGHBOURING state (e.g. Kerala's two dances swapped, or AP/Telangana confusion post-2014), that's the most common SSC trap — always double check state, not just 'sounds classical'. Semi-classical/folk add-ons: Chhau=Jharkhand+Odisha+WestBengal(3 states), Bihu=Assam, Garba/Dandiya=Gujarat, Bhangra/Giddha=Punjab, Lavani=Maharashtra, Ghoomar=Rajasthan.", trapcat: "Classical Dance", level: "L2 Application" },
    { q: "Chhau dance, a semi-classical dance form involving martial arts and acrobatic movements, is practiced across which three states/region?", options: ["Jharkhand (Seraikella), Odisha (Mayurbhanj), and West Bengal (Purulia)", "Punjab, Haryana, and Himachal Pradesh", "Kerala, Tamil Nadu, and Karnataka", "Gujarat, Rajasthan, and Madhya Pradesh"], answer: 0, explanation: "Chhau has three regional styles named after their location: Seraikella Chhau (Jharkhand), Mayurbhanj Chhau (Odisha), and Purulia Chhau (West Bengal). The other state groupings are unrelated to Chhau; Chhau is UNESCO-recognised as an Intangible Cultural Heritage and is unique for having three distinct regional sub-styles under one name.", rule: "SSC often asks 'Chhau belongs to how many states' (three) and 'name them' - memorize via the sub-style names which directly name the location (Seraikella, Mayurbhanj, Purulia). || FULL BRUSH-UP — All 8 Classical Dances (memorize as one table): Bharatanatyam=Tamil Nadu | Kathak=Uttar Pradesh | Kathakali=Kerala | Kuchipudi=Andhra Pradesh | Odissi=Odisha | Manipuri=Manipur | Mohiniyattam=Kerala | Sattriya=Assam. MNEMONIC: 'Tamil BHARATanatyam, UP ka KATHAk, KERALa has 2 (Kathakali+Mohiniyattam), AP KUchipudi, Odisha ODISSi, Manipuri=Manipur(same name!), Assam SATtriya(Sattra).' ELIMINATION TRICK: if a question names a STATE correctly but pairs it with the WRONG dance of a NEIGHBOURING state (e.g. Kerala's two dances swapped, or AP/Telangana confusion post-2014), that's the most common SSC trap — always double check state, not just 'sounds classical'. Semi-classical/folk add-ons: Chhau=Jharkhand+Odisha+WestBengal(3 states), Bihu=Assam, Garba/Dandiya=Gujarat, Bhangra/Giddha=Punjab, Lavani=Maharashtra, Ghoomar=Rajasthan.", trapcat: "Folk/Semi-classical Dance", level: "L2 Application" },
    { q: "Bihu, a folk dance performed during the Assamese New Year harvest festival, is celebrated in which month(s)?", options: ["December (Christmas season)", "October (during Durga Puja)", "Mid-January (Magh Bihu only)", "Mid-April (Bohag/Rongali Bihu, marking the Assamese New Year)"], answer: 3, explanation: "Rongali/Bohag Bihu in mid-April marks the Assamese New Year and spring harvest; it is the most celebrated of the three Bihus. Magh Bihu (mid-January) marks the end of the harvesting season, a DIFFERENT Bihu, not the New Year one; Bihu has no link to Durga Puja (October) or Christmas (December) timing.", rule: "TRAP: Assam has THREE Bihus - Bohag/Rongali (April, New Year), Magh/Bhogali (January, harvest-end), Kati/Kongali (October, sparse harvest). SSC tests which one is the New Year festival. || FULL BRUSH-UP — Festival-State-Month table: Bihu(Assam,April/Jan/Oct-3 types)=Rongali/Bohag(April,New Year), Magh/Bhogali(Jan), Kati(Oct) | Onam(Kerala,Aug-Sep,harvest,King Mahabali) | Pongal(Tamil Nadu,mid-Jan,harvest) | Lohri(Punjab,mid-Jan) | Baisakhi(Punjab,April,harvest+Khalsa founding) | Hornbill(Nagaland,1-10 Dec,Kisama village) | Hemis(Ladakh,summer,masked Cham dance,Guru Padmasambhava) | Rath Yatra(Puri Odisha,Jagannath chariot festival) | Durga Puja(West Bengal,Sep-Oct) | Surajkund Mela(Haryana-Faridabad,Feb,crafts) | Khajuraho Dance Festival(MP,Feb) | Pushkar Camel Fair(Rajasthan,Nov). MNEMONIC for harvest festivals in Jan: 'PML-B' = Pongal, Makar Sankranti, Lohri, Bihu(Magh) — all occur in mid-January across different states, a very common SSC confusion set. ELIMINATION TRICK: if an option names the WRONG state for a correctly-named festival's exact ritual description, that's the trap; if it names the right state but wrong MONTH, that's the second most common trap.", trapcat: "Festivals", level: "L3 Trap" },
    { q: "Which festival is known as the 'Festival of Chariots' and involves a massive procession of three deities including Lord Jagannath?", options: ["Hornbill Festival (Nagaland)", "Pongal (Tamil Nadu)", "Rath Yatra (Puri, Odisha)", "Onam (Kerala)"], answer: 2, explanation: "Rath Yatra at Puri, Odisha, involves huge wooden chariots carrying Jagannath, Balabhadra, and Subhadra through the streets. Pongal is Tamil Nadu's harvest festival; Onam is Kerala's harvest festival linked to King Mahabali; Hornbill Festival is Nagaland's cultural festival of tribes - none involve chariot processions.", rule: "'Festival of Chariots' = Rath Yatra, always tied to Puri/Jagannath - a very frequently repeated SSC fact. || FULL BRUSH-UP — Festival-State-Month table: Bihu(Assam,April/Jan/Oct-3 types)=Rongali/Bohag(April,New Year), Magh/Bhogali(Jan), Kati(Oct) | Onam(Kerala,Aug-Sep,harvest,King Mahabali) | Pongal(Tamil Nadu,mid-Jan,harvest) | Lohri(Punjab,mid-Jan) | Baisakhi(Punjab,April,harvest+Khalsa founding) | Hornbill(Nagaland,1-10 Dec,Kisama village) | Hemis(Ladakh,summer,masked Cham dance,Guru Padmasambhava) | Rath Yatra(Puri Odisha,Jagannath chariot festival) | Durga Puja(West Bengal,Sep-Oct) | Surajkund Mela(Haryana-Faridabad,Feb,crafts) | Khajuraho Dance Festival(MP,Feb) | Pushkar Camel Fair(Rajasthan,Nov). MNEMONIC for harvest festivals in Jan: 'PML-B' = Pongal, Makar Sankranti, Lohri, Bihu(Magh) — all occur in mid-January across different states, a very common SSC confusion set. ELIMINATION TRICK: if an option names the WRONG state for a correctly-named festival's exact ritual description, that's the trap; if it names the right state but wrong MONTH, that's the second most common trap.", trapcat: "Festivals", level: "L1 Direct" },
    { q: "Hemis Festival, celebrated in honour of Guru Padmasambhava with masked 'Cham' dances, is observed in which region?", options: ["Ladakh (at Hemis Monastery)", "Arunachal Pradesh", "Himachal Pradesh", "Sikkim"], answer: 0, explanation: "Hemis Festival is held at Hemis Monastery in Ladakh, featuring masked Cham dances performed by monks honouring Guru Padmasambhava's birth anniversary. Sikkim has its own Buddhist festivals (e.g., Losar) but Hemis specifically belongs to Ladakh's Hemis Monastery; Arunachal Pradesh and Himachal Pradesh have other Buddhist monastic festivals but Hemis itself is Ladakh's signature festival.", rule: "SSC frequently tests region-specific masked/monastery festivals - Hemis is THE flagship answer for Ladakh. || FULL BRUSH-UP — Festival-State-Month table: Bihu(Assam,April/Jan/Oct-3 types)=Rongali/Bohag(April,New Year), Magh/Bhogali(Jan), Kati(Oct) | Onam(Kerala,Aug-Sep,harvest,King Mahabali) | Pongal(Tamil Nadu,mid-Jan,harvest) | Lohri(Punjab,mid-Jan) | Baisakhi(Punjab,April,harvest+Khalsa founding) | Hornbill(Nagaland,1-10 Dec,Kisama village) | Hemis(Ladakh,summer,masked Cham dance,Guru Padmasambhava) | Rath Yatra(Puri Odisha,Jagannath chariot festival) | Durga Puja(West Bengal,Sep-Oct) | Surajkund Mela(Haryana-Faridabad,Feb,crafts) | Khajuraho Dance Festival(MP,Feb) | Pushkar Camel Fair(Rajasthan,Nov). MNEMONIC for harvest festivals in Jan: 'PML-B' = Pongal, Makar Sankranti, Lohri, Bihu(Magh) — all occur in mid-January across different states, a very common SSC confusion set. ELIMINATION TRICK: if an option names the WRONG state for a correctly-named festival's exact ritual description, that's the trap; if it names the right state but wrong MONTH, that's the second most common trap.", trapcat: "Festivals", level: "L2 Application" },
    { q: "The Khelo India Youth Games were first held in which year and city?", options: ["2018, New Delhi", "2016, Pune", "2020, Guwahati", "2017, Bhopal"], answer: 0, explanation: "The inaugural Khelo India School Games (later Youth Games) were held in New Delhi in January 2018. Pune hosted a later edition (2019); Guwahati hosted the 2020 edition; Bhopal was not a host of the first edition.", rule: "SSC tests 'first edition' host cities for sports events - always distinguish the INAUGURAL edition from LATER editions mentioned as distractors. || FULL BRUSH-UP — Sport terminology + trophies: Kabaddi=Raid/Dub/Lona/Bonus-line | Kho-Kho=Pole/Lobby/Chain/Foul(3 types) | Hockey=Bully(old)/Penalty-corner/Penalty-stroke | Cricket domestic trophies: Ranji(first-class,state-level,oldest-1934),Duleep(zonal),Irani(Ranji champion vs Rest of India),Vijay Hazare(ODI format),Syed Mushtaq Ali(T20 format). Major awards by field: Khel Ratna/Arjuna=sports | Dronacharya=coaching | Dhyan Chand=lifetime sports contribution | Jnanpith=literature | Sangeet Natak Akademi=music/dance/drama | Dadasaheb Phalke=cinema lifetime | Padma awards=any field, by govt of India. 'Oldest' facts: Durand Cup(1888)=oldest football tournament in Asia; Ranji Trophy(1934)=oldest domestic cricket; Modern Olympics started 1896 Athens; first Asian Games 1951 New Delhi. ELIMINATION TRICK: when 2 options are both plausible trophies/awards, check whether the question asks for FORMAT(T20/ODI/first-class) vs LEVEL(state/zonal/national) — most SSC traps swap these two axes.", trapcat: "Sports", level: "L2 Application" },
    { q: "The 'Dhyan Chand Award' (now renamed) was India's highest award for lifetime achievement in which field?", options: ["Social Service", "Classical Music", "Literature", "Sports (for lifetime contribution to sports)"], answer: 3, explanation: "The Dhyan Chand Award (now Major Dhyan Chand Khel Ratna's lifetime category, distinct from the renamed Khel Ratna itself) recognised lifetime achievement in sports coaching/contribution. Literature's highest honours are the Jnanpith/Sahitya Akademi awards; Classical music has the Sangeet Natak Akademi awards; Social service has the Padma awards broadly - none are the Dhyan Chand award.", rule: "Major Dhyan Chand (hockey legend) - name used for both the Khel Ratna (renamed 2021) AND a separate lifetime achievement award; SSC may test either, read the question's wording carefully. || FULL BRUSH-UP — Sport terminology + trophies: Kabaddi=Raid/Dub/Lona/Bonus-line | Kho-Kho=Pole/Lobby/Chain/Foul(3 types) | Hockey=Bully(old)/Penalty-corner/Penalty-stroke | Cricket domestic trophies: Ranji(first-class,state-level,oldest-1934),Duleep(zonal),Irani(Ranji champion vs Rest of India),Vijay Hazare(ODI format),Syed Mushtaq Ali(T20 format). Major awards by field: Khel Ratna/Arjuna=sports | Dronacharya=coaching | Dhyan Chand=lifetime sports contribution | Jnanpith=literature | Sangeet Natak Akademi=music/dance/drama | Dadasaheb Phalke=cinema lifetime | Padma awards=any field, by govt of India. 'Oldest' facts: Durand Cup(1888)=oldest football tournament in Asia; Ranji Trophy(1934)=oldest domestic cricket; Modern Olympics started 1896 Athens; first Asian Games 1951 New Delhi. ELIMINATION TRICK: when 2 options are both plausible trophies/awards, check whether the question asks for FORMAT(T20/ODI/first-class) vs LEVEL(state/zonal/national) — most SSC traps swap these two axes.", trapcat: "Sports", level: "L2 Application" },
    { q: "Which trophy is awarded to the winner of the Ranji Trophy, India's premier domestic cricket tournament?", options: ["The Ranji Trophy itself (named after Ranjitsinhji)", "The Duleep Trophy", "The Irani Cup", "The Vijay Hazare Trophy"], answer: 0, explanation: "The Ranji Trophy, India's premier first-class domestic cricket championship, is named after Ranjitsinhji and awarded to the winning state/zonal team. Duleep Trophy is a separate zonal tournament; Irani Cup is played between the Ranji champion and Rest of India; Vijay Hazare Trophy is the domestic ONE-DAY tournament, not first-class.", rule: "TRAP: SSC tests confusion between India's FOUR major domestic cricket tournaments - Ranji (first-class, state-level), Duleep (zonal), Irani (Ranji winner vs Rest of India), Vijay Hazare (ODI format). || FULL BRUSH-UP — Sport terminology + trophies: Kabaddi=Raid/Dub/Lona/Bonus-line | Kho-Kho=Pole/Lobby/Chain/Foul(3 types) | Hockey=Bully(old)/Penalty-corner/Penalty-stroke | Cricket domestic trophies: Ranji(first-class,state-level,oldest-1934),Duleep(zonal),Irani(Ranji champion vs Rest of India),Vijay Hazare(ODI format),Syed Mushtaq Ali(T20 format). Major awards by field: Khel Ratna/Arjuna=sports | Dronacharya=coaching | Dhyan Chand=lifetime sports contribution | Jnanpith=literature | Sangeet Natak Akademi=music/dance/drama | Dadasaheb Phalke=cinema lifetime | Padma awards=any field, by govt of India. 'Oldest' facts: Durand Cup(1888)=oldest football tournament in Asia; Ranji Trophy(1934)=oldest domestic cricket; Modern Olympics started 1896 Athens; first Asian Games 1951 New Delhi. ELIMINATION TRICK: when 2 options are both plausible trophies/awards, check whether the question asks for FORMAT(T20/ODI/first-class) vs LEVEL(state/zonal/national) — most SSC traps swap these two axes.", trapcat: "Sports", level: "L3 Trap" },
    { q: "Which Indian classical musical instrument is most associated with the Maihar Gharana and was popularised globally by Pandit Ravi Shankar?", options: ["Sitar", "Tabla", "Sarod", "Santoor"], answer: 0, explanation: "Pandit Ravi Shankar, a disciple of Ustad Allauddin Khan (founder of the Maihar Gharana), popularised the Sitar worldwide. Sarod is associated with Ustad Ali Akbar Khan (also of Maihar Gharana, Ravi Shankar's brother-in-law and guru's son) - a close distractor; Tabla's global icon is Zakir Hussain; Santoor's is Pandit Shivkumar Sharma.", rule: "TRAP: Ravi Shankar (Sitar) and Ali Akbar Khan (Sarod) are BOTH Maihar Gharana and often confused - match the exact artist to the exact instrument, not just the gharana. || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture", level: "L3 Trap" },
    { q: "The 'Madhubani' painting style, characterised by geometric patterns and natural dyes, originates from which state?", options: ["Odisha", "Bihar (Mithila region)", "Rajasthan", "West Bengal"], answer: 1, explanation: "Madhubani (also called Mithila painting) originates from the Mithila region of Bihar, traditionally done by women using natural dyes and pigments. Rajasthan is known for Phad and Pichwai paintings; West Bengal for Kalighat painting; Odisha for Pattachitra.", rule: "MNEMONIC: Madhubani-Bihar(Mithila), Pattachitra-Odisha, Kalighat-Bengal, Phad-Rajasthan - memorize as fixed state-art pairs. || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture", level: "L1 Direct" },
    { q: "Warli painting, a tribal art form using geometric shapes (circles, triangles, squares) on a mud base, belongs to which state?", options: ["Gujarat", "Chhattisgarh", "Madhya Pradesh", "Maharashtra"], answer: 3, explanation: "Warli painting is practised by the Warli tribe of Maharashtra (mainly in the Thane/Nashik/Palghar regions). Gujarat has Pithora painting; Madhya Pradesh/Chhattisgarh have Gond art as their notable tribal art forms - Warli is distinctly Maharashtra's.", rule: "SSC-level trap: distinguishing TRIBAL art forms by state (Warli-Maharashtra, Gond-MP/Chhattisgarh, Pithora-Gujarat) since all use similarly 'primitive' geometric styles. || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture", level: "L2 Application" },
    { q: "Consider the following statements about the Konark Sun Temple: 1. It is located in Odisha and built in the 13th century. 2. It is designed in the shape of a gigantic chariot with 24 wheels. 3. It was built by Narasimhadeva I of the Eastern Ganga dynasty. Which of the above is/are correct?", options: ["1 only", "2 and 3 only", "1, 2 and 3", "1 and 2 only"], answer: 2, explanation: "All three statements are correct: Konark Sun Temple (13th century, Odisha) is shaped as a chariot with 24 wheels, built under Narasimhadeva I of the Eastern Ganga dynasty. This is a rare 'all true' case - SSC does include some all-correct statement sets to prevent over-reliance on 'there's always one false statement' heuristic.", rule: "WARNING: do not assume one statement is always false - some SSC statement sets are entirely correct. Verify each one independently. || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture/History", level: "L2 Application" },
    { q: "The 'Pattachitra' art form, involving cloth-based scroll paintings depicting Hindu mythology, is traditionally associated with which temple town?", options: ["Puri, Odisha (linked to Jagannath temple traditions)", "Dwarka, Gujarat", "Madurai, Tamil Nadu", "Varanasi, Uttar Pradesh"], answer: 0, explanation: "Pattachitra originated in and around Puri, Odisha, closely tied to Jagannath temple traditions and mythology. Madurai is famous for the Meenakshi temple, not Pattachitra; Varanasi is famous as a spiritual/Ganga Aarti center; Dwarka for the Krishna temple - none are Pattachitra's home.", rule: "Pattachitra and Odissi dance and Konark/Jagannath temples are ALL Odisha-linked - SSC often clusters Odisha culture questions together. || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture", level: "L2 Application" },
    { q: "Which of these Indian classical dance forms uses 'Mudras' (hand gestures) codified in the ancient text 'Natya Shastra', attributed to sage Bharata Muni?", options: ["All classical dances of India draw from the Natya Shastra (it is the common foundational text)", "Only Kathak uses it, since it originated in temples first", "Only Bharatanatyam uses the Natya Shastra; others have separate independent texts", "Natya Shastra applies only to music, not dance"], answer: 0, explanation: "The Natya Shastra, attributed to Bharata Muni (dated roughly 200 BCE-200 CE), is the foundational treatise for ALL Indian classical dance forms, codifying mudras, rasa, and performance theory - not exclusive to any one style. Bharatanatyam is often most closely associated with it due to direct mudra correspondence, but this is a common trap - the text underlies ALL eight classical dances, not one exclusively; it covers both dance (nritya) and dramaturgy, not just music.", rule: "TRAP: SSC sometimes tests whether you think Natya Shastra belongs to only ONE dance form - it is the shared root text for the entire classical tradition. || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture", level: "L3 Trap" },
    { q: "The Hornbill Festival, showcasing the culture of Naga tribes, is held annually in which month at Kisama, Nagaland?", options: ["August", "October", "December (1st-10th December)", "March"], answer: 2, explanation: "The Hornbill Festival is held every year from 1-10 December at Kisama Heritage Village, Nagaland, showcasing all major Naga tribes. March, August, and October do not correspond to the Hornbill Festival's fixed December dates; SSC may insert other states' festival months here as distractors.", rule: "Hornbill Festival = December, Nagaland, Kisama village - a fixed, frequently tested fact-triplet. || FULL BRUSH-UP — Festival-State-Month table: Bihu(Assam,April/Jan/Oct-3 types)=Rongali/Bohag(April,New Year), Magh/Bhogali(Jan), Kati(Oct) | Onam(Kerala,Aug-Sep,harvest,King Mahabali) | Pongal(Tamil Nadu,mid-Jan,harvest) | Lohri(Punjab,mid-Jan) | Baisakhi(Punjab,April,harvest+Khalsa founding) | Hornbill(Nagaland,1-10 Dec,Kisama village) | Hemis(Ladakh,summer,masked Cham dance,Guru Padmasambhava) | Rath Yatra(Puri Odisha,Jagannath chariot festival) | Durga Puja(West Bengal,Sep-Oct) | Surajkund Mela(Haryana-Faridabad,Feb,crafts) | Khajuraho Dance Festival(MP,Feb) | Pushkar Camel Fair(Rajasthan,Nov). MNEMONIC for harvest festivals in Jan: 'PML-B' = Pongal, Makar Sankranti, Lohri, Bihu(Magh) — all occur in mid-January across different states, a very common SSC confusion set. ELIMINATION TRICK: if an option names the WRONG state for a correctly-named festival's exact ritual description, that's the trap; if it names the right state but wrong MONTH, that's the second most common trap.", trapcat: "Festivals", level: "L1 Direct" },
    { q: "Pochampally Ikat, a famous tie-dye weaving technique given a Geographical Indication (GI) tag, is associated with which state?", options: ["Andhra Pradesh", "Gujarat", "Odisha", "Telangana"], answer: 3, explanation: "Pochampally Ikat is from Telangana (Bhoodan Pochampally village), recognised with a GI tag for its distinctive tie-dye weaving. Andhra Pradesh and Telangana were a single state until 2014; after bifurcation, Pochampally falls within Telangana specifically - a key post-2014 geography update SSC likes to test; Odisha has its own separate Ikat tradition (Sambalpuri Ikat); Gujarat has Patola, a related but distinct double-ikat.", rule: "POST-BIFURCATION TRAP: many GI/culture facts that used to say 'Andhra Pradesh' pre-2014 now belong to Telangana - always check the current state post-2014. || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture", level: "L3 Trap" },
    { q: "The 'Durand Cup', one of the oldest football tournaments in Asia, was established in which year and originally organised by whom?", options: ["1911, by the Indian Football Association", "1888, by Sir Mortimer Durand (then British Foreign Secretary in India)", "1930, by the Maharaja of Mysore", "1950, by the All India Football Federation"], answer: 1, explanation: "The Durand Cup was established in 1888 by Sir Mortimer Durand, making it Asia's oldest and the world's third-oldest football tournament. AIFF (founded 1937) came much later; the Indian Football Association organises other tournaments like the IFA Shield (1893); the Maharaja of Mysore has no link to the Durand Cup's founding.", rule: "'Oldest football tournament in Asia' = Durand Cup (1888) - a very commonly repeated standalone SSC fact. || FULL BRUSH-UP — Sport terminology + trophies: Kabaddi=Raid/Dub/Lona/Bonus-line | Kho-Kho=Pole/Lobby/Chain/Foul(3 types) | Hockey=Bully(old)/Penalty-corner/Penalty-stroke | Cricket domestic trophies: Ranji(first-class,state-level,oldest-1934),Duleep(zonal),Irani(Ranji champion vs Rest of India),Vijay Hazare(ODI format),Syed Mushtaq Ali(T20 format). Major awards by field: Khel Ratna/Arjuna=sports | Dronacharya=coaching | Dhyan Chand=lifetime sports contribution | Jnanpith=literature | Sangeet Natak Akademi=music/dance/drama | Dadasaheb Phalke=cinema lifetime | Padma awards=any field, by govt of India. 'Oldest' facts: Durand Cup(1888)=oldest football tournament in Asia; Ranji Trophy(1934)=oldest domestic cricket; Modern Olympics started 1896 Athens; first Asian Games 1951 New Delhi. ELIMINATION TRICK: when 2 options are both plausible trophies/awards, check whether the question asks for FORMAT(T20/ODI/first-class) vs LEVEL(state/zonal/national) — most SSC traps swap these two axes.", trapcat: "Sports", level: "L2 Application" },
    { q: "Which Indian sport uses terms like 'Raid', 'Dub', and 'Lona', and is governed internationally by a federation headquartered in India?", options: ["Kabaddi", "Mallakhamb", "Sepak Takraw", "Kho-Kho"], answer: 0, explanation: "Kabaddi terminology includes 'Raid' (attacking move), 'Dub' (defensive touch-escape), and 'Lona' (all-out, bonus points) - its international federation (AKFI/International Kabaddi Federation) is India-based. Kho-Kho uses terms like 'pole', 'lobby', and 'chain'; Mallakhamb is a gymnastics-pole sport with different terminology; Sepak Takraw is a Southeast Asian kick-volleyball sport, not Indian in origin.", rule: "Sport-specific terminology (Raid/Dub/Lona = Kabaddi) is an easy, high-frequency SSC identification question. || FULL BRUSH-UP — Sport terminology + trophies: Kabaddi=Raid/Dub/Lona/Bonus-line | Kho-Kho=Pole/Lobby/Chain/Foul(3 types) | Hockey=Bully(old)/Penalty-corner/Penalty-stroke | Cricket domestic trophies: Ranji(first-class,state-level,oldest-1934),Duleep(zonal),Irani(Ranji champion vs Rest of India),Vijay Hazare(ODI format),Syed Mushtaq Ali(T20 format). Major awards by field: Khel Ratna/Arjuna=sports | Dronacharya=coaching | Dhyan Chand=lifetime sports contribution | Jnanpith=literature | Sangeet Natak Akademi=music/dance/drama | Dadasaheb Phalke=cinema lifetime | Padma awards=any field, by govt of India. 'Oldest' facts: Durand Cup(1888)=oldest football tournament in Asia; Ranji Trophy(1934)=oldest domestic cricket; Modern Olympics started 1896 Athens; first Asian Games 1951 New Delhi. ELIMINATION TRICK: when 2 options are both plausible trophies/awards, check whether the question asks for FORMAT(T20/ODI/first-class) vs LEVEL(state/zonal/national) — most SSC traps swap these two axes.", trapcat: "Sports", level: "L1 Direct" },
    { q: "The Jallikattu sport, involving bull-taming and traditionally held during the Pongal festival, is practised in which state?", options: ["Andhra Pradesh", "Karnataka", "Tamil Nadu", "Kerala"], answer: 2, explanation: "Jallikattu is practised in Tamil Nadu during the Pongal harvest festival, involving participants attempting to tame bulls released into crowds. Kerala has its own bull-related and animal-centric festivals but not Jallikattu specifically; Karnataka has a similar but distinctly named sport called 'Kambala' (buffalo racing, not bull-taming); Andhra Pradesh has no equivalent traditional sport of this name.", rule: "TRAP: do not confuse Jallikattu (Tamil Nadu, bull-taming) with Kambala (Karnataka, buffalo RACING) - both are agrarian bull/buffalo sports but different states and different formats. || FULL BRUSH-UP — Sport terminology + trophies: Kabaddi=Raid/Dub/Lona/Bonus-line | Kho-Kho=Pole/Lobby/Chain/Foul(3 types) | Hockey=Bully(old)/Penalty-corner/Penalty-stroke | Cricket domestic trophies: Ranji(first-class,state-level,oldest-1934),Duleep(zonal),Irani(Ranji champion vs Rest of India),Vijay Hazare(ODI format),Syed Mushtaq Ali(T20 format). Major awards by field: Khel Ratna/Arjuna=sports | Dronacharya=coaching | Dhyan Chand=lifetime sports contribution | Jnanpith=literature | Sangeet Natak Akademi=music/dance/drama | Dadasaheb Phalke=cinema lifetime | Padma awards=any field, by govt of India. 'Oldest' facts: Durand Cup(1888)=oldest football tournament in Asia; Ranji Trophy(1934)=oldest domestic cricket; Modern Olympics started 1896 Athens; first Asian Games 1951 New Delhi. ELIMINATION TRICK: when 2 options are both plausible trophies/awards, check whether the question asks for FORMAT(T20/ODI/first-class) vs LEVEL(state/zonal/national) — most SSC traps swap these two axes.", trapcat: "Sports/Festivals", level: "L3 Trap" },
    { q: "Consider the following statements: 1. Odissi dance draws its themes largely from Vaishnavism, especially the life of Krishna. 2. The 'Tribhangi' (three-bend) posture is a signature stance in Odissi. 3. Odissi is believed to be one of the oldest surviving dance forms, with evidence in 2nd century BCE cave carvings at Udayagiri-Khandagiri. Which of the above is/are correct?", options: ["1 and 2 only", "1 only", "1, 2 and 3", "2 and 3 only"], answer: 2, explanation: "All three are correct: Odissi's themes centre on Krishna/Vaishnavism, its hallmark posture is the Tribhangi (three-bend), and its antiquity is evidenced by 2nd century BCE carvings at the Udayagiri-Khandagiri caves in Odisha. Another all-true case - reinforces that SSC statement sets are not always 'spot the one false fact'.", rule: "Tribhangi = Odissi's signature stance; carve this fact alongside the Udayagiri-Khandagiri antiquity evidence as a single memorized block. || FULL BRUSH-UP — All 8 Classical Dances (memorize as one table): Bharatanatyam=Tamil Nadu | Kathak=Uttar Pradesh | Kathakali=Kerala | Kuchipudi=Andhra Pradesh | Odissi=Odisha | Manipuri=Manipur | Mohiniyattam=Kerala | Sattriya=Assam. MNEMONIC: 'Tamil BHARATanatyam, UP ka KATHAk, KERALa has 2 (Kathakali+Mohiniyattam), AP KUchipudi, Odisha ODISSi, Manipuri=Manipur(same name!), Assam SATtriya(Sattra).' ELIMINATION TRICK: if a question names a STATE correctly but pairs it with the WRONG dance of a NEIGHBOURING state (e.g. Kerala's two dances swapped, or AP/Telangana confusion post-2014), that's the most common SSC trap — always double check state, not just 'sounds classical'. Semi-classical/folk add-ons: Chhau=Jharkhand+Odisha+WestBengal(3 states), Bihu=Assam, Garba/Dandiya=Gujarat, Bhangra/Giddha=Punjab, Lavani=Maharashtra, Ghoomar=Rajasthan.", trapcat: "Classical Dance", level: "L2 Application" },
    { q: "The 'Surajkund International Crafts Mela', a major annual fair showcasing crafts, handlooms and cultural performances, is held in which state?", options: ["Rajasthan", "Haryana (Faridabad district)", "Delhi", "Uttar Pradesh"], answer: 1, explanation: "The Surajkund Crafts Mela is held annually (February) at Surajkund, Faridabad, Haryana, featuring artisans and performers from across India and a chosen 'partner country/state'. Rajasthan hosts its own fairs like the Pushkar Camel Fair; Delhi is geographically close to Surajkund but the venue itself falls within Haryana's jurisdiction; Uttar Pradesh hosts separate events like the Taj Mahotsav.", rule: "Surajkund is physically near Delhi's border but administratively in Haryana (Faridabad) - a common location-based SSC trap. || FULL BRUSH-UP — Festival-State-Month table: Bihu(Assam,April/Jan/Oct-3 types)=Rongali/Bohag(April,New Year), Magh/Bhogali(Jan), Kati(Oct) | Onam(Kerala,Aug-Sep,harvest,King Mahabali) | Pongal(Tamil Nadu,mid-Jan,harvest) | Lohri(Punjab,mid-Jan) | Baisakhi(Punjab,April,harvest+Khalsa founding) | Hornbill(Nagaland,1-10 Dec,Kisama village) | Hemis(Ladakh,summer,masked Cham dance,Guru Padmasambhava) | Rath Yatra(Puri Odisha,Jagannath chariot festival) | Durga Puja(West Bengal,Sep-Oct) | Surajkund Mela(Haryana-Faridabad,Feb,crafts) | Khajuraho Dance Festival(MP,Feb) | Pushkar Camel Fair(Rajasthan,Nov). MNEMONIC for harvest festivals in Jan: 'PML-B' = Pongal, Makar Sankranti, Lohri, Bihu(Magh) — all occur in mid-January across different states, a very common SSC confusion set. ELIMINATION TRICK: if an option names the WRONG state for a correctly-named festival's exact ritual description, that's the trap; if it names the right state but wrong MONTH, that's the second most common trap.", trapcat: "Festivals", level: "L3 Trap" },
    { q: "Which award is given by the Sangeet Natak Akademi for outstanding contributions to music, dance, and drama, considered India's highest honour in the performing arts?", options: ["Jnanpith Award", "Dadasaheb Phalke Award", "Sangeet Natak Akademi Fellowship/Award (Akademi Ratna / Akademi Puraskar)", "Kalidas Samman"], answer: 2, explanation: "The Sangeet Natak Akademi gives Fellowships (Akademi Ratna) and Awards (Akademi Puraskar) - India's highest recognitions specifically for music, dance, and drama. Jnanpith is for literature; Dadasaheb Phalke Award is for lifetime contribution to CINEMA; Kalidas Samman is a Madhya Pradesh state government award for arts, not a central/highest national one.", rule: "Match each award to its EXACT field: Jnanpith-literature, Phalke-cinema, Sangeet Natak Akademi-performing arts (music/dance/drama). || FULL BRUSH-UP — Painting styles by state: Madhubani/Mithila=Bihar | Warli=Maharashtra(tribal,geometric) | Pattachitra=Odisha(cloth scroll,Jagannath themes) | Kalighat=West Bengal | Phad & Pichwai=Rajasthan | Gond=Madhya Pradesh/Chhattisgarh(tribal) | Tanjore=Tamil Nadu(gold-leaf relief) | Pithora=Gujarat(tribal) | Kangra & Basholi=Himachal Pradesh(miniature). Instrument-Artist pairs (frequently confused): Sitar=Pandit Ravi Shankar | Sarod=Ustad Ali Akbar Khan (both from Maihar Gharana — a classic trap) | Tabla=Ustad Zakir Hussain | Santoor=Pandit Shivkumar Sharma | Shehnai=Ustad Bismillah Khan | Violin(Carnatic)=Lalgudi Jayaraman/M.S.Gopalakrishnan | Flute=Pandit Hariprasad Chaurasia. Natya Shastra=foundational text for ALL classical dance+drama (by Bharata Muni), not exclusive to one style. GI-tag crafts: Pochampally Ikat=Telangana(post-2014,was AP before) | Sambalpuri Ikat=Odisha | Banarasi Silk=Uttar Pradesh | Kanjeevaram Silk=Tamil Nadu | Chanderi=Madhya Pradesh. ELIMINATION TRICK: any GI/craft fact that says 'Andhra Pradesh' for something now in Telangana (post-2014 split) is often an outdated-option trap.", trapcat: "Art & Culture", level: "L2 Application" }
  ]
},
{
  id: "oct6_m1", label: "Extreme Maths Test 1 (Full Syllabus Brush-up)", timeLimitMin: 30,
  questions: [
    { q: "Rs. 12,000 is invested at 9% p.a. compound interest (compounded annually) for 3 years. For the 4th year only, the rate increases to 11%. Find the amount at the end of the 4th year (nearest rupee). [Given: (1.09)^3 = 1.295029]", options: ["Rs. 17250", "Rs. 16350", "Rs. 17870", "Rs. 16900"], answer: 0, explanation: "Amount after 3 yrs = 12000 x 1.09^3 = 12000 x 1.295029 = Rs. 15540.35. For year 4, apply ONLY the new 11% rate to this amount: 15540.35 x 1.11 = Rs. 17250. The wrong options come from either applying 11% to all 4 years from the start, or applying 9% in year 4 instead of switching rates — both are common chaining errors.", rule: "When a rate changes for a LATER year only, apply the new rate to the accumulated amount up to that point, not from the principal. || FULL BRUSH-UP — SI/CI: SI = (P*R*T)/100. CI = P*[(1+R/100)^T - 1]. CI - SI for 2 years = P*(R/100)^2 (shortcut, skip full calculation). CI - SI for 3 years = P*(R/100)^2*[(300+R)/100]. Half-yearly compounding: use R/2 as rate, 2T as time periods. Quarterly: R/4 as rate, 4T as periods. ELIMINATION TRICK: if a problem changes the rate for ONE specific later year/period, apply the new rate only to the ACCUMULATED amount up to that point — never recompute from the original principal with a blended rate.", trapcat: "Compound Interest (multi-step)", level: "L3 Trap" },
    { q: "Find the difference between Compound Interest and Simple Interest on Rs. 8,000 at 10% p.a. for 2 years.", options: ["Rs. 80", "Rs. 160", "Rs. 50", "Rs. 120"], answer: 0, explanation: "SI = PRT/100 = 8000x10x2/100 = Rs.1600. CI = P[(1+r)^2-1] = 8000x[1.21-1] = Rs.1680. Difference = Rs.80. A frequent shortcut: for 2 years, CI-SI = P x (r/100)^2 = 8000 x 0.01 = Rs.80, confirming the same answer instantly without computing CI and SI separately.", rule: "SHORTCUT: For exactly 2 years, (CI - SI) = P x (R/100)^2 — memorize this to skip full CI/SI computation. || FULL BRUSH-UP — SI/CI: SI = (P*R*T)/100. CI = P*[(1+R/100)^T - 1]. CI - SI for 2 years = P*(R/100)^2 (shortcut, skip full calculation). CI - SI for 3 years = P*(R/100)^2*[(300+R)/100]. Half-yearly compounding: use R/2 as rate, 2T as time periods. Quarterly: R/4 as rate, 4T as periods. ELIMINATION TRICK: if a problem changes the rate for ONE specific later year/period, apply the new rate only to the ACCUMULATED amount up to that point — never recompute from the original principal with a blended rate.", trapcat: "SI vs CI", level: "L2 Application" },
    { q: "The price of an item is first increased by 25% and then decreased by 20%. Find the net percentage change in price.", options: ["5% increase", "0% (no net change)", "5% decrease", "10% increase"], answer: 1, explanation: "Net multiplier = 1.25 x 0.80 = 1.00, i.e., exactly 100% of the original price — a 0% net change. The trap is assuming +25% and -20% simply cancel to a non-zero value like 5%; always multiply the factors, never just subtract the percentages.", rule: "Successive % change = [(1+a/100)(1+b/100) - 1] x 100; never just add/subtract the two percentages directly. || FULL BRUSH-UP — Percentage & Profit-Loss: Fraction-to-% table (memorize): 1/2=50%, 1/3=33.33%, 1/4=25%, 1/5=20%, 1/6=16.67%, 1/7=14.28%, 1/8=12.5%, 1/9=11.11%, 1/10=10%, 1/11=9.09%, 1/12=8.33% — instantly convert common fractions without long division. Successive % change: net multiplier=(1+a/100)(1+b/100); NEVER just add/subtract the two percentages. Profit%=((SP-CP)/CP)*100, Loss%=((CP-SP)/CP)*100. Discount is always on Marked Price: SP=MP*(1-discount%/100). Faulty weight dealer: Profit% = [(True weight-False weight)/False weight]*100 (denominator is the ACTUAL/false weight given, not the claimed one). ELIMINATION TRICK: when markup% and discount% are both given, compute via MP and SP step by step — an option that looks like a simple (markup% - discount%) subtraction is almost always the trap.", trapcat: "Percentage (successive change)", level: "L2 Application" },
    { q: "A shopkeeper marks an article 50% above its cost price of Rs. 2,000, then allows a 20% discount on the marked price. Find his profit percentage.", options: ["10%", "30%", "0% (no profit no loss)", "20%"], answer: 3, explanation: "MP = 2000 x 1.5 = Rs.3000. SP = MP x 0.8 = Rs.2400. Profit = 2400-2000 = Rs.400, i.e. 20% profit. The trap is assuming the 50% markup and 20% discount cancel to a 30% net profit by simple subtraction — they do not, since discount applies to the ALREADY marked-up price.", rule: "Chain MP and SP step by step on the actual CP; never subtract markup% and discount% directly. || FULL BRUSH-UP — Percentage & Profit-Loss: Fraction-to-% table (memorize): 1/2=50%, 1/3=33.33%, 1/4=25%, 1/5=20%, 1/6=16.67%, 1/7=14.28%, 1/8=12.5%, 1/9=11.11%, 1/10=10%, 1/11=9.09%, 1/12=8.33% — instantly convert common fractions without long division. Successive % change: net multiplier=(1+a/100)(1+b/100); NEVER just add/subtract the two percentages. Profit%=((SP-CP)/CP)*100, Loss%=((CP-SP)/CP)*100. Discount is always on Marked Price: SP=MP*(1-discount%/100). Faulty weight dealer: Profit% = [(True weight-False weight)/False weight]*100 (denominator is the ACTUAL/false weight given, not the claimed one). ELIMINATION TRICK: when markup% and discount% are both given, compute via MP and SP step by step — an option that looks like a simple (markup% - discount%) subtraction is almost always the trap.", trapcat: "Profit & Loss (multi-step)", level: "L2 Application" },
    { q: "A is twice as efficient as B. Working together, they complete a work in 8 days. In how many days can B alone complete the work?", options: ["16 days", "24 days", "20 days", "12 days"], answer: 1, explanation: "Let B's 1-day work = x, so A's = 2x. Together: 3x = 1/8 => x = 1/24. So B alone takes 24 days (and A alone would take 12 days). 12 days is A's time (a common mix-up of which person the question asks about); 16 and 20 don't satisfy the 2:1 efficiency ratio at all.", rule: "Set up efficiency ratio as work-rates (not days) first, combine rates, then convert back to days only at the end. || FULL BRUSH-UP — Time, Work & Pipes: Work rate = 1/(days to finish). Combine rates by ADDING for people/inlet-pipes working together. Outlet/emptying pipes are NEGATIVE rates — subtract, don't add. Efficiency ratio is the INVERSE of the time ratio (if A is twice as efficient as B, A takes HALF the time B takes). 'A and B together do a work B could do alone in X days' type: always set up rate equations from the given condition, don't guess-and-check arbitrary day values. ELIMINATION TRICK: if a solved 'days' value doesn't divide evenly into the LCM used for total work units, recheck your rate setup — most of these problems are designed around clean LCM-based total work values.", trapcat: "Time and Work", level: "L2 Application" },
    { q: "Pipe A can fill a tank in 12 hours, Pipe B in 15 hours. An outlet pipe C can empty the full tank in 20 hours. If all three are opened together, in how many hours will the tank be filled?", options: ["15 hours", "8 hours", "10 hours", "12 hours"], answer: 2, explanation: "Combined rate = 1/12+1/15-1/20 = (5+4-3)/60 = 6/60 = 1/10 per hour. So the tank fills in 10 hours. A common trap is adding all three rates as positive (ignoring that C is an OUTLET, which must be subtracted) — this would give a wrong, faster time.", rule: "Always treat outlet/emptying pipes as NEGATIVE rates when combining with inlet pipes. || FULL BRUSH-UP — Time, Work & Pipes: Work rate = 1/(days to finish). Combine rates by ADDING for people/inlet-pipes working together. Outlet/emptying pipes are NEGATIVE rates — subtract, don't add. Efficiency ratio is the INVERSE of the time ratio (if A is twice as efficient as B, A takes HALF the time B takes). 'A and B together do a work B could do alone in X days' type: always set up rate equations from the given condition, don't guess-and-check arbitrary day values. ELIMINATION TRICK: if a solved 'days' value doesn't divide evenly into the LCM used for total work units, recheck your rate setup — most of these problems are designed around clean LCM-based total work values.", trapcat: "Time and Work (pipes)", level: "L2 Application" },
    { q: "A invests Rs. 5,000 for the full year (12 months). B invests Rs. 6,000 but only for 8 months (joining later). Find the ratio in which they should share the annual profit.", options: ["5:4", "4:5", "5:6", "7:4"], answer: 0, explanation: "Capital x Time: A = 5000x12 = 60000; B = 6000x8 = 48000. Ratio = 60000:48000 = 5:4. 5:6 ignores the TIME factor entirely (uses only capital); the reversed ratio swaps A and B's shares incorrectly.", rule: "Partnership profit ratio = (Capital x Time) for each partner, never capital alone when durations differ. || FULL BRUSH-UP — Ratio, Average & Partnership: To combine two ratios sharing a common term (e.g. A:B and B:C), scale both so the common term (B) matches via LCM, then merge into one combined ratio. Partnership profit-share = Capital * Time-invested for each partner (never capital alone if durations differ). Average of an Arithmetic Progression = (first term + last term)/2. Combined average of two groups of DIFFERENT sizes = weighted average = (n1*a1+n2*a2)/(n1+n2), never the simple average of the two averages unless the group sizes are equal. ELIMINATION TRICK: an option that's just the plain average of two given averages (ignoring group sizes/weights) is the single most common average-question trap.", trapcat: "Ratio & Proportion (Partnership)", level: "L2 Application" },
    { q: "A vessel contains 40 litres of pure milk. 8 litres of milk is withdrawn and replaced with water; this process is repeated once more (total twice). Find the quantity of pure milk left in the vessel.", options: ["30.0 litres", "25.6 litres", "28.0 litres", "24.0 litres"], answer: 1, explanation: "Formula: Milk left = V x [(V-d)/V]^n = 40 x (32/40)^2 = 40 x 0.64 = 25.6 litres. 24.0 and 30.0 assume a simple linear subtraction (40 - 8 - 8 = 24, or similar), which is WRONG for replacement problems since the second withdrawal removes a diluted mixture, not pure milk.", rule: "Replacement formula: Final quantity = Initial x [(V-d)/V]^n — never subtract the withdrawn amount linearly after the first replacement. || FULL BRUSH-UP — Mixture & Alligation: Alligation cross-rule: (Quantity of cheaper)/(Quantity of dearer) = (Dearer price - Mean price)/(Mean price - Cheaper price). Replacement formula (withdraw-and-replace repeated n times): Final quantity of original substance = Initial quantity * [(Volume - amount withdrawn each time)/Volume]^n — this is NOT linear subtraction after the first round, since later withdrawals remove an already-diluted mixture. ELIMINATION TRICK: any option from simple repeated subtraction (e.g., V - d - d for n=2 replacements) ignores dilution and is always the trap in a 'replace and repeat' problem.", trapcat: "Mixture & Alligation (replacement)", level: "L3 Trap" },
    { q: "A boat's speed in still water is 10 km/h and the stream's speed is 2 km/h. Find the total time taken to travel 24 km upstream and then return 24 km downstream.", options: ["4.00 hours", "4.50 hours", "5.00 hours", "6.00 hours"], answer: 2, explanation: "Upstream speed = 10-2=8 km/h, time=24/8=3.00 hr. Downstream speed=10+2=12 km/h, time=24/12=2.00 hr. Total = 5.00 hr. 4.00 hours assumes a flat average speed of 12 km/h for the full 48 km round trip, ignoring that upstream and downstream speeds (and hence individual times) differ.", rule: "Never average upstream/downstream SPEEDS directly for total time — compute each leg's time separately from its own speed, then add. || FULL BRUSH-UP — Time-Speed-Distance: Convert km/h to m/s by multiplying by 5/18 (and m/s to km/h by 18/5). Same direction -> RELATIVE SPEED = difference of speeds. Opposite directions -> RELATIVE SPEED = sum of speeds. Trains crossing: distance to cover = sum of both lengths (if crossing each other) or just one length (crossing a pole). Average speed for equal distances at two different speeds x,y = 2xy/(x+y) (NOT the simple average (x+y)/2). Boats: Downstream speed = boat+stream, Upstream speed = boat-stream; Boat speed = (downstream+upstream)/2, Stream speed = (downstream-upstream)/2. ELIMINATION TRICK: never average two different SPEEDS directly for a round trip — only average when the TIME (not distance) is equal at both speeds; for equal distances, always use the 2xy/(x+y) harmonic-mean formula.", trapcat: "Time-Speed-Distance (boats)", level: "L2 Application" },
    { q: "Train A (120 m long) runs at 54 km/h and Train B (180 m long) runs at 36 km/h, in opposite directions on parallel tracks. Find the time taken for them to completely cross each other.", options: ["8 seconds", "12 seconds", "18 seconds", "10 seconds"], answer: 1, explanation: "Convert to m/s: 54 km/h=15 m/s, 36 km/h=10 m/s. Relative speed (opposite directions, so ADD) = 25 m/s. Total distance to cross = sum of lengths = 120+180=300 m. Time = 300/25 = 12 s. 10 seconds would result from forgetting to add both train lengths (using only one length); using SUBTRACTED relative speed (as if same direction) would give a much longer, wrong time.", rule: "Opposite directions -> ADD speeds; same direction -> SUBTRACT speeds. Distance to cross = sum of both lengths, always. || FULL BRUSH-UP — Time-Speed-Distance: Convert km/h to m/s by multiplying by 5/18 (and m/s to km/h by 18/5). Same direction -> RELATIVE SPEED = difference of speeds. Opposite directions -> RELATIVE SPEED = sum of speeds. Trains crossing: distance to cover = sum of both lengths (if crossing each other) or just one length (crossing a pole). Average speed for equal distances at two different speeds x,y = 2xy/(x+y) (NOT the simple average (x+y)/2). Boats: Downstream speed = boat+stream, Upstream speed = boat-stream; Boat speed = (downstream+upstream)/2, Stream speed = (downstream-upstream)/2. ELIMINATION TRICK: never average two different SPEEDS directly for a round trip — only average when the TIME (not distance) is equal at both speeds; for equal distances, always use the 2xy/(x+y) harmonic-mean formula.", trapcat: "Time-Speed-Distance (trains)", level: "L2 Application" },
    { q: "If x + 1/x = 4, find the value of x^3 + 1/x^3.", options: ["52", "40", "64", "60"], answer: 0, explanation: "x^3+1/x^3 = (x+1/x)^3 - 3(x+1/x) = 4^3 - 3x4 = 64-12 = 52. 64 is simply 4^3 without subtracting the 3(x+1/x) correction term — a very common identity-application error.", rule: "Memorize: x^3+1/x^3 = (x+1/x)^3 - 3(x+1/x). Do not forget the subtraction term. || FULL IDENTITY BRUSH-UP — Algebra: (a+b)^2=a^2+2ab+b^2 | (a-b)^2=a^2-2ab+b^2 | a^2-b^2=(a+b)(a-b) | (a+b)^3=a^3+b^3+3ab(a+b) | (a-b)^3=a^3-b^3-3ab(a-b) | a^3+b^3=(a+b)(a^2-ab+b^2) | a^3-b^3=(a-b)(a^2+ab+b^2) | a^2+b^2=(a+b)^2-2ab=(a-b)^2+2ab. x+1/x relations: if x+1/x=k, then x^2+1/x^2=k^2-2, and x^3+1/x^3=k^3-3k. If x-1/x=k, then x^2+1/x^2=k^2+2, and x^3-1/x^3=k^3+3k (sign flips vs the + version — a common trap). ELIMINATION TRICK: any option that looks like just 'k^3' or 'k^2' WITHOUT the correction term (-3k or -2) is a near-miss trap testing whether you remember the full identity.", trapcat: "Algebra (identities)", level: "L2 Application" },
    { q: "3 chairs and 2 tables together cost Rs. 1,500. 5 chairs and 3 tables together cost Rs. 2,350. Find the cost of 1 chair and 1 table together.", options: ["Rs. 650", "Rs. 600", "Rs. 750", "Rs. 700"], answer: 0, explanation: "3c+2t=1500 ...(i); 5c+3t=2350 ...(ii). Multiply (i) by 3 and (ii) by 2: 9c+6t=4500, 10c+6t=4700. Subtract: c=200. Substitute: 3(200)+2t=1500 => t=450. Chair+Table = Rs.650. Rs.700 is a plausible-looking round number that doesn't actually satisfy both original equations when checked.", rule: "Use elimination by matching coefficients (LCM of coefficients) rather than guessing round-number answers. || FULL IDENTITY BRUSH-UP — Algebra: (a+b)^2=a^2+2ab+b^2 | (a-b)^2=a^2-2ab+b^2 | a^2-b^2=(a+b)(a-b) | (a+b)^3=a^3+b^3+3ab(a+b) | (a-b)^3=a^3-b^3-3ab(a-b) | a^3+b^3=(a+b)(a^2-ab+b^2) | a^3-b^3=(a-b)(a^2+ab+b^2) | a^2+b^2=(a+b)^2-2ab=(a-b)^2+2ab. x+1/x relations: if x+1/x=k, then x^2+1/x^2=k^2-2, and x^3+1/x^3=k^3-3k. If x-1/x=k, then x^2+1/x^2=k^2+2, and x^3-1/x^3=k^3+3k (sign flips vs the + version — a common trap). ELIMINATION TRICK: any option that looks like just 'k^3' or 'k^2' WITHOUT the correction term (-3k or -2) is a near-miss trap testing whether you remember the full identity.", trapcat: "Algebra (simultaneous equations)", level: "L2 Application" },
    { q: "Find the area of a triangle with sides 13 cm, 14 cm, and 15 cm.", options: ["98 sq cm", "78 sq cm", "94 sq cm", "84 sq cm"], answer: 3, explanation: "Using Heron's formula: s=(13+14+15)/2=21. Area=sqrt(21x8x7x6)=sqrt(7056)=84 sq cm. 98 sq cm would result from a half-base-height guess without properly finding the height; this triangle is NOT right-angled so no Pythagorean shortcut applies here.", rule: "When sides don't form a Pythagorean triple, Heron's formula is required — check for a triple first (as a shortcut) before defaulting to Heron's. || FULL FORMULA BRUSH-UP — Mensuration (2D): Square: Area=a^2, Perimeter=4a, Diagonal=a*sqrt(2). Rectangle: Area=l*b, Perimeter=2(l+b), Diagonal=sqrt(l^2+b^2). Triangle(general): Area=(1/2)*base*height; Heron's: s=(a+b+c)/2, Area=sqrt(s(s-a)(s-b)(s-c)). Equilateral triangle: Area=(sqrt(3)/4)*a^2, Height=(sqrt(3)/2)*a. Right triangle: Area=(1/2)*base*height(the two legs). Parallelogram: Area=base*height. Rhombus: Area=(1/2)*d1*d2. Trapezium: Area=(1/2)*(sum of parallel sides)*height. Circle: Area=pi*r^2, Circumference=2*pi*r. Sector: Area=(theta/360)*pi*r^2, Arc length=(theta/360)*2*pi*r. FULL FORMULA BRUSH-UP — Mensuration (3D): Cube: Volume=a^3, Surface Area=6a^2. Cuboid: Volume=l*b*h, Surface Area=2(lb+bh+hl). Cylinder: Volume=pi*r^2*h, Curved SA=2*pi*r*h, Total SA=2*pi*r(r+h). Cone: Volume=(1/3)*pi*r^2*h, Slant height l=sqrt(r^2+h^2), Curved SA=pi*r*l. Sphere: Volume=(4/3)*pi*r^3, SA=4*pi*r^2. Hemisphere: Volume=(2/3)*pi*r^3, Curved SA=2*pi*r^2, Total SA=3*pi*r^2. ELIMINATION TRICK: when only ONE linear dimension (radius/side) changes, ratios scale by its POWER matching the quantity asked — length ratios stay as given, area ratios SQUARE it, volume ratios CUBE it. Options using the wrong power are traps.", trapcat: "Geometry (Heron's formula)", level: "L2 Application" },
    { q: "The largest possible circle is inscribed in a square of side 14 cm. Find the area of the square NOT covered by the circle. (Use pi = 22/7)", options: ["154 sq cm", "42 sq cm", "62 sq cm", "32 sq cm"], answer: 1, explanation: "Circle's diameter = side of square = 14 cm, so radius = 7 cm. Area of circle = (22/7)x7x7 = 154 sq cm. Area of square = 14x14=196 sq cm. Uncovered area = 196-154 = 42 sq cm. 154 sq cm is the circle's OWN area, not the uncovered region — a common careless mix-up of what's actually being asked.", rule: "For 'largest circle inscribed in a square', diameter = side of square; always re-read whether the question wants the circle's area or the LEFTOVER area. || FULL FORMULA BRUSH-UP — Mensuration (2D): Square: Area=a^2, Perimeter=4a, Diagonal=a*sqrt(2). Rectangle: Area=l*b, Perimeter=2(l+b), Diagonal=sqrt(l^2+b^2). Triangle(general): Area=(1/2)*base*height; Heron's: s=(a+b+c)/2, Area=sqrt(s(s-a)(s-b)(s-c)). Equilateral triangle: Area=(sqrt(3)/4)*a^2, Height=(sqrt(3)/2)*a. Right triangle: Area=(1/2)*base*height(the two legs). Parallelogram: Area=base*height. Rhombus: Area=(1/2)*d1*d2. Trapezium: Area=(1/2)*(sum of parallel sides)*height. Circle: Area=pi*r^2, Circumference=2*pi*r. Sector: Area=(theta/360)*pi*r^2, Arc length=(theta/360)*2*pi*r. FULL FORMULA BRUSH-UP — Mensuration (3D): Cube: Volume=a^3, Surface Area=6a^2. Cuboid: Volume=l*b*h, Surface Area=2(lb+bh+hl). Cylinder: Volume=pi*r^2*h, Curved SA=2*pi*r*h, Total SA=2*pi*r(r+h). Cone: Volume=(1/3)*pi*r^2*h, Slant height l=sqrt(r^2+h^2), Curved SA=pi*r*l. Sphere: Volume=(4/3)*pi*r^3, SA=4*pi*r^2. Hemisphere: Volume=(2/3)*pi*r^3, Curved SA=2*pi*r^2, Total SA=3*pi*r^2. ELIMINATION TRICK: when only ONE linear dimension (radius/side) changes, ratios scale by its POWER matching the quantity asked — length ratios stay as given, area ratios SQUARE it, volume ratios CUBE it. Options using the wrong power are traps.", trapcat: "Mensuration (combined figures)", level: "L2 Application" },
    { q: "Find the greatest number which divides both 245 and 1029, leaving a remainder of 5 in each case.", options: ["8", "41", "16", "32"], answer: 2, explanation: "Subtract the remainder from both numbers: 245-5=240, 1029-5=1024. The required number = HCF(240,1024) = 16. 41 and other distractors come from taking HCF of the ORIGINAL numbers (245,1029) without first subtracting the remainder — a frequent omission.", rule: "For 'divides leaving remainder r' problems, ALWAYS subtract r from each number first, then find HCF. || FULL BRUSH-UP — Number System: Divisibility rules: by 2(last digit even), by 3(digit sum divisible by 3), by 4(last 2 digits divisible by 4), by 5(last digit 0 or 5), by 6(divisible by both 2 and 3), by 8(last 3 digits divisible by 8), by 9(digit sum divisible by 9), by 11(alternating digit-sum difference divisible by 11). Unit-digit cycles: 2:(2,4,8,6) | 3:(3,9,7,1) | 4:(4,6) | 7:(7,9,3,1) | 8:(8,4,2,6) | 9:(9,1) — cycle length 4 for 2/3/7/8, length 2 for 4/9, and 0/1/5/6 always repeat themselves. 'Divides leaving remainder r' -> subtract r first, then take HCF/LCM. 'Smallest number to subtract/add to be divisible by d' -> use (N mod d) as the subtract value, (d - N mod d) as the add value. ELIMINATION TRICK: for unit-digit/remainder problems, if the exponent is an EXACT multiple of the cycle length, use the LAST value in the cycle (not a 'zero' position) — the most common off-by-one trap.", trapcat: "Number System (HCF/LCM)", level: "L2 Application" },
    { q: "Find the unit digit of (247^45 x 368^56).", options: ["3", "7", "2", "5"], answer: 2, explanation: "Unit digit of 247^45 depends on 7's cycle (7,9,3,1): 45 mod 4=1, so unit digit=7. Unit digit of 368^56 depends on 8's cycle (8,4,2,6): 56 mod 4=0, so use the LAST position of the cycle, giving unit digit=6. Multiply the two unit digits: 7x6=42, final unit digit=2. Other options result from miscounting the cycle position (off-by-one errors) when the exponent is an exact multiple of the cycle length.", rule: "When exponent mod cycle-length = 0, use the LAST value in the cycle, not a 'zeroth' or wraparound value — this is the most common off-by-one trap. || FULL BRUSH-UP — Number System: Divisibility rules: by 2(last digit even), by 3(digit sum divisible by 3), by 4(last 2 digits divisible by 4), by 5(last digit 0 or 5), by 6(divisible by both 2 and 3), by 8(last 3 digits divisible by 8), by 9(digit sum divisible by 9), by 11(alternating digit-sum difference divisible by 11). Unit-digit cycles: 2:(2,4,8,6) | 3:(3,9,7,1) | 4:(4,6) | 7:(7,9,3,1) | 8:(8,4,2,6) | 9:(9,1) — cycle length 4 for 2/3/7/8, length 2 for 4/9, and 0/1/5/6 always repeat themselves. 'Divides leaving remainder r' -> subtract r first, then take HCF/LCM. 'Smallest number to subtract/add to be divisible by d' -> use (N mod d) as the subtract value, (d - N mod d) as the add value. ELIMINATION TRICK: for unit-digit/remainder problems, if the exponent is an EXACT multiple of the cycle length, use the LAST value in the cycle (not a 'zero' position) — the most common off-by-one trap.", trapcat: "Number System (unit digit)", level: "L3 Trap" },
    { q: "The angle of elevation of the top of a tower from a point on the ground is 30 degrees. Moving 20 m closer to the tower, the angle of elevation becomes 60 degrees. Find the height of the tower. (Use sqrt(3)=1.732)", options: ["34.64 m", "11.55 m", "17.32 m", "20.00 m"], answer: 2, explanation: "Let height=h, far distance=d. tan30=h/d => d=h*sqrt(3). Near distance=(d-20), tan60=h/(d-20) => d-20=h/sqrt(3). Subtracting: h*sqrt(3) - h/sqrt(3) = 20 => h(3-1)/sqrt(3)=20 => h=20*sqrt(3)/2=10*sqrt(3)=17.32 m. 34.64 m (double the answer) comes from a sign error in combining the two equations; 20.00 m and 11.55 m come from using only one angle's equation and ignoring the 20 m shift entirely.", rule: "Two-angle height-distance problems: set up BOTH tan equations with the distance difference equal to the given shift (20 m), then eliminate d algebraically. || FULL BRUSH-UP — Trigonometric ratio table (memorize fully): | Angle:    0    30        45        60        90 | sin:      0    1/2       1/sqrt2   sqrt3/2   1 | cos:      1    sqrt3/2   1/sqrt2   1/2       0 | tan:      0    1/sqrt3   1         sqrt3     undefined | Identities: sin^2A+cos^2A=1 | 1+tan^2A=sec^2A | 1+cot^2A=cosec^2A | tanA=sinA/cosA | cotA=1/tanA. Height-Distance setup: angle of elevation increases as you move CLOSER to the object; for a two-angle problem, set up tan(angle1)=h/d1 and tan(angle2)=h/d2, use the given distance DIFFERENCE (d1-d2) to eliminate one variable algebraically. ELIMINATION TRICK: tan45=1 always gives height=base distance exactly — if an option doesn't equal the given distance in a 45-degree case, eliminate it instantly.", trapcat: "Trigonometry (height & distance)", level: "L3 Trap" },
    { q: "Simplify: (1 - sin^2 A)(1 + tan^2 A).", options: ["cos^2 A", "1", "2", "sin^2 A"], answer: 1, explanation: "(1-sin^2A) = cos^2A. (1+tan^2A) = sec^2A = 1/cos^2A. Product = cos^2A x 1/cos^2A = 1. cos^2A and sin^2A are each only ONE of the two factors before multiplying, not the simplified product; 2 is not derivable from any correct identity substitution here.", rule: "Memorize the Pythagorean identities: 1-sin^2A=cos^2A, 1+tan^2A=sec^2A, 1+cot^2A=cosec^2A — apply both together before multiplying. || FULL BRUSH-UP — Trigonometric ratio table (memorize fully): | Angle:    0    30        45        60        90 | sin:      0    1/2       1/sqrt2   sqrt3/2   1 | cos:      1    sqrt3/2   1/sqrt2   1/2       0 | tan:      0    1/sqrt3   1         sqrt3     undefined | Identities: sin^2A+cos^2A=1 | 1+tan^2A=sec^2A | 1+cot^2A=cosec^2A | tanA=sinA/cosA | cotA=1/tanA. Height-Distance setup: angle of elevation increases as you move CLOSER to the object; for a two-angle problem, set up tan(angle1)=h/d1 and tan(angle2)=h/d2, use the given distance DIFFERENCE (d1-d2) to eliminate one variable algebraically. ELIMINATION TRICK: tan45=1 always gives height=base distance exactly — if an option doesn't equal the given distance in a 45-degree case, eliminate it instantly.", trapcat: "Trigonometry (identities)", level: "L2 Application" },
    { q: "Four products P, Q, R, S recorded sales (in units) of 450, 620, 380, and 550 respectively in a month. Find R's sales as a percentage of the TOTAL sales of all four products (nearest whole %).", options: ["25%", "24%", "19%", "13%"], answer: 2, explanation: "Total = 450+620+380+550 = 2000. R's share = 380/2000 x 100 = 19.0% ≈ 19%. 25% is a tempting round guess (380 is roughly a quarter-ish of a 1500-2000 range) but doesn't match the actual precise total; always compute the real total first.", rule: "Always sum ALL given categories first for a 'percentage of total' question — never estimate the total. || FULL BRUSH-UP — Percentage & Profit-Loss: Fraction-to-% table (memorize): 1/2=50%, 1/3=33.33%, 1/4=25%, 1/5=20%, 1/6=16.67%, 1/7=14.28%, 1/8=12.5%, 1/9=11.11%, 1/10=10%, 1/11=9.09%, 1/12=8.33% — instantly convert common fractions without long division. Successive % change: net multiplier=(1+a/100)(1+b/100); NEVER just add/subtract the two percentages. Profit%=((SP-CP)/CP)*100, Loss%=((CP-SP)/CP)*100. Discount is always on Marked Price: SP=MP*(1-discount%/100). Faulty weight dealer: Profit% = [(True weight-False weight)/False weight]*100 (denominator is the ACTUAL/false weight given, not the claimed one). ELIMINATION TRICK: when markup% and discount% are both given, compute via MP and SP step by step — an option that looks like a simple (markup% - discount%) subtraction is almost always the trap.", trapcat: "Data Interpretation (percentage of total)", level: "L1 Direct" },
    { q: "A class of 30 students has an average score of 60 marks. Another class of 20 students has an average score of 75 marks. Find the combined average score of all 50 students.", options: ["67.5 marks", "62 marks", "66 marks", "68 marks"], answer: 2, explanation: "Total marks = (30x60)+(20x75) = 1800+1500=3300. Combined average = 3300/50 = 66 marks. 67.5 is the simple (unweighted) average of 60 and 75, ignoring that the two groups have different sizes.", rule: "Combined average of groups of DIFFERENT sizes must be weighted by count — never average the two averages directly unless the group sizes are equal. || FULL BRUSH-UP — Ratio, Average & Partnership: To combine two ratios sharing a common term (e.g. A:B and B:C), scale both so the common term (B) matches via LCM, then merge into one combined ratio. Partnership profit-share = Capital * Time-invested for each partner (never capital alone if durations differ). Average of an Arithmetic Progression = (first term + last term)/2. Combined average of two groups of DIFFERENT sizes = weighted average = (n1*a1+n2*a2)/(n1+n2), never the simple average of the two averages unless the group sizes are equal. ELIMINATION TRICK: an option that's just the plain average of two given averages (ignoring group sizes/weights) is the single most common average-question trap.", trapcat: "Average (weighted)", level: "L2 Application" },
    { q: "Rs. 7,800 is divided among A, B, and C such that A:B = 3:4 and B:C = 5:6. Find C's share.", options: ["Rs. 3373", "Rs. 2773", "Rs. 2,600", "Rs. 3173"], answer: 3, explanation: "Make B's value common: A:B=3:4=15:20 (x5), B:C=5:6=20:24 (x4). So A:B:C=15:20:24, total parts=59. C's share = 7800 x 24/59 = Rs.3173. Rs.2,600 comes from naively dividing 7800 by 3 (treating it as a simple 3-way equal split), ignoring the actual ratio chain entirely.", rule: "To combine two ratios sharing a common term (B here), scale both so the common term matches before combining into one three-part ratio. || FULL BRUSH-UP — Ratio, Average & Partnership: To combine two ratios sharing a common term (e.g. A:B and B:C), scale both so the common term (B) matches via LCM, then merge into one combined ratio. Partnership profit-share = Capital * Time-invested for each partner (never capital alone if durations differ). Average of an Arithmetic Progression = (first term + last term)/2. Combined average of two groups of DIFFERENT sizes = weighted average = (n1*a1+n2*a2)/(n1+n2), never the simple average of the two averages unless the group sizes are equal. ELIMINATION TRICK: an option that's just the plain average of two given averages (ignoring group sizes/weights) is the single most common average-question trap.", trapcat: "Ratio & Proportion (combining ratios)", level: "L2 Application" },
    { q: "A dishonest dealer professes to sell his goods at cost price but uses a weight of 800 grams instead of 1000 grams (1 kg). Find his profit percentage.", options: ["25%", "16.67%", "12.5%", "20%"], answer: 0, explanation: "He gives only 800g while charging for 1000g. Profit % = (1000-800)/800 x 100 = 25.00% = 25%. 20% comes from wrongly using (1000-800)/1000 as the base (should be the ACTUAL quantity given, 800, not the claimed quantity); 12.5% and 16.67% are unrelated miscalculations.", rule: "Faulty weight profit % = [(True weight - False weight)/False weight] x 100 — the DENOMINATOR is the false (actually given) weight, not the claimed one. || FULL BRUSH-UP — Percentage & Profit-Loss: Fraction-to-% table (memorize): 1/2=50%, 1/3=33.33%, 1/4=25%, 1/5=20%, 1/6=16.67%, 1/7=14.28%, 1/8=12.5%, 1/9=11.11%, 1/10=10%, 1/11=9.09%, 1/12=8.33% — instantly convert common fractions without long division. Successive % change: net multiplier=(1+a/100)(1+b/100); NEVER just add/subtract the two percentages. Profit%=((SP-CP)/CP)*100, Loss%=((CP-SP)/CP)*100. Discount is always on Marked Price: SP=MP*(1-discount%/100). Faulty weight dealer: Profit% = [(True weight-False weight)/False weight]*100 (denominator is the ACTUAL/false weight given, not the claimed one). ELIMINATION TRICK: when markup% and discount% are both given, compute via MP and SP step by step — an option that looks like a simple (markup% - discount%) subtraction is almost always the trap.", trapcat: "Profit & Loss (faulty weight)", level: "L3 Trap" },
    { q: "5 years ago, a father's age was 7 times his son's age. 5 years from now, the father's age will be 3 times his son's age. Find their present ages.", options: ["Father = 50 years, Son = 10 years", "Father = 45 years, Son = 15 years", "Father = 35 years, Son = 15 years", "Father = 40 years, Son = 10 years"], answer: 3, explanation: "Let son's age 5 yrs ago = x, father's = 7x. Present: son=x+5, father=7x+5. 5 yrs hence: 7x+10=3(x+10) => 4x=20 => x=5. Present son=10, father=40. The other options use inconsistent or unverified age pairs that fail one of the two given time conditions when checked.", rule: "For two-condition age problems, define variables at the EARLIEST reference point (5 years ago here) and build both equations from there. || FULL IDENTITY BRUSH-UP — Algebra: (a+b)^2=a^2+2ab+b^2 | (a-b)^2=a^2-2ab+b^2 | a^2-b^2=(a+b)(a-b) | (a+b)^3=a^3+b^3+3ab(a+b) | (a-b)^3=a^3-b^3-3ab(a-b) | a^3+b^3=(a+b)(a^2-ab+b^2) | a^3-b^3=(a-b)(a^2+ab+b^2) | a^2+b^2=(a+b)^2-2ab=(a-b)^2+2ab. x+1/x relations: if x+1/x=k, then x^2+1/x^2=k^2-2, and x^3+1/x^3=k^3-3k. If x-1/x=k, then x^2+1/x^2=k^2+2, and x^3-1/x^3=k^3+3k (sign flips vs the + version — a common trap). ELIMINATION TRICK: any option that looks like just 'k^3' or 'k^2' WITHOUT the correction term (-3k or -2) is a near-miss trap testing whether you remember the full identity.", trapcat: "Algebra (ages)", level: "L2 Application" },
    { q: "Two cylinders have the same height but their radii are in the ratio 2:3. Find the ratio of their volumes.", options: ["2:3", "4:9", "16:81", "8:27"], answer: 1, explanation: "Volume of cylinder = pi r^2 h. Since height is same, Volume ratio = r1^2 : r2^2 = 2^2:3^2 = 4:9. 2:3 wrongly uses the radius ratio directly without squaring; 8:27 wrongly cubes it (that would apply if BOTH radius and height scaled together, like similar solids, not here); 16:81 wrongly uses the 4th power.", rule: "Cylinder volume depends on r^2 (not r), so when only radius differs, square the ratio; cube only when a solid scales uniformly in all 3 dimensions. || FULL FORMULA BRUSH-UP — Mensuration (2D): Square: Area=a^2, Perimeter=4a, Diagonal=a*sqrt(2). Rectangle: Area=l*b, Perimeter=2(l+b), Diagonal=sqrt(l^2+b^2). Triangle(general): Area=(1/2)*base*height; Heron's: s=(a+b+c)/2, Area=sqrt(s(s-a)(s-b)(s-c)). Equilateral triangle: Area=(sqrt(3)/4)*a^2, Height=(sqrt(3)/2)*a. Right triangle: Area=(1/2)*base*height(the two legs). Parallelogram: Area=base*height. Rhombus: Area=(1/2)*d1*d2. Trapezium: Area=(1/2)*(sum of parallel sides)*height. Circle: Area=pi*r^2, Circumference=2*pi*r. Sector: Area=(theta/360)*pi*r^2, Arc length=(theta/360)*2*pi*r. FULL FORMULA BRUSH-UP — Mensuration (3D): Cube: Volume=a^3, Surface Area=6a^2. Cuboid: Volume=l*b*h, Surface Area=2(lb+bh+hl). Cylinder: Volume=pi*r^2*h, Curved SA=2*pi*r*h, Total SA=2*pi*r(r+h). Cone: Volume=(1/3)*pi*r^2*h, Slant height l=sqrt(r^2+h^2), Curved SA=pi*r*l. Sphere: Volume=(4/3)*pi*r^3, SA=4*pi*r^2. Hemisphere: Volume=(2/3)*pi*r^3, Curved SA=2*pi*r^2, Total SA=3*pi*r^2. ELIMINATION TRICK: when only ONE linear dimension (radius/side) changes, ratios scale by its POWER matching the quantity asked — length ratios stay as given, area ratios SQUARE it, volume ratios CUBE it. Options using the wrong power are traps.", trapcat: "Mensuration (cylinder)", level: "L2 Application" },
    { q: "Find the remainder when 2^50 is divided by 7.", options: ["0", "2", "4", "5"], answer: 2, explanation: "2^3=8 leaves remainder 1 when divided by 7, so 2^3 ≡ 1 (mod 7). 50=3x16+2, so 2^50=(2^3)^16 x 2^2 ≡ 1^16 x 4 = 4 (mod 7). Remainder = 4. Other remainders arise from miscounting the leftover power after dividing the exponent by the cycle length (here 3), a common off-by-one slip.", rule: "Find the smallest power of the base that gives remainder 1 (here 2^3≡1 mod 7), then reduce the exponent modulo that cycle length before computing the leftover power. || FULL BRUSH-UP — Number System: Divisibility rules: by 2(last digit even), by 3(digit sum divisible by 3), by 4(last 2 digits divisible by 4), by 5(last digit 0 or 5), by 6(divisible by both 2 and 3), by 8(last 3 digits divisible by 8), by 9(digit sum divisible by 9), by 11(alternating digit-sum difference divisible by 11). Unit-digit cycles: 2:(2,4,8,6) | 3:(3,9,7,1) | 4:(4,6) | 7:(7,9,3,1) | 8:(8,4,2,6) | 9:(9,1) — cycle length 4 for 2/3/7/8, length 2 for 4/9, and 0/1/5/6 always repeat themselves. 'Divides leaving remainder r' -> subtract r first, then take HCF/LCM. 'Smallest number to subtract/add to be divisible by d' -> use (N mod d) as the subtract value, (d - N mod d) as the add value. ELIMINATION TRICK: for unit-digit/remainder problems, if the exponent is an EXACT multiple of the cycle length, use the LAST value in the cycle (not a 'zero' position) — the most common off-by-one trap.", trapcat: "Number System (remainders)", level: "L3 Trap" }
  ]
},
{
  id: "oct6_gs2", label: "Extreme GS Test 2 (History/Polity/Geography/Economy/Science)", timeLimitMin: 25,
  questions: [
    { q: "The 'Non-Cooperation Movement' (1920) was withdrawn by Gandhi following which incident?", options: ["Jallianwala Bagh massacre (1919)", "The Poona Pact (1932)", "Chauri Chaura incident (1922, a mob burned a police station, killing policemen)", "Simon Commission's arrival (1928)"], answer: 2, explanation: "Gandhi withdrew the Non-Cooperation Movement in 1922 after the Chauri Chaura incident, where a violent mob clash led to policemen's deaths, contradicting the movement's strict non-violence principle. Jallianwala Bagh (1919) actually PRECEDED and partly triggered the movement's launch, not its withdrawal; Simon Commission's arrival sparked separate 'Simon Go Back' protests in 1928; the Poona Pact (1932) concerned separate electorates for depressed classes, unrelated to NCM's withdrawal.", rule: "Chauri Chaura = NCM withdrawn (1922) due to violence breaking Gandhi's non-violence condition. || FULL BRUSH-UP — Freedom struggle timeline: 1857=First War of Independence | 1885=INC founded(A.O.Hume) | 1905=Partition of Bengal(Curzon) | 1906=Muslim League founded(Dhaka) | 1919=Jallianwala Bagh(Gen.Dyer)+Rowlatt Act | 1920=Non-Cooperation Movement(Gandhi) | 1922=Chauri Chaura incident(NCM withdrawn) | 1930=Civil Disobedience+Dandi March(Salt Satyagraha) | 1931=Gandhi-Irwin Pact | 1935=Government of India Act | 1942=Quit India Movement('Do or Die',most leaders arrested immediately) | 1943=Bengal Famine(Viceroy Linlithgow) | 1946=Cabinet Mission | 1947=Independence+Partition(Mountbatten,last Viceroy). Key Viceroys: Curzon(Bengal partition), Hardinge(capital shifted to Delhi 1911), Chelmsford(Rowlatt Act,Jallianwala), Irwin(Dandi March,Gandhi-Irwin Pact), Linlithgow(WWII,Quit India,Bengal Famine), Wavell(Shimla Conf,Cabinet Mission), Mountbatten(last Viceroy,Partition,first Governor-General of independent India). ELIMINATION TRICK: questions often swap the VICEROY for an adjacent-era event — always anchor by decade (1905-10=Curzon/Minto, 1916-21=Chelmsford, 1926-31=Irwin, 1936-43=Linlithgow, 1943-47=Wavell then Mountbatten).", trapcat: "History", level: "L2 Application" },
    { q: "Who among the following was the first Governor-General of independent India?", options: ["Lord Mountbatten", "C. Rajagopalachari", "Lord Wavell", "Jawaharlal Nehru"], answer: 0, explanation: "Lord Mountbatten, the last Viceroy of British India, became independent India's first Governor-General (Aug 1947 - June 1948). C. Rajagopalachari was the LAST Governor-General and the only INDIAN to hold the post (1948-50), succeeding Mountbatten — a classic 'first vs last' SSC trap; Wavell was Viceroy BEFORE Mountbatten, under British rule; Nehru was the first Prime Minister, a different office entirely.", rule: "TRAP: Mountbatten=first Governor-General of independent India; Rajagopalachari=LAST Governor-General (and only Indian one) — don't swap first/last. || FULL BRUSH-UP — Freedom struggle timeline: 1857=First War of Independence | 1885=INC founded(A.O.Hume) | 1905=Partition of Bengal(Curzon) | 1906=Muslim League founded(Dhaka) | 1919=Jallianwala Bagh(Gen.Dyer)+Rowlatt Act | 1920=Non-Cooperation Movement(Gandhi) | 1922=Chauri Chaura incident(NCM withdrawn) | 1930=Civil Disobedience+Dandi March(Salt Satyagraha) | 1931=Gandhi-Irwin Pact | 1935=Government of India Act | 1942=Quit India Movement('Do or Die',most leaders arrested immediately) | 1943=Bengal Famine(Viceroy Linlithgow) | 1946=Cabinet Mission | 1947=Independence+Partition(Mountbatten,last Viceroy). Key Viceroys: Curzon(Bengal partition), Hardinge(capital shifted to Delhi 1911), Chelmsford(Rowlatt Act,Jallianwala), Irwin(Dandi March,Gandhi-Irwin Pact), Linlithgow(WWII,Quit India,Bengal Famine), Wavell(Shimla Conf,Cabinet Mission), Mountbatten(last Viceroy,Partition,first Governor-General of independent India). ELIMINATION TRICK: questions often swap the VICEROY for an adjacent-era event — always anchor by decade (1905-10=Curzon/Minto, 1916-21=Chelmsford, 1926-31=Irwin, 1936-43=Linlithgow, 1943-47=Wavell then Mountbatten).", trapcat: "History", level: "L3 Trap" },
    { q: "The 'Doctrine of Lapse', used to annex Indian princely states lacking a natural male heir, was introduced by which Governor-General?", options: ["Lord Canning", "Lord Dalhousie's predecessor, Lord Hardinge I", "Lord William Bentinck", "Lord Dalhousie"], answer: 3, explanation: "Lord Dalhousie (1848-56) introduced the Doctrine of Lapse, annexing states like Satara, Jhansi, and Nagpur when rulers died without a natural heir. Hardinge I preceded Dalhousie and is known for the Anglo-Sikh War, not this doctrine; Canning was Governor-General during the 1857 revolt (the LAST one, and first Viceroy after the Crown took over) — a frequently tested transition figure, not the doctrine's author; Bentinck (1828-35) is known for banning Sati, not the Doctrine of Lapse.", rule: "Doctrine of Lapse = Dalhousie; Canning = last Governor-General AND first Viceroy (the 1857-58 transition point) — memorize this transition pair separately. || FULL BRUSH-UP — Freedom struggle timeline: 1857=First War of Independence | 1885=INC founded(A.O.Hume) | 1905=Partition of Bengal(Curzon) | 1906=Muslim League founded(Dhaka) | 1919=Jallianwala Bagh(Gen.Dyer)+Rowlatt Act | 1920=Non-Cooperation Movement(Gandhi) | 1922=Chauri Chaura incident(NCM withdrawn) | 1930=Civil Disobedience+Dandi March(Salt Satyagraha) | 1931=Gandhi-Irwin Pact | 1935=Government of India Act | 1942=Quit India Movement('Do or Die',most leaders arrested immediately) | 1943=Bengal Famine(Viceroy Linlithgow) | 1946=Cabinet Mission | 1947=Independence+Partition(Mountbatten,last Viceroy). Key Viceroys: Curzon(Bengal partition), Hardinge(capital shifted to Delhi 1911), Chelmsford(Rowlatt Act,Jallianwala), Irwin(Dandi March,Gandhi-Irwin Pact), Linlithgow(WWII,Quit India,Bengal Famine), Wavell(Shimla Conf,Cabinet Mission), Mountbatten(last Viceroy,Partition,first Governor-General of independent India). ELIMINATION TRICK: questions often swap the VICEROY for an adjacent-era event — always anchor by decade (1905-10=Curzon/Minto, 1916-21=Chelmsford, 1926-31=Irwin, 1936-43=Linlithgow, 1943-47=Wavell then Mountbatten).", trapcat: "History", level: "L2 Application" },
    { q: "Which Article of the Indian Constitution empowers the President to issue Ordinances when Parliament is not in session?", options: ["Article 124", "Article 352", "Article 123", "Article 143"], answer: 2, explanation: "Article 123 empowers the President to promulgate Ordinances when Parliament is not in session; such an Ordinance must be approved by Parliament within 6 weeks of reassembly or it lapses. Article 124 establishes the Supreme Court (unrelated to ordinances); Article 352 deals with National Emergency; Article 143 gives the President power to seek the Supreme Court's advisory opinion.", rule: "Article 123=President's Ordinance power (Art 213 is the equivalent for a Governor at the state level). || FULL BRUSH-UP — Key Articles cheat sheet: Art 14=Equality before law | Art 19=6 Freedoms | Art 21=Right to Life & Personal Liberty | Art 21A=Right to Education(86th Amdt) | Art 32=Right to Constitutional Remedies('heart and soul'-Ambedkar) | Art 352=National Emergency | Art 356=President's Rule(State Emergency) | Art 360=Financial Emergency(never used) | Art 368=Amendment procedure | Art 108=Joint sitting(presided by Lok Sabha Speaker) | Art 124=Supreme Court | Art 280=Finance Commission | Art 324=Election Commission. Fundamental Rights(6, after 44th Amdt removed Right to Property): Equality(14-18),Freedom(19-22),Against Exploitation(23-24),Freedom of Religion(25-28),Cultural & Educational(29-30),Constitutional Remedies(32). DPSP vs FR trick: Fundamental Rights=justiciable(enforceable in court); DPSP(Part IV)=non-justiciable(directive only). Money Bill: only introduced in Lok Sabha; Rajya Sabha can only RECOMMEND changes, cannot reject/amend. ELIMINATION TRICK: an option claiming Rajya Sabha has 'equal power' specifically on Money Bills or on no-confidence motions is always false — these are the two areas of genuine Lok Sabha supremacy.", trapcat: "Polity", level: "L2 Application" },
    { q: "The concept of 'Judicial Review' in the Indian Constitution means:", options: ["The power of courts to examine and invalidate laws or executive actions that violate the Constitution", "The President's power to review and veto any law passed by Parliament", "The power of Parliament to review and overrule any Supreme Court judgment", "The power of the Election Commission to review electoral rolls periodically"], answer: 0, explanation: "Judicial Review is the judiciary's power (mainly via Articles 13, 32, 226) to strike down any law or executive action inconsistent with the Constitution. Parliament cannot simply 'overrule' a Supreme Court judgment by review (it may amend the Constitution instead, subject to the Basic Structure doctrine); the President's veto powers over bills are separate and don't involve 'judicial review'; electoral roll revision is the Election Commission's administrative function, not judicial review.", rule: "Judicial Review = courts striking down unconstitutional laws/actions — rooted in Article 13 (laws inconsistent with Fundamental Rights are void). || FULL BRUSH-UP — Key Articles cheat sheet: Art 14=Equality before law | Art 19=6 Freedoms | Art 21=Right to Life & Personal Liberty | Art 21A=Right to Education(86th Amdt) | Art 32=Right to Constitutional Remedies('heart and soul'-Ambedkar) | Art 352=National Emergency | Art 356=President's Rule(State Emergency) | Art 360=Financial Emergency(never used) | Art 368=Amendment procedure | Art 108=Joint sitting(presided by Lok Sabha Speaker) | Art 124=Supreme Court | Art 280=Finance Commission | Art 324=Election Commission. Fundamental Rights(6, after 44th Amdt removed Right to Property): Equality(14-18),Freedom(19-22),Against Exploitation(23-24),Freedom of Religion(25-28),Cultural & Educational(29-30),Constitutional Remedies(32). DPSP vs FR trick: Fundamental Rights=justiciable(enforceable in court); DPSP(Part IV)=non-justiciable(directive only). Money Bill: only introduced in Lok Sabha; Rajya Sabha can only RECOMMEND changes, cannot reject/amend. ELIMINATION TRICK: an option claiming Rajya Sabha has 'equal power' specifically on Money Bills or on no-confidence motions is always false — these are the two areas of genuine Lok Sabha supremacy.", trapcat: "Polity", level: "L2 Application" },
    { q: "Consider the following statements regarding the Finance Commission of India: 1. It is a constitutional body under Article 280. 2. It is constituted by the President every 5 years. 3. It recommends the distribution of tax revenues between the Union and the States. Which of the above is/are correct?", options: ["2 and 3 only", "1 and 2 only", "1 only", "1, 2 and 3"], answer: 3, explanation: "All three statements are correct: the Finance Commission (Art 280) is constituted every 5 years by the President and recommends Union-State tax revenue sharing. This is another all-true statement set, reinforcing that SSC doesn't always hide a false statement among three.", rule: "Finance Commission = Art 280, every 5 years, recommends tax devolution between Centre and States (distinct from the NITI Aayog, which has no constitutional status and no such revenue-sharing role). || FULL BRUSH-UP — Key Articles cheat sheet: Art 14=Equality before law | Art 19=6 Freedoms | Art 21=Right to Life & Personal Liberty | Art 21A=Right to Education(86th Amdt) | Art 32=Right to Constitutional Remedies('heart and soul'-Ambedkar) | Art 352=National Emergency | Art 356=President's Rule(State Emergency) | Art 360=Financial Emergency(never used) | Art 368=Amendment procedure | Art 108=Joint sitting(presided by Lok Sabha Speaker) | Art 124=Supreme Court | Art 280=Finance Commission | Art 324=Election Commission. Fundamental Rights(6, after 44th Amdt removed Right to Property): Equality(14-18),Freedom(19-22),Against Exploitation(23-24),Freedom of Religion(25-28),Cultural & Educational(29-30),Constitutional Remedies(32). DPSP vs FR trick: Fundamental Rights=justiciable(enforceable in court); DPSP(Part IV)=non-justiciable(directive only). Money Bill: only introduced in Lok Sabha; Rajya Sabha can only RECOMMEND changes, cannot reject/amend. ELIMINATION TRICK: an option claiming Rajya Sabha has 'equal power' specifically on Money Bills or on no-confidence motions is always false — these are the two areas of genuine Lok Sabha supremacy.", trapcat: "Polity", level: "L2 Application" },
    { q: "The Tropic of Cancer passes through how many Indian states?", options: ["8 states", "6 states", "10 states", "5 states"], answer: 0, explanation: "The Tropic of Cancer passes through 8 Indian states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram. 6 and 5 undercount the list; 10 overcounts it — a frequently tested exact-count GK fact that SSC likes to verify with slight numeric variations.", rule: "MNEMONIC for the 8 states (west to east): 'Gujarat Rajasthan MP Chhattisgarh Jharkhand WestBengal Tripura Mizoram' - GRMCJWTM, roughly west-to-east order across India. || FULL BRUSH-UP — River origins: Ganga=Gangotri glacier(Uttarakhand) | Yamuna=Yamunotri glacier | Narmada=Amarkantak plateau(MP) | Godavari=Trimbakeshwar(Maharashtra,'Vridha Ganga') | Krishna=Mahabaleshwar(Maharashtra) | Kaveri=Talakaveri(Karnataka) | Indus=Tibet(near Mansarovar) | Brahmaputra=Tibet(as Yarlung Tsangpo), enters India in Arunachal Pradesh. Physical superlatives: Highest peak in India=Kangchenjunga(Sikkim,since K2 is in PoK); Largest state(area)=Rajasthan; Largest state(population)=Uttar Pradesh; Smallest state(area)=Goa; Largest coastline=Gujarat; Largest river island=Majuli(Assam,Brahmaputra); Largest mangrove forest=Sundarbans(West Bengal, shared with Bangladesh); Largest salt lake=Sambhar(Rajasthan). Mountain passes: Nathu La & Jelep La(Sikkim-Tibet), Rohtang Pass(Himachal), Zoji La(Kashmir-Ladakh), Shipki La(Himachal-Tibet),Bomdi La(Arunachal). ELIMINATION TRICK: an option swapping a river's origin with a NEARBY peak/plateau of the same region is the most common trap (e.g. Narmada from Amarkantak vs a Vindhya/Satpura mix-up).", trapcat: "Geography", level: "L2 Application" },
    { q: "Which Indian state has the longest coastline?", options: ["Gujarat", "Maharashtra", "Andhra Pradesh", "Tamil Nadu"], answer: 0, explanation: "Gujarat has India's longest coastline among states (approx. 1,600+ km), due to the Kathiawar and Kutch peninsulas. Andhra Pradesh has the second-longest state coastline; Tamil Nadu and Maharashtra have shorter coastlines than both — this ranking is a common 'longest vs second-longest' SSC trap.", rule: "Longest coastline (state)=Gujarat; 2nd longest=Andhra Pradesh; by Union Territory, Andaman & Nicobar's combined coastline is also notable but that's a UT, not a state. || FULL BRUSH-UP — River origins: Ganga=Gangotri glacier(Uttarakhand) | Yamuna=Yamunotri glacier | Narmada=Amarkantak plateau(MP) | Godavari=Trimbakeshwar(Maharashtra,'Vridha Ganga') | Krishna=Mahabaleshwar(Maharashtra) | Kaveri=Talakaveri(Karnataka) | Indus=Tibet(near Mansarovar) | Brahmaputra=Tibet(as Yarlung Tsangpo), enters India in Arunachal Pradesh. Physical superlatives: Highest peak in India=Kangchenjunga(Sikkim,since K2 is in PoK); Largest state(area)=Rajasthan; Largest state(population)=Uttar Pradesh; Smallest state(area)=Goa; Largest coastline=Gujarat; Largest river island=Majuli(Assam,Brahmaputra); Largest mangrove forest=Sundarbans(West Bengal, shared with Bangladesh); Largest salt lake=Sambhar(Rajasthan). Mountain passes: Nathu La & Jelep La(Sikkim-Tibet), Rohtang Pass(Himachal), Zoji La(Kashmir-Ladakh), Shipki La(Himachal-Tibet),Bomdi La(Arunachal). ELIMINATION TRICK: an option swapping a river's origin with a NEARBY peak/plateau of the same region is the most common trap (e.g. Narmada from Amarkantak vs a Vindhya/Satpura mix-up).", trapcat: "Geography", level: "L2 Application" },
    { q: "The Western Ghats, a UNESCO World Heritage Site and biodiversity hotspot, run parallel to which coast of India?", options: ["They run through central India, not along any coast", "The eastern coast (Odisha to Tamil Nadu)", "They form India's northern border with Tibet", "The western coast (from Gujarat/Maharashtra border down to Kerala/Tamil Nadu)"], answer: 3, explanation: "The Western Ghats run roughly parallel to India's western coastline, from south of the Tapi river down to Kanyakumari, covering Maharashtra, Goa, Karnataka, Kerala, and Tamil Nadu. The Eastern Ghats run along the EASTERN coast and are discontinuous (unlike the more continuous Western Ghats) — a common east/west swap trap; they are a coastal mountain range, not central or northern.", rule: "Western Ghats=continuous range along the west coast (older, taller, wetter); Eastern Ghats=discontinuous range along the east coast (older in geological age but lower, broken by rivers like Godavari/Krishna/Kaveri deltas). || FULL BRUSH-UP — River origins: Ganga=Gangotri glacier(Uttarakhand) | Yamuna=Yamunotri glacier | Narmada=Amarkantak plateau(MP) | Godavari=Trimbakeshwar(Maharashtra,'Vridha Ganga') | Krishna=Mahabaleshwar(Maharashtra) | Kaveri=Talakaveri(Karnataka) | Indus=Tibet(near Mansarovar) | Brahmaputra=Tibet(as Yarlung Tsangpo), enters India in Arunachal Pradesh. Physical superlatives: Highest peak in India=Kangchenjunga(Sikkim,since K2 is in PoK); Largest state(area)=Rajasthan; Largest state(population)=Uttar Pradesh; Smallest state(area)=Goa; Largest coastline=Gujarat; Largest river island=Majuli(Assam,Brahmaputra); Largest mangrove forest=Sundarbans(West Bengal, shared with Bangladesh); Largest salt lake=Sambhar(Rajasthan). Mountain passes: Nathu La & Jelep La(Sikkim-Tibet), Rohtang Pass(Himachal), Zoji La(Kashmir-Ladakh), Shipki La(Himachal-Tibet),Bomdi La(Arunachal). ELIMINATION TRICK: an option swapping a river's origin with a NEARBY peak/plateau of the same region is the most common trap (e.g. Narmada from Amarkantak vs a Vindhya/Satpura mix-up).", trapcat: "Geography", level: "L2 Application" },
    { q: "Which of the following is NOT a feature of the Monetary Policy Committee (MPC) of India?", options: ["It is headed by the RBI Governor", "It has 6 members, 3 from RBI and 3 external appointees", "The MPC decides the Union Government's annual fiscal deficit target", "It primarily decides the repo rate to control inflation"], answer: 2, explanation: "Fiscal deficit targets are set by the Union Government/Finance Ministry (fiscal policy), NOT the MPC — the MPC's role is strictly monetary policy, chiefly setting the repo rate. The other three statements are all TRUE features of the MPC: it has 6 members (3 RBI + 3 external), is chaired by the RBI Governor, and its main function is repo rate decisions to target inflation (currently 4% +/-2%).", rule: "MPC=monetary policy(repo rate,inflation target) by RBI; fiscal deficit/taxation/spending=Union Government's fiscal policy — never mix the two institutions' roles. || FULL BRUSH-UP — Five Year Plans: 1951-56=1st(Harrod-Domar model,agriculture) | 1956-61=2nd(Mahalanobis model,heavy industry) | 1966-69='Plan Holiday'(annual plans, after 3rd Plan failure) | 1978-80='Rolling Plan'(Janata govt, different from Plan Holiday - don't confuse the two) | 1980-2017=Plans resumed till 12th Plan(2012-17), then replaced by NITI Aayog's 15-year vision from 2017. RBI nationalised in 1949(was PRIVATE 1935-1949 - a common trap). Key terms: Inflation=general price rise | Disinflation=inflation RATE slowing(prices still rising, just slower) | Deflation=prices actually FALLING | Stagflation=high inflation + stagnant growth together. Fiscal Policy=Government(taxation/spending) | Monetary Policy=RBI(repo rate/CRR/SLR). RBI tools: Repo Rate(RBI lends to banks), Reverse Repo(banks lend to RBI), CRR(cash reserve with RBI), SLR(liquid assets banks must hold). GDP=total output within India's borders; GNP=GDP+net income from abroad. ELIMINATION TRICK: 'Disinflation' vs 'Deflation' is SSC's favourite swap — disinflation still has POSITIVE inflation, just less of it.", trapcat: "Economy", level: "L3 Trap" },
    { q: "'Disguised Unemployment', commonly discussed in the context of Indian agriculture, refers to:", options: ["A complete absence of jobs in a sector", "A situation where more people are employed in an activity than actually needed, so removing some would not reduce output", "Unemployment that is officially hidden or unreported by the government", "Unemployment caused by seasonal factors only, such as during the off-harvest season"], answer: 1, explanation: "Disguised unemployment means apparent employment masks underutilized labour — e.g., 5 people doing a 2-people farming job; removing the extra 3 would not reduce total output, since their marginal productivity is near zero. Complete job absence describes open unemployment, a different category; seasonal unemployment is a distinct type tied to harvest cycles, not disguised employment; disguised unemployment isn't about data reporting/hiding, but about actual redundant labour.", rule: "Disguised unemployment = redundant labour with near-zero marginal product, classic example: Indian agriculture's overcrowded small landholdings. || FULL BRUSH-UP — Five Year Plans: 1951-56=1st(Harrod-Domar model,agriculture) | 1956-61=2nd(Mahalanobis model,heavy industry) | 1966-69='Plan Holiday'(annual plans, after 3rd Plan failure) | 1978-80='Rolling Plan'(Janata govt, different from Plan Holiday - don't confuse the two) | 1980-2017=Plans resumed till 12th Plan(2012-17), then replaced by NITI Aayog's 15-year vision from 2017. RBI nationalised in 1949(was PRIVATE 1935-1949 - a common trap). Key terms: Inflation=general price rise | Disinflation=inflation RATE slowing(prices still rising, just slower) | Deflation=prices actually FALLING | Stagflation=high inflation + stagnant growth together. Fiscal Policy=Government(taxation/spending) | Monetary Policy=RBI(repo rate/CRR/SLR). RBI tools: Repo Rate(RBI lends to banks), Reverse Repo(banks lend to RBI), CRR(cash reserve with RBI), SLR(liquid assets banks must hold). GDP=total output within India's borders; GNP=GDP+net income from abroad. ELIMINATION TRICK: 'Disinflation' vs 'Deflation' is SSC's favourite swap — disinflation still has POSITIVE inflation, just less of it.", trapcat: "Economy", level: "L2 Application" },
    { q: "Consider the following statements about India's Green Revolution (1960s): 1. It was primarily led by the introduction of High Yielding Variety (HYV) seeds of wheat and rice. 2. Punjab, Haryana, and Western Uttar Pradesh were its major beneficiary regions. 3. It led to a uniformly balanced agricultural growth across all crops and all regions of India. Which of the above is/are correct?", options: ["1, 2 and 3", "1 and 2 only", "2 and 3 only", "1 only"], answer: 1, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Green Revolution's benefits were highly UNEVEN, concentrated in wheat/rice and in specific irrigated regions (Punjab, Haryana, W.UP), largely bypassing pulses, oilseeds, and rain-fed/eastern regions. A common exaggeration trap — the Green Revolution is often mistakenly described as universally beneficial, when in reality its regional and crop-wise concentration is one of its most frequently tested limitations.", rule: "Green Revolution = HYV seeds(wheat/rice) + Punjab/Haryana/W.UP concentration + UNEVEN spread(not balanced) — the 'balanced for all crops/regions' claim is always false in SSC statements.", trapcat: "Economy/History", level: "L3 Trap" },
    { q: "Which vitamin is synthesized by the human body itself upon exposure to sunlight?", options: ["Vitamin B12", "Vitamin D", "Vitamin A", "Vitamin C"], answer: 1, explanation: "Vitamin D is synthesized in human skin when exposed to UV-B sunlight, converting a cholesterol derivative into active Vitamin D (cholecalciferol). Vitamin C must be obtained from diet (citrus fruits etc.), the human body cannot synthesize it; Vitamin B12 is obtained mainly from animal products, not sunlight; Vitamin A comes from diet (dairy, liver, orange/yellow vegetables via beta-carotene).", rule: "Vitamin D = 'sunshine vitamin', the only vitamin the human body can self-synthesize via sunlight exposure. || FULL BRUSH-UP — common Biology/Chemistry/Physics facts: Vitamin deficiency diseases: A=Night blindness,B1=Beri-beri,C=Scurvy,D=Rickets,B12=Anemia,K=Blood clotting issues. Vitamin C & B-complex are water-soluble(not stored, need daily intake); A,D,E,K are fat-soluble(stored in body). SI units: Force=Newton,Energy/Work=Joule,Power=Watt,Pressure=Pascal,Frequency=Hertz,Current=Ampere. pH scale: <7=acidic,7=neutral,>7=basic; pure water=7. Human body: largest organ=Skin, largest gland=Liver, smallest bone=Stapes(ear), longest bone=Femur, normal body temp=37°C(98.6°F), normal BP=120/80 mmHg, RBC life=120 days, WBC fights infection. ELIMINATION TRICK: fat-soluble vs water-soluble vitamin mix-ups are extremely common — memorize 'ADEK are fat-soluble' as one block, everything else (B-complex, C) is water-soluble.", trapcat: "Science", level: "L1 Direct" },
    { q: "Which part of the human brain is primarily responsible for controlling balance and coordination of voluntary movements?", options: ["Cerebellum", "Hypothalamus", "Cerebrum", "Medulla oblongata"], answer: 0, explanation: "The Cerebellum ('little brain') controls balance, posture, and fine coordination of voluntary muscle movements. Cerebrum is the largest part, responsible for higher functions like thought, memory, and voluntary action INITIATION (not fine coordination); Medulla oblongata controls involuntary functions (heartbeat, breathing); Hypothalamus regulates body temperature, hunger, and hormones.", rule: "Cerebellum=balance/coordination; Cerebrum=thinking/voluntary action; Medulla=involuntary life-functions; Hypothalamus=homeostasis(temperature/hunger/hormones) — four distinct brain-region roles frequently tested together. || FULL BRUSH-UP — common Biology/Chemistry/Physics facts: Vitamin deficiency diseases: A=Night blindness,B1=Beri-beri,C=Scurvy,D=Rickets,B12=Anemia,K=Blood clotting issues. Vitamin C & B-complex are water-soluble(not stored, need daily intake); A,D,E,K are fat-soluble(stored in body). SI units: Force=Newton,Energy/Work=Joule,Power=Watt,Pressure=Pascal,Frequency=Hertz,Current=Ampere. pH scale: <7=acidic,7=neutral,>7=basic; pure water=7. Human body: largest organ=Skin, largest gland=Liver, smallest bone=Stapes(ear), longest bone=Femur, normal body temp=37°C(98.6°F), normal BP=120/80 mmHg, RBC life=120 days, WBC fights infection. ELIMINATION TRICK: fat-soluble vs water-soluble vitamin mix-ups are extremely common — memorize 'ADEK are fat-soluble' as one block, everything else (B-complex, C) is water-soluble.", trapcat: "Science", level: "L2 Application" },
    { q: "Which gas is most responsible for the greenhouse effect and is the primary target of global carbon emission reduction efforts?", options: ["Hydrogen (H2)", "Oxygen (O2)", "Nitrogen (N2)", "Carbon dioxide (CO2)"], answer: 3, explanation: "Carbon dioxide (CO2), released mainly from burning fossil fuels, is the primary greenhouse gas targeted in global climate agreements (e.g., Paris Agreement), though methane and other gases also contribute. Oxygen and Nitrogen make up ~99% of the atmosphere but are NOT significant greenhouse gases; Hydrogen is not a naturally dominant atmospheric gas nor a major greenhouse contributor.", rule: "Primary greenhouse gases (in order of typical contribution focus): CO2 > Methane(CH4) > Nitrous oxide(N2O) > CFCs — CO2 remains the headline target in SSC GK questions on climate. || FULL BRUSH-UP — common Biology/Chemistry/Physics facts: Vitamin deficiency diseases: A=Night blindness,B1=Beri-beri,C=Scurvy,D=Rickets,B12=Anemia,K=Blood clotting issues. Vitamin C & B-complex are water-soluble(not stored, need daily intake); A,D,E,K are fat-soluble(stored in body). SI units: Force=Newton,Energy/Work=Joule,Power=Watt,Pressure=Pascal,Frequency=Hertz,Current=Ampere. pH scale: <7=acidic,7=neutral,>7=basic; pure water=7. Human body: largest organ=Skin, largest gland=Liver, smallest bone=Stapes(ear), longest bone=Femur, normal body temp=37°C(98.6°F), normal BP=120/80 mmHg, RBC life=120 days, WBC fights infection. ELIMINATION TRICK: fat-soluble vs water-soluble vitamin mix-ups are extremely common — memorize 'ADEK are fat-soluble' as one block, everything else (B-complex, C) is water-soluble.", trapcat: "Science", level: "L1 Direct" },
    { q: "The 'Chipko Movement' and later the 'Narmada Bachao Andolan' are both examples of which broader category of movement in India?", options: ["Linguistic reorganisation movements", "Environmental/ecological conservation movements", "Caste-based reservation movements", "Trade union/labour rights movements"], answer: 1, explanation: "Both Chipko (forest conservation, Uttarakhand, 1973) and Narmada Bachao Andolan (anti-dam displacement/ecological movement, led by Medha Patkar) are environmental movements opposing resource exploitation that harms local ecology and livelihoods. Neither movement is about labour/trade unions, caste reservations, or state reorganisation along linguistic lines (like the 1950s-60s linguistic states movements) — those are entirely separate categories of Indian social movements.", rule: "Chipko(1973,Bahuguna/Bhatt) + Narmada Bachao Andolan(1980s-90s,Medha Patkar) = environmental movements; keep this category distinct from labour (e.g. Bombay textile strikes) or caste-based movements.", trapcat: "History/Economy", level: "L2 Application" },
    { q: "Who was the chairman of the Drafting Committee of the Indian Constitution?", options: ["Dr. Rajendra Prasad", "Sardar Vallabhbhai Patel", "Dr. B.R. Ambedkar", "Jawaharlal Nehru"], answer: 2, explanation: "Dr. B.R. Ambedkar chaired the Drafting Committee (7 members) of the Constituent Assembly, hence often called the 'Father of the Indian Constitution'. Dr. Rajendra Prasad was the PRESIDENT of the Constituent Assembly as a whole (a broader, separate role) and later independent India's first President; Nehru chaired other committees (like the Union Powers Committee) and moved the Objectives Resolution; Patel chaired the States/Minorities-related committees — none chaired the DRAFTING Committee specifically.", rule: "Constituent Assembly President=Rajendra Prasad; Drafting Committee Chairman=Ambedkar — a very frequently confused pair of 'who chaired what'.", trapcat: "Polity/History", level: "L3 Trap" },
    { q: "The headquarters of the United Nations Educational, Scientific and Cultural Organization (UNESCO) is located in:", options: ["Geneva, Switzerland", "Vienna, Austria", "Paris, France", "New York, USA"], answer: 2, explanation: "UNESCO is headquartered in Paris, France, since its founding in 1945/46. Geneva hosts WHO and the UN's European office; New York hosts the UN's main headquarters and UNICEF; Vienna hosts the IAEA and UNODC — each major international body has a distinct, frequently tested headquarters city.", rule: "UNESCO=Paris; WHO=Geneva; UNICEF/UN HQ=New York; IAEA=Vienna; ILO=Geneva — build ONE table of UN body headquarters, don't learn them in isolation.", trapcat: "Geography/Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Mount Everest is the highest peak in the world, located in Nepal. 2. K2 (Mount Godwin-Austen), the second-highest peak in the world, is located in India. 3. Kangchenjunga, the third-highest peak in the world, is located in India (Sikkim). Which of the above is/are correct?", options: ["1, 2 and 3", "1 and 3 only", "1 only", "2 and 3 only"], answer: 1, explanation: "Statements 1 and 3 are correct. Statement 2 is false — K2 is located in Pakistan-occupied Kashmir (Gilgit-Baltistan region), a territory India claims but does not administer; it is not located within India's administered territory. This statement-set trap exploits a politically sensitive geography fact — SSC expects the factual/administrative reality (K2 in PoK, administered by Pakistan), not India's territorial claim, when asking where a peak 'is located'.", rule: "Kangchenjunga(Sikkim,India)=India's highest peak and world's 3rd highest; Everest(Nepal)=world's highest; K2(PoK)=world's 2nd highest but NOT in India-administered territory. || FULL BRUSH-UP — River origins: Ganga=Gangotri glacier(Uttarakhand) | Yamuna=Yamunotri glacier | Narmada=Amarkantak plateau(MP) | Godavari=Trimbakeshwar(Maharashtra,'Vridha Ganga') | Krishna=Mahabaleshwar(Maharashtra) | Kaveri=Talakaveri(Karnataka) | Indus=Tibet(near Mansarovar) | Brahmaputra=Tibet(as Yarlung Tsangpo), enters India in Arunachal Pradesh. Physical superlatives: Highest peak in India=Kangchenjunga(Sikkim,since K2 is in PoK); Largest state(area)=Rajasthan; Largest state(population)=Uttar Pradesh; Smallest state(area)=Goa; Largest coastline=Gujarat; Largest river island=Majuli(Assam,Brahmaputra); Largest mangrove forest=Sundarbans(West Bengal, shared with Bangladesh); Largest salt lake=Sambhar(Rajasthan). Mountain passes: Nathu La & Jelep La(Sikkim-Tibet), Rohtang Pass(Himachal), Zoji La(Kashmir-Ladakh), Shipki La(Himachal-Tibet),Bomdi La(Arunachal). ELIMINATION TRICK: an option swapping a river's origin with a NEARBY peak/plateau of the same region is the most common trap (e.g. Narmada from Amarkantak vs a Vindhya/Satpura mix-up).", trapcat: "Geography", level: "L3 Trap" },
    { q: "The 'Right to Information Act' (RTI), empowering citizens to request information from public authorities, was enacted in which year?", options: ["1995", "2005", "2010", "2000"], answer: 1, explanation: "The RTI Act was passed by Parliament in 2005, coming into full effect on 12 October 2005. 2000, 2010, and 1995 are all incorrect years frequently used as distractors around major Indian legislative milestones; always anchor the RTI Act specifically to 2005.", rule: "RTI Act=2005; compare with other rights-based laws: Right to Education Act=2009(Art 21A added 2002 via 86th Amdt), Right to Food/NFSA=2013 — build a mini-timeline of 'Right to X' Acts. || FULL BRUSH-UP — Key Articles cheat sheet: Art 14=Equality before law | Art 19=6 Freedoms | Art 21=Right to Life & Personal Liberty | Art 21A=Right to Education(86th Amdt) | Art 32=Right to Constitutional Remedies('heart and soul'-Ambedkar) | Art 352=National Emergency | Art 356=President's Rule(State Emergency) | Art 360=Financial Emergency(never used) | Art 368=Amendment procedure | Art 108=Joint sitting(presided by Lok Sabha Speaker) | Art 124=Supreme Court | Art 280=Finance Commission | Art 324=Election Commission. Fundamental Rights(6, after 44th Amdt removed Right to Property): Equality(14-18),Freedom(19-22),Against Exploitation(23-24),Freedom of Religion(25-28),Cultural & Educational(29-30),Constitutional Remedies(32). DPSP vs FR trick: Fundamental Rights=justiciable(enforceable in court); DPSP(Part IV)=non-justiciable(directive only). Money Bill: only introduced in Lok Sabha; Rajya Sabha can only RECOMMEND changes, cannot reject/amend. ELIMINATION TRICK: an option claiming Rajya Sabha has 'equal power' specifically on Money Bills or on no-confidence motions is always false — these are the two areas of genuine Lok Sabha supremacy.", trapcat: "Polity", level: "L1 Direct" },
    { q: "Which blood group is known as the 'universal donor'?", options: ["A positive (A+)", "O negative (O-)", "B negative (B-)", "AB positive (AB+)"], answer: 1, explanation: "O negative blood lacks A, B, and Rh antigens, so it can typically be given to patients of any blood group in emergencies, making it the 'universal donor'. AB positive is actually the 'universal RECIPIENT' (can receive from any group) — the exact reverse concept, a very common swap trap; A positive and B negative are ordinary blood types without universal donor/recipient status.", rule: "O negative=universal DONOR (gives to all); AB positive=universal RECIPIENT (receives from all) — memorize this as one reciprocal pair, never confuse donor with recipient. || FULL BRUSH-UP — common Biology/Chemistry/Physics facts: Vitamin deficiency diseases: A=Night blindness,B1=Beri-beri,C=Scurvy,D=Rickets,B12=Anemia,K=Blood clotting issues. Vitamin C & B-complex are water-soluble(not stored, need daily intake); A,D,E,K are fat-soluble(stored in body). SI units: Force=Newton,Energy/Work=Joule,Power=Watt,Pressure=Pascal,Frequency=Hertz,Current=Ampere. pH scale: <7=acidic,7=neutral,>7=basic; pure water=7. Human body: largest organ=Skin, largest gland=Liver, smallest bone=Stapes(ear), longest bone=Femur, normal body temp=37°C(98.6°F), normal BP=120/80 mmHg, RBC life=120 days, WBC fights infection. ELIMINATION TRICK: fat-soluble vs water-soluble vitamin mix-ups are extremely common — memorize 'ADEK are fat-soluble' as one block, everything else (B-complex, C) is water-soluble.", trapcat: "Science", level: "L2 Application" },
    { q: "The Bhopal Gas Tragedy (1984), one of the world's worst industrial disasters, involved the leak of which toxic gas?", options: ["Carbon monoxide", "Chlorine gas", "Sulphur dioxide", "Methyl Isocyanate (MIC)"], answer: 3, explanation: "The 1984 Bhopal Gas Tragedy involved a leak of Methyl Isocyanate (MIC) gas from the Union Carbide pesticide plant, killing thousands. Chlorine gas, carbon monoxide, and sulphur dioxide are all real industrial/toxic gases but were NOT the gas involved in the Bhopal tragedy specifically — a common 'plausible toxic gas' distractor pattern.", rule: "Bhopal Gas Tragedy (1984) = Methyl Isocyanate (MIC), Union Carbide plant — a standalone, frequently tested fact-triplet (year+gas+company).", trapcat: "Science/History", level: "L2 Application" },
    { q: "Who gave India its National Anthem 'Jana Gana Mana', and in which year was it first sung publicly?", options: ["Rabindranath Tagore, first sung in 1911 (at the Calcutta session of the INC)", "Sarojini Naidu, first sung in 1930", "Bankim Chandra Chattopadhyay, first sung in 1896", "Rabindranath Tagore, first sung in 1947"], answer: 0, explanation: "Rabindranath Tagore composed 'Jana Gana Mana', first publicly sung in 1911 at the Calcutta session of the Indian National Congress; it was adopted as the National Anthem in 1950. Bankim Chandra Chattopadhyay wrote 'Vande Mataram' (the National SONG, a different title, first sung 1896) — a very common Anthem-vs-Song confusion; Tagore's anthem was NOT first sung in 1947 (that's Independence year, a tempting but wrong distractor); Sarojini Naidu had no authorship role here.", rule: "National Anthem='Jana Gana Mana'(Tagore,1911); National Song='Vande Mataram'(Bankim Chandra,1896, from novel Anandamath) — two DIFFERENT titles, authors, and years, extremely frequently tested as a pair.", trapcat: "History/Polity", level: "L3 Trap" },
    { q: "Which Indian Prime Minister launched the 'Make in India' initiative in 2014 to boost domestic manufacturing?", options: ["Atal Bihari Vajpayee", "Manmohan Singh", "P.V. Narasimha Rao", "Narendra Modi"], answer: 3, explanation: "Narendra Modi launched the 'Make in India' initiative in September 2014 to encourage domestic and foreign manufacturing investment. Manmohan Singh's government (2004-14) launched schemes like MGNREGA and the RTI Act, not Make in India; Vajpayee (1998-2004) is associated with the Golden Quadrilateral highway project; Narasimha Rao (1991-96) led the 1991 LPG economic reforms (Liberalization-Privatization-Globalization) — each PM has distinct flagship initiatives frequently tested.", rule: "Match PM to flagship scheme: Narasimha Rao=1991 LPG reforms; Vajpayee=Golden Quadrilateral/Pokhran-II; Manmohan Singh=RTI/MGNREGA/RTE; Modi=Make in India/Swachh Bharat/GST implementation(2017).", trapcat: "Economy/Polity", level: "L2 Application" },
    { q: "The 'Panchayati Raj' three-tier system of local self-government in rural India was given constitutional status by which amendment?", options: ["61st Amendment Act, 1989", "42nd Amendment Act, 1976", "73rd Amendment Act, 1992", "74th Amendment Act, 1992"], answer: 2, explanation: "The 73rd Amendment Act (1992) gave constitutional status to Panchayati Raj Institutions (rural local self-government), adding Part IX and the 11th Schedule. The 74th Amendment (1992, passed alongside the 73rd) covers URBAN local bodies (Municipalities) instead, via Part IXA and the 12th Schedule — a very commonly confused pair since both passed the same year; the 42nd Amendment (1976) is the 'Mini-Constitution' amendment (added Fundamental Duties, 'Socialist Secular' to Preamble); the 61st Amendment (1989) lowered the voting age to 18.", rule: "73rd Amendment=Panchayats(RURAL,Part IX,11th Schedule); 74th Amendment=Municipalities(URBAN,Part IXA,12th Schedule) — both from 1992, memorize 73=rural/74=urban as a fixed pair. || FULL BRUSH-UP — Key Articles cheat sheet: Art 14=Equality before law | Art 19=6 Freedoms | Art 21=Right to Life & Personal Liberty | Art 21A=Right to Education(86th Amdt) | Art 32=Right to Constitutional Remedies('heart and soul'-Ambedkar) | Art 352=National Emergency | Art 356=President's Rule(State Emergency) | Art 360=Financial Emergency(never used) | Art 368=Amendment procedure | Art 108=Joint sitting(presided by Lok Sabha Speaker) | Art 124=Supreme Court | Art 280=Finance Commission | Art 324=Election Commission. Fundamental Rights(6, after 44th Amdt removed Right to Property): Equality(14-18),Freedom(19-22),Against Exploitation(23-24),Freedom of Religion(25-28),Cultural & Educational(29-30),Constitutional Remedies(32). DPSP vs FR trick: Fundamental Rights=justiciable(enforceable in court); DPSP(Part IV)=non-justiciable(directive only). Money Bill: only introduced in Lok Sabha; Rajya Sabha can only RECOMMEND changes, cannot reject/amend. ELIMINATION TRICK: an option claiming Rajya Sabha has 'equal power' specifically on Money Bills or on no-confidence motions is always false — these are the two areas of genuine Lok Sabha supremacy.", trapcat: "Polity", level: "L3 Trap" }
  ]
},
{
  id: "oct6_m2", label: "Extreme Maths Test 2 (Full Syllabus Brush-up)", timeLimitMin: 30,
  questions: [
    { q: "Find the rate of interest per annum if Rs. 5,000 amounts to a Compound Interest of Rs. 1,050 in 2 years (compounded annually).", options: ["12%", "15%", "10%", "8%"], answer: 2, explanation: "CI formula: P[(1+r)^2-1]=1050 => (1+r)^2 = 1+1050/5000 = 1.21 => (1+r)=1.1 => r=10%. 12% and 15% would produce a much larger CI than Rs.1050 on this principal; 8% would produce a smaller CI — verify by back-substitution, not just guessing a 'round' rate.", rule: "When CI for 2 years is given, back-solve (1+r)^2 = 1 + CI/P, then take the square root to isolate r — much faster than trial-and-error with answer options. || FULL BRUSH-UP — SI/CI: SI = (P*R*T)/100. CI = P*[(1+R/100)^T - 1]. CI - SI for 2 years = P*(R/100)^2 (shortcut, skip full calculation). CI - SI for 3 years = P*(R/100)^2*[(300+R)/100]. Half-yearly compounding: use R/2 as rate, 2T as time periods. Quarterly: R/4 as rate, 4T as periods. ELIMINATION TRICK: if a problem changes the rate for ONE specific later year/period, apply the new rate only to the ACCUMULATED amount up to that point — never recompute from the original principal with a blended rate.", trapcat: "Compound Interest (reverse)", level: "L2 Application" },
    { q: "A sum amounts to Rs. 9,800 in 2.5 years at 8% p.a. simple interest. Find the principal.", options: ["Rs. 8,500", "Rs. 8,000", "Rs. 7,500", "Rs. 7,800"], answer: 1, explanation: "Amount = P(1 + rt/100) => 9800 = P(1 + 8x2.5/100) = P(1.20) => P = 9800/1.20 = Rs.8,000. Rs.7,500 and Rs.8,500 come from rounding errors in the (1+rt/100) multiplier; Rs.7,800 wrongly treats the amount itself as if it were just principal plus a flat Rs.2000, ignoring the actual rate-time multiplier.", rule: "Always solve Amount=P(1+rt/100) for P by dividing by the FULL multiplier (1+rt/100), not by subtracting a guessed interest amount. || FULL BRUSH-UP — SI/CI: SI = (P*R*T)/100. CI = P*[(1+R/100)^T - 1]. CI - SI for 2 years = P*(R/100)^2 (shortcut, skip full calculation). CI - SI for 3 years = P*(R/100)^2*[(300+R)/100]. Half-yearly compounding: use R/2 as rate, 2T as time periods. Quarterly: R/4 as rate, 4T as periods. ELIMINATION TRICK: if a problem changes the rate for ONE specific later year/period, apply the new rate only to the ACCUMULATED amount up to that point — never recompute from the original principal with a blended rate.", trapcat: "SI vs CI", level: "L2 Application" },
    { q: "A shop offers successive discounts of 10% and 5% on an item marked at Rs. 5,000. Find the final selling price.", options: ["Rs. 4250", "Rs. 4325", "Rs. 4175", "Rs. 4275"], answer: 3, explanation: "Successive discounts multiply: SP = 5000 x 0.90 x 0.95 = Rs.4275. Rs.4250 wrongly ADDS the two discounts (10%+5%=15% flat off) instead of applying them successively — successive discounts are always slightly LESS severe than their simple sum suggests.", rule: "Successive discounts: multiply (1-d1/100)(1-d2/100); never add the discount percentages directly — same logic as successive percentage increases. || FULL BRUSH-UP — Percentage & Profit-Loss: Fraction-to-% table (memorize): 1/2=50%, 1/3=33.33%, 1/4=25%, 1/5=20%, 1/6=16.67%, 1/7=14.28%, 1/8=12.5%, 1/9=11.11%, 1/10=10%, 1/11=9.09%, 1/12=8.33% — instantly convert common fractions without long division. Successive % change: net multiplier=(1+a/100)(1+b/100); NEVER just add/subtract the two percentages. Profit%=((SP-CP)/CP)*100, Loss%=((CP-SP)/CP)*100. Discount is always on Marked Price: SP=MP*(1-discount%/100). Faulty weight dealer: Profit% = [(True weight-False weight)/False weight]*100 (denominator is the ACTUAL/false weight given, not the claimed one). ELIMINATION TRICK: when markup% and discount% are both given, compute via MP and SP step by step — an option that looks like a simple (markup% - discount%) subtraction is almost always the trap.", trapcat: "Percentage (successive change)", level: "L2 Application" },
    { q: "Two articles are each sold for Rs. 990. On the first, a profit of 10% is made; on the second, a loss of 10% is incurred. Find the overall profit or loss percentage on the whole transaction.", options: ["No profit no loss (exactly 0%)", "Loss of 6%", "Loss of 1%", "Profit of 1%"], answer: 2, explanation: "CP(profit article)=990/1.10=Rs.900. CP(loss article)=990/0.90=Rs.1100. Total CP=Rs.2000, Total SP=Rs.1980. Net = 1980-2000=-Rs.20, a LOSS of 20/2000 x100=1%. The tempting '0% net' answer assumes equal % profit and loss cancel out — they do NOT when the SAME selling price (not cost price) is used for both; there is always a net LOSS equal to (common%/10)^2 in such cases.", rule: "SHORTCUT: when two items are sold at the SAME price, one at x% profit and the other at x% loss, there is always a net LOSS of (x/10)^2 percent — here (10/10)^2=1%... [note: this shortcut gives %age of SP-sum basis; always verify via direct CP calculation as shown]. || FULL BRUSH-UP — Percentage & Profit-Loss: Fraction-to-% table (memorize): 1/2=50%, 1/3=33.33%, 1/4=25%, 1/5=20%, 1/6=16.67%, 1/7=14.28%, 1/8=12.5%, 1/9=11.11%, 1/10=10%, 1/11=9.09%, 1/12=8.33% — instantly convert common fractions without long division. Successive % change: net multiplier=(1+a/100)(1+b/100); NEVER just add/subtract the two percentages. Profit%=((SP-CP)/CP)*100, Loss%=((CP-SP)/CP)*100. Discount is always on Marked Price: SP=MP*(1-discount%/100). Faulty weight dealer: Profit% = [(True weight-False weight)/False weight]*100 (denominator is the ACTUAL/false weight given, not the claimed one). ELIMINATION TRICK: when markup% and discount% are both given, compute via MP and SP step by step — an option that looks like a simple (markup% - discount%) subtraction is almost always the trap.", trapcat: "Profit & Loss (multi-step)", level: "L3 Trap" },
    { q: "A can complete a work in 20 days and B in 30 days. A works alone for the first 5 days, after which B joins him and they finish the remaining work together. Find the TOTAL number of days taken to complete the work.", options: ["14 days", "15 days", "17 days", "12 days"], answer: 0, explanation: "A's 5-day work = 5/20 = 1/4. Remaining work = 3/4. Combined rate = 1/20+1/30 = 1/12. Time for remaining = (3/4)/(1/12) = 9 days. Total = 5+9 = 14 days. 15 days is a plausible-looking round number but doesn't satisfy the actual work-fraction equation when checked.", rule: "For 'joined later' problems: compute work ALREADY done in the solo phase, subtract from 1 to get remaining work, then divide by the COMBINED rate for the joint phase — add the two phase-durations at the end. || FULL BRUSH-UP — Time, Work & Pipes: Work rate = 1/(days to finish). Combine rates by ADDING for people/inlet-pipes working together. Outlet/emptying pipes are NEGATIVE rates — subtract, don't add. Efficiency ratio is the INVERSE of the time ratio (if A is twice as efficient as B, A takes HALF the time B takes). 'A and B together do a work B could do alone in X days' type: always set up rate equations from the given condition, don't guess-and-check arbitrary day values. ELIMINATION TRICK: if a solved 'days' value doesn't divide evenly into the LCM used for total work units, recheck your rate setup — most of these problems are designed around clean LCM-based total work values.", trapcat: "Time and Work", level: "L2 Application" },
    { q: "Pipe A can fill a tank in 10 hours and Pipe B in 15 hours. Both pipes are opened together, but after 3 hours, Pipe B is closed. Find the total time taken to fill the tank completely.", options: ["7.0 hours", "8.0 hours", "9.5 hours", "6.0 hours"], answer: 1, explanation: "Combined rate (3 hrs) = 1/10+1/15 = 1/6 per hour. Work done in 3 hrs = 3/6 = 1/2. Remaining = 1/2. Pipe A alone fills remaining 1/2 in (1/2)/(1/10) = 5 hours. Total = 3+5 = 8.0 hours. 6.0 hours assumes both pipes work the entire time (ignoring that B closes after 3 hours), which would undercount the actual total time needed.", rule: "For 'pipe closed partway' problems: find work done during the JOINT phase first, then switch to the remaining pipe's own rate for the leftover work — never apply the combined rate for the full duration. || FULL BRUSH-UP — Time, Work & Pipes: Work rate = 1/(days to finish). Combine rates by ADDING for people/inlet-pipes working together. Outlet/emptying pipes are NEGATIVE rates — subtract, don't add. Efficiency ratio is the INVERSE of the time ratio (if A is twice as efficient as B, A takes HALF the time B takes). 'A and B together do a work B could do alone in X days' type: always set up rate equations from the given condition, don't guess-and-check arbitrary day values. ELIMINATION TRICK: if a solved 'days' value doesn't divide evenly into the LCM used for total work units, recheck your rate setup — most of these problems are designed around clean LCM-based total work values.", trapcat: "Time and Work (pipes)", level: "L2 Application" },
    { q: "Two numbers are in the ratio 4:5. If 10 is added to each number, the new ratio becomes 6:7. Find the two numbers.", options: ["20 and 25", "24 and 29", "16 and 21", "16 and 20"], answer: 0, explanation: "Let numbers = 4x, 5x. (4x+10)/(5x+10) = 6/7 => 7(4x+10) = 6(5x+10) => 28x+70 = 30x+60 => 2x=10 => x=5. Numbers = 20 and 25. 16 and 20 keeps the ORIGINAL 4:5 ratio exactly (16:20=4:5) without applying the '+10 each' condition at all — a trap for those who stop after setting up variables but forget to solve the equation.", rule: "For 'ratio changes after adding/subtracting a constant' problems, always set up (4x+k)/(5x+k)=new ratio and cross-multiply to solve for x — never assume the original ratio's multiple still works. || FULL BRUSH-UP — Ratio, Average & Partnership: To combine two ratios sharing a common term (e.g. A:B and B:C), scale both so the common term (B) matches via LCM, then merge into one combined ratio. Partnership profit-share = Capital * Time-invested for each partner (never capital alone if durations differ). Average of an Arithmetic Progression = (first term + last term)/2. Combined average of two groups of DIFFERENT sizes = weighted average = (n1*a1+n2*a2)/(n1+n2), never the simple average of the two averages unless the group sizes are equal. ELIMINATION TRICK: an option that's just the plain average of two given averages (ignoring group sizes/weights) is the single most common average-question trap.", trapcat: "Ratio & Proportion", level: "L2 Application" },
    { q: "How many litres of a 20% acid solution must be mixed with a 50% acid solution to get 30 litres of a 30% acid mixture?", options: ["15 litres of each solution", "15 litres of the 20% solution", "20 litres of the 20% solution (and 10 litres of the 50% solution)", "10 litres of the 20% solution (and 20 litres of the 50% solution)"], answer: 2, explanation: "By alligation: ratio of 20%-solution to 50%-solution = (50-30):(30-20) = 20:10 = 2:1. Out of 30L total, 20%-solution = 30x2/3=20L, 50%-solution = 30x1/3=10L. Swapping the ratio (giving more of the STRONGER solution when the mixture is closer to the WEAKER one) is the classic alligation direction-error; 15L each would only work if the mean were exactly 35% (the midpoint), not 30%.", rule: "Alligation ratio = (far price - mean)/(mean - near price), and this ratio belongs to the NEARER component first — the mixture being closer to 20% means MORE of the 20% solution is needed, not less. || FULL BRUSH-UP — Mixture & Alligation: Alligation cross-rule: (Quantity of cheaper)/(Quantity of dearer) = (Dearer price - Mean price)/(Mean price - Cheaper price). Replacement formula (withdraw-and-replace repeated n times): Final quantity of original substance = Initial quantity * [(Volume - amount withdrawn each time)/Volume]^n — this is NOT linear subtraction after the first round, since later withdrawals remove an already-diluted mixture. ELIMINATION TRICK: any option from simple repeated subtraction (e.g., V - d - d for n=2 replacements) ignores dilution and is always the trap in a 'replace and repeat' problem.", trapcat: "Mixture & Alligation", level: "L3 Trap" },
    { q: "A car travels from city X to city Y at 40 km/h and returns from Y to X at 60 km/h. Find its average speed for the entire round trip.", options: ["54 km/h", "44 km/h", "50 km/h", "48 km/h"], answer: 3, explanation: "For equal distances at two speeds, average speed = 2xy/(x+y) = 2x40x60/100 = 48 km/h (the harmonic mean), NOT the simple average. 50 km/h is the simple arithmetic average of 40 and 60, which is WRONG whenever the same distance (not same time) is covered at each speed.", rule: "Average speed for EQUAL DISTANCES at two different speeds = 2xy/(x+y) (harmonic mean); only use the simple average (x+y)/2 when the TIME spent at each speed is equal instead. || FULL BRUSH-UP — Time-Speed-Distance: Convert km/h to m/s by multiplying by 5/18 (and m/s to km/h by 18/5). Same direction -> RELATIVE SPEED = difference of speeds. Opposite directions -> RELATIVE SPEED = sum of speeds. Trains crossing: distance to cover = sum of both lengths (if crossing each other) or just one length (crossing a pole). Average speed for equal distances at two different speeds x,y = 2xy/(x+y) (NOT the simple average (x+y)/2). Boats: Downstream speed = boat+stream, Upstream speed = boat-stream; Boat speed = (downstream+upstream)/2, Stream speed = (downstream-upstream)/2. ELIMINATION TRICK: never average two different SPEEDS directly for a round trip — only average when the TIME (not distance) is equal at both speeds; for equal distances, always use the 2xy/(x+y) harmonic-mean formula.", trapcat: "Time-Speed-Distance", level: "L3 Trap" },
    { q: "Car B leaves a point travelling at 60 km/h. Car A leaves the SAME point, in the SAME direction, 30 minutes later, travelling at 80 km/h. How long after Car A starts will it catch up with Car B?", options: ["2 hours", "1 hour", "0.5 hours", "1.5 hours"], answer: 3, explanation: "When A starts, B already has a head start of 60 x 0.5 = 30 km. Relative speed (same direction, so SUBTRACT) = 80-60 = 20 km/h. Time for A to close the 30 km gap = 30/20 = 1.5 hours. 1 hour and 2 hours are round-number guesses that don't satisfy the actual head-start/relative-speed equation; 0.5 hours confuses the head-start TIME itself with the catch-up TIME, which are different quantities.", rule: "'Catches up later' problems: compute the head-start DISTANCE first (using the time gap), then divide by the RELATIVE speed (difference, since same direction) to get the catch-up time from when the second vehicle starts. || FULL BRUSH-UP — Time-Speed-Distance: Convert km/h to m/s by multiplying by 5/18 (and m/s to km/h by 18/5). Same direction -> RELATIVE SPEED = difference of speeds. Opposite directions -> RELATIVE SPEED = sum of speeds. Trains crossing: distance to cover = sum of both lengths (if crossing each other) or just one length (crossing a pole). Average speed for equal distances at two different speeds x,y = 2xy/(x+y) (NOT the simple average (x+y)/2). Boats: Downstream speed = boat+stream, Upstream speed = boat-stream; Boat speed = (downstream+upstream)/2, Stream speed = (downstream-upstream)/2. ELIMINATION TRICK: never average two different SPEEDS directly for a round trip — only average when the TIME (not distance) is equal at both speeds; for equal distances, always use the 2xy/(x+y) harmonic-mean formula.", trapcat: "Time-Speed-Distance", level: "L2 Application" },
    { q: "If a + b + c = 0, find the value of a^3 + b^3 + c^3 in terms of a, b, c.", options: ["a*b*c/3", "3abc", "abc", "0"], answer: 1, explanation: "Identity: if a+b+c=0, then a^3+b^3+c^3 = 3abc (a special case of the general sum-of-cubes identity). 0 is a trap for those who assume cubes of numbers summing to zero also sum to zero (false in general); abc and abc/3 are incorrect coefficient guesses on the right identity structure.", rule: "MEMORIZE as a standalone special identity: a+b+c=0 => a^3+b^3+c^3=3abc — extremely common SSC shortcut question, saves fully expanding the cubic. || FULL IDENTITY BRUSH-UP — Algebra: (a+b)^2=a^2+2ab+b^2 | (a-b)^2=a^2-2ab+b^2 | a^2-b^2=(a+b)(a-b) | (a+b)^3=a^3+b^3+3ab(a+b) | (a-b)^3=a^3-b^3-3ab(a-b) | a^3+b^3=(a+b)(a^2-ab+b^2) | a^3-b^3=(a-b)(a^2+ab+b^2) | a^2+b^2=(a+b)^2-2ab=(a-b)^2+2ab. x+1/x relations: if x+1/x=k, then x^2+1/x^2=k^2-2, and x^3+1/x^3=k^3-3k. If x-1/x=k, then x^2+1/x^2=k^2+2, and x^3-1/x^3=k^3+3k (sign flips vs the + version — a common trap). ELIMINATION TRICK: any option that looks like just 'k^3' or 'k^2' WITHOUT the correction term (-3k or -2) is a near-miss trap testing whether you remember the full identity.", trapcat: "Algebra (identities)", level: "L2 Application" },
    { q: "Solve for x and y: 2/x + 3/y = 2 and 4/x - 9/y = -1.", options: ["x = 2, y = 3", "x = 4, y = 3", "x = 2, y = 2", "x = 3, y = 2"], answer: 0, explanation: "Let u=1/x, v=1/y: 2u+3v=2 ...(i); 4u-9v=-1 ...(ii). Multiply (i) by 3: 6u+9v=6. Add to (ii): 10u=5 => u=1/2 => x=2. From (i): 1+3v=2 => v=1/3 => y=3. x=3,y=2 swaps the two values; x=2,y=2 and x=4,y=3 fail to satisfy both original fractional equations when substituted back.", rule: "For equations with 1/x and 1/y terms, substitute u=1/x, v=1/y to convert into ordinary LINEAR simultaneous equations, solve normally, then invert at the end to get x and y. || FULL IDENTITY BRUSH-UP — Algebra: (a+b)^2=a^2+2ab+b^2 | (a-b)^2=a^2-2ab+b^2 | a^2-b^2=(a+b)(a-b) | (a+b)^3=a^3+b^3+3ab(a+b) | (a-b)^3=a^3-b^3-3ab(a-b) | a^3+b^3=(a+b)(a^2-ab+b^2) | a^3-b^3=(a-b)(a^2+ab+b^2) | a^2+b^2=(a+b)^2-2ab=(a-b)^2+2ab. x+1/x relations: if x+1/x=k, then x^2+1/x^2=k^2-2, and x^3+1/x^3=k^3-3k. If x-1/x=k, then x^2+1/x^2=k^2+2, and x^3-1/x^3=k^3+3k (sign flips vs the + version — a common trap). ELIMINATION TRICK: any option that looks like just 'k^3' or 'k^2' WITHOUT the correction term (-3k or -2) is a near-miss trap testing whether you remember the full identity.", trapcat: "Algebra (simultaneous equations)", level: "L2 Application" },
    { q: "A cone and a cylinder have the same base radius and the same height. Find the ratio of the volume of the cone to the volume of the cylinder.", options: ["1:3", "1:4", "2:3", "1:2"], answer: 0, explanation: "Volume of cone = (1/3)*pi*r^2*h; Volume of cylinder = pi*r^2*h. Ratio = (1/3):1 = 1:3. 1:2 and 2:3 are common wrong guesses not derived from the actual (1/3) factor in the cone's volume formula; 1:4 overcorrects the fraction.", rule: "A cone's volume is always exactly 1/3 of a cylinder's volume when they share the same base radius AND height — memorize this ratio (1:3) directly rather than recomputing both volumes every time. || FULL FORMULA BRUSH-UP — Mensuration (2D): Square: Area=a^2, Perimeter=4a, Diagonal=a*sqrt(2). Rectangle: Area=l*b, Perimeter=2(l+b), Diagonal=sqrt(l^2+b^2). Triangle(general): Area=(1/2)*base*height; Heron's: s=(a+b+c)/2, Area=sqrt(s(s-a)(s-b)(s-c)). Equilateral triangle: Area=(sqrt(3)/4)*a^2, Height=(sqrt(3)/2)*a. Right triangle: Area=(1/2)*base*height(the two legs). Parallelogram: Area=base*height. Rhombus: Area=(1/2)*d1*d2. Trapezium: Area=(1/2)*(sum of parallel sides)*height. Circle: Area=pi*r^2, Circumference=2*pi*r. Sector: Area=(theta/360)*pi*r^2, Arc length=(theta/360)*2*pi*r. FULL FORMULA BRUSH-UP — Mensuration (3D): Cube: Volume=a^3, Surface Area=6a^2. Cuboid: Volume=l*b*h, Surface Area=2(lb+bh+hl). Cylinder: Volume=pi*r^2*h, Curved SA=2*pi*r*h, Total SA=2*pi*r(r+h). Cone: Volume=(1/3)*pi*r^2*h, Slant height l=sqrt(r^2+h^2), Curved SA=pi*r*l. Sphere: Volume=(4/3)*pi*r^3, SA=4*pi*r^2. Hemisphere: Volume=(2/3)*pi*r^3, Curved SA=2*pi*r^2, Total SA=3*pi*r^2. ELIMINATION TRICK: when only ONE linear dimension (radius/side) changes, ratios scale by its POWER matching the quantity asked — length ratios stay as given, area ratios SQUARE it, volume ratios CUBE it. Options using the wrong power are traps.", trapcat: "Mensuration (cone vs cylinder)", level: "L1 Direct" },
    { q: "A rectangular park measures 50 m by 30 m. A path of uniform width 2 m is built all around the OUTSIDE of the park. Find the area of the path.", options: ["416 sq m", "336 sq m", "320 sq m", "296 sq m"], answer: 1, explanation: "Outer dimensions = (50+2x2) x (30+2x2) = 54 x 34 = 1836 sq m. Inner (park) area = 50x30=1500 sq m. Path area = 1836-1500 = 336 sq m. 320 sq m comes from using only ONE side's extra width (treating it like a simple perimeter x width calculation without correctly handling the corners) — always compute outer-minus-inner area for a path AROUND a shape, which automatically handles the corners correctly.", rule: "For a path OUTSIDE a rectangle: Outer area = (L+2w)(B+2w), Path area = Outer - Inner. For a path INSIDE (bordering within the rectangle): Inner area = (L-2w)(B-2w), Path area = Given - Inner. || FULL FORMULA BRUSH-UP — Mensuration (2D): Square: Area=a^2, Perimeter=4a, Diagonal=a*sqrt(2). Rectangle: Area=l*b, Perimeter=2(l+b), Diagonal=sqrt(l^2+b^2). Triangle(general): Area=(1/2)*base*height; Heron's: s=(a+b+c)/2, Area=sqrt(s(s-a)(s-b)(s-c)). Equilateral triangle: Area=(sqrt(3)/4)*a^2, Height=(sqrt(3)/2)*a. Right triangle: Area=(1/2)*base*height(the two legs). Parallelogram: Area=base*height. Rhombus: Area=(1/2)*d1*d2. Trapezium: Area=(1/2)*(sum of parallel sides)*height. Circle: Area=pi*r^2, Circumference=2*pi*r. Sector: Area=(theta/360)*pi*r^2, Arc length=(theta/360)*2*pi*r. FULL FORMULA BRUSH-UP — Mensuration (3D): Cube: Volume=a^3, Surface Area=6a^2. Cuboid: Volume=l*b*h, Surface Area=2(lb+bh+hl). Cylinder: Volume=pi*r^2*h, Curved SA=2*pi*r*h, Total SA=2*pi*r(r+h). Cone: Volume=(1/3)*pi*r^2*h, Slant height l=sqrt(r^2+h^2), Curved SA=pi*r*l. Sphere: Volume=(4/3)*pi*r^3, SA=4*pi*r^2. Hemisphere: Volume=(2/3)*pi*r^3, Curved SA=2*pi*r^2, Total SA=3*pi*r^2. ELIMINATION TRICK: when only ONE linear dimension (radius/side) changes, ratios scale by its POWER matching the quantity asked — length ratios stay as given, area ratios SQUARE it, volume ratios CUBE it. Options using the wrong power are traps.", trapcat: "Mensuration (combined figures)", level: "L2 Application" },
    { q: "How many numbers from 1 to 500 are divisible by 3 or 5?", options: ["233", "266", "223", "248"], answer: 0, explanation: "Divisible by 3: floor(500/3)=166. Divisible by 5: floor(500/5)=100. Divisible by both (15): floor(500/15)=33. By inclusion-exclusion: 166+100-33=233. 266 (simply adding the two counts) double-counts numbers divisible by BOTH 3 and 5 (i.e. by 15) — this is the classic inclusion-exclusion omission error.", rule: "For 'divisible by A or B' counting questions, ALWAYS use inclusion-exclusion: count(A)+count(B)-count(LCM of A,B) — never just add the two individual counts. || FULL BRUSH-UP — Number System: Divisibility rules: by 2(last digit even), by 3(digit sum divisible by 3), by 4(last 2 digits divisible by 4), by 5(last digit 0 or 5), by 6(divisible by both 2 and 3), by 8(last 3 digits divisible by 8), by 9(digit sum divisible by 9), by 11(alternating digit-sum difference divisible by 11). Unit-digit cycles: 2:(2,4,8,6) | 3:(3,9,7,1) | 4:(4,6) | 7:(7,9,3,1) | 8:(8,4,2,6) | 9:(9,1) — cycle length 4 for 2/3/7/8, length 2 for 4/9, and 0/1/5/6 always repeat themselves. 'Divides leaving remainder r' -> subtract r first, then take HCF/LCM. 'Smallest number to subtract/add to be divisible by d' -> use (N mod d) as the subtract value, (d - N mod d) as the add value. ELIMINATION TRICK: for unit-digit/remainder problems, if the exponent is an EXACT multiple of the cycle length, use the LAST value in the cycle (not a 'zero' position) — the most common off-by-one trap.", trapcat: "Number System (counting/divisibility)", level: "L2 Application" },
    { q: "The HCF of two numbers is 12 and their LCM is 336. If one of the numbers is 48, find the other number.", options: ["70", "96", "72", "84"], answer: 3, explanation: "Product of two numbers = HCF x LCM = 12x336=4032. Other number = 4032/48 = 84. 96 is a plausible-looking multiple of 12 but doesn't satisfy HCF(48,96)=12 AND LCM(48,96)=336 simultaneously when checked — always verify, don't just guess a multiple.", rule: "KEY RELATION: (Number1) x (Number2) = HCF x LCM — always holds for exactly TWO numbers (not for three or more), making this a one-step shortcut instead of prime factorization. || FULL BRUSH-UP — Number System: Divisibility rules: by 2(last digit even), by 3(digit sum divisible by 3), by 4(last 2 digits divisible by 4), by 5(last digit 0 or 5), by 6(divisible by both 2 and 3), by 8(last 3 digits divisible by 8), by 9(digit sum divisible by 9), by 11(alternating digit-sum difference divisible by 11). Unit-digit cycles: 2:(2,4,8,6) | 3:(3,9,7,1) | 4:(4,6) | 7:(7,9,3,1) | 8:(8,4,2,6) | 9:(9,1) — cycle length 4 for 2/3/7/8, length 2 for 4/9, and 0/1/5/6 always repeat themselves. 'Divides leaving remainder r' -> subtract r first, then take HCF/LCM. 'Smallest number to subtract/add to be divisible by d' -> use (N mod d) as the subtract value, (d - N mod d) as the add value. ELIMINATION TRICK: for unit-digit/remainder problems, if the exponent is an EXACT multiple of the cycle length, use the LAST value in the cycle (not a 'zero' position) — the most common off-by-one trap.", trapcat: "Number System (HCF/LCM)", level: "L1 Direct" },
    { q: "Find the value of: sin60°cos30° + cos60°sin30°.", options: ["sqrt(3)/2", "1/2", "1", "0"], answer: 2, explanation: "This matches the identity sin(A+B)=sinAcosB+cosAsinB, so the expression = sin(60+30) = sin90 = 1. 1/2 and sqrt(3)/2 result from computing only ONE of the two product terms and forgetting to add the second; 0 would be the result of SUBTRACTING instead of adding the two terms (which would instead give sin(60-30)=sin30=1/2, still not 0 — showing the importance of matching the exact identity pattern).", rule: "Recognize the sin(A+B) / cos(A+B) / sin(A-B) / cos(A-B) expansion PATTERNS directly in a sum-of-products expression — this skips plugging in individual sin/cos values entirely and avoids arithmetic slips. || FULL BRUSH-UP — Trigonometric ratio table (memorize fully): | Angle:    0    30        45        60        90 | sin:      0    1/2       1/sqrt2   sqrt3/2   1 | cos:      1    sqrt3/2   1/sqrt2   1/2       0 | tan:      0    1/sqrt3   1         sqrt3     undefined | Identities: sin^2A+cos^2A=1 | 1+tan^2A=sec^2A | 1+cot^2A=cosec^2A | tanA=sinA/cosA | cotA=1/tanA. Height-Distance setup: angle of elevation increases as you move CLOSER to the object; for a two-angle problem, set up tan(angle1)=h/d1 and tan(angle2)=h/d2, use the given distance DIFFERENCE (d1-d2) to eliminate one variable algebraically. ELIMINATION TRICK: tan45=1 always gives height=base distance exactly — if an option doesn't equal the given distance in a 45-degree case, eliminate it instantly.", trapcat: "Trigonometry (identities)", level: "L2 Application" },
    { q: "From the top of a 20 m tall building, the angle of depression to the foot of a tower is 30°, and the angle of elevation to the top of the same tower is 60°. Find the height of the tower. (Use sqrt(3)=1.732)", options: ["40 m", "100 m", "60 m", "80 m"], answer: 3, explanation: "Angle of depression to tower's foot = 30° means the horizontal distance d satisfies tan30 = 20/d => d = 20*sqrt(3) = 34.64 m. Angle of elevation to tower's top = 60° means tan60 = (extra height above building)/d => extra height = d*sqrt(3) = 34.64*1.732 = 60 m. Total tower height = 20 (building) + 60 (extra) = 80 m. 60 m is just the EXTRA height above the building, mistaken for the tower's TOTAL height (forgetting to add the building's own 20 m); 100 m and 40 m come from distance-calculation slips.", rule: "In 'building and tower' problems, the depression angle gives the horizontal distance using the BUILDING's height; then the elevation angle (from the SAME point, same distance) gives the EXTRA height above the building — total tower height = building height + extra height. || FULL BRUSH-UP — Trigonometric ratio table (memorize fully): | Angle:    0    30        45        60        90 | sin:      0    1/2       1/sqrt2   sqrt3/2   1 | cos:      1    sqrt3/2   1/sqrt2   1/2       0 | tan:      0    1/sqrt3   1         sqrt3     undefined | Identities: sin^2A+cos^2A=1 | 1+tan^2A=sec^2A | 1+cot^2A=cosec^2A | tanA=sinA/cosA | cotA=1/tanA. Height-Distance setup: angle of elevation increases as you move CLOSER to the object; for a two-angle problem, set up tan(angle1)=h/d1 and tan(angle2)=h/d2, use the given distance DIFFERENCE (d1-d2) to eliminate one variable algebraically. ELIMINATION TRICK: tan45=1 always gives height=base distance exactly — if an option doesn't equal the given distance in a 45-degree case, eliminate it instantly.", trapcat: "Trigonometry (height & distance)", level: "L3 Trap" },
    { q: "A family's monthly expenses are: Rent Rs.8,000, Food Rs.6,000, Transport Rs.2,000, Savings Rs.4,000. Find the ratio of Food expense to Savings.", options: ["3:1", "1:2", "3:2", "2:3"], answer: 2, explanation: "Food:Savings = 6000:4000 = 3:2 (dividing both by their HCF, 2000). 2:3 simply reverses the ratio (a common careless swap of numerator/denominator); 3:1 and 1:2 don't match the actual values at all.", rule: "Always reduce a ratio by dividing both terms by their HCF, and double-check which quantity the question lists FIRST (that one becomes the ratio's first term). || FULL BRUSH-UP — Ratio, Average & Partnership: To combine two ratios sharing a common term (e.g. A:B and B:C), scale both so the common term (B) matches via LCM, then merge into one combined ratio. Partnership profit-share = Capital * Time-invested for each partner (never capital alone if durations differ). Average of an Arithmetic Progression = (first term + last term)/2. Combined average of two groups of DIFFERENT sizes = weighted average = (n1*a1+n2*a2)/(n1+n2), never the simple average of the two averages unless the group sizes are equal. ELIMINATION TRICK: an option that's just the plain average of two given averages (ignoring group sizes/weights) is the single most common average-question trap.", trapcat: "Data Interpretation (ratio)", level: "L1 Direct" },
    { q: "The average of 7 consecutive integers is 30. If the next 3 consecutive integers (continuing the same sequence) are also included, find the new average of all 10 integers.", options: ["30.0", "31.5", "32.0", "32.5"], answer: 1, explanation: "7 consecutive integers averaging 30 are 27 to 33 (sum=210). The next 3 are 34,35,36 (sum=105). Total of all 10 = 315. New average = 315/10 = 31.5. 30.0 wrongly assumes adding more consecutive (increasing) integers leaves the average unchanged; 32.0 is a rough guess without actually listing the numbers.", rule: "For consecutive-integer average problems, first find the actual starting number (average of an odd count of consecutive integers IS the middle number), list out the real numbers, then recompute directly. || FULL BRUSH-UP — Ratio, Average & Partnership: To combine two ratios sharing a common term (e.g. A:B and B:C), scale both so the common term (B) matches via LCM, then merge into one combined ratio. Partnership profit-share = Capital * Time-invested for each partner (never capital alone if durations differ). Average of an Arithmetic Progression = (first term + last term)/2. Combined average of two groups of DIFFERENT sizes = weighted average = (n1*a1+n2*a2)/(n1+n2), never the simple average of the two averages unless the group sizes are equal. ELIMINATION TRICK: an option that's just the plain average of two given averages (ignoring group sizes/weights) is the single most common average-question trap.", trapcat: "Average", level: "L2 Application" },
    { q: "A, B, and C invest Rs. 5,000 (for 12 months), Rs. 7,000 (for 8 months), and Rs. 4,000 (for 6 months) respectively in a business. If the total annual profit is Rs. 16,500, find C's share.", options: ["Rs. 3,000", "Rs. 2829", "Rs. 7071", "Rs. 6600"], answer: 1, explanation: "Capital x Time: A=5000x12=60000, B=7000x8=56000, C=4000x6=24000. Total=140000. C's share = 16500 x 24000/140000 = Rs.2829. Rs.7071 and Rs.6600 are A's and B's shares respectively (easy to mix up which partner's share is being asked); Rs.3,000 comes from a naive equal three-way split ignoring both capital and time.", rule: "In 3-partner problems, compute (Capital x Time) for ALL partners, sum them for the total, then multiply the TOTAL PROFIT by each partner's individual fraction of that total. || FULL BRUSH-UP — Ratio, Average & Partnership: To combine two ratios sharing a common term (e.g. A:B and B:C), scale both so the common term (B) matches via LCM, then merge into one combined ratio. Partnership profit-share = Capital * Time-invested for each partner (never capital alone if durations differ). Average of an Arithmetic Progression = (first term + last term)/2. Combined average of two groups of DIFFERENT sizes = weighted average = (n1*a1+n2*a2)/(n1+n2), never the simple average of the two averages unless the group sizes are equal. ELIMINATION TRICK: an option that's just the plain average of two given averages (ignoring group sizes/weights) is the single most common average-question trap.", trapcat: "Ratio & Proportion (Partnership)", level: "L2 Application" },
    { q: "A trader marks his goods 40% above the cost price of Rs. 1,000 and then allows a discount of 20%. Find his profit percentage.", options: ["20%", "8%", "12%", "0% (no profit, no loss)"], answer: 2, explanation: "MP = 1000x1.40 = Rs.1400. SP = 1400x0.80 = Rs.1120. Profit = 1120-1000=Rs.120, i.e. 12%. 20% comes from naively subtracting the discount from the markup (40%-20%+...) without properly chaining MP then SP; 8% and 0% are miscalculations that don't follow from the actual CP-MP-SP chain.", rule: "Net effect of markup m% then discount d% on CP = [(1+m/100)(1-d/100) - 1] x 100 — always compute via this chained multiplier, never by subtracting percentages directly. || FULL BRUSH-UP — Percentage & Profit-Loss: Fraction-to-% table (memorize): 1/2=50%, 1/3=33.33%, 1/4=25%, 1/5=20%, 1/6=16.67%, 1/7=14.28%, 1/8=12.5%, 1/9=11.11%, 1/10=10%, 1/11=9.09%, 1/12=8.33% — instantly convert common fractions without long division. Successive % change: net multiplier=(1+a/100)(1+b/100); NEVER just add/subtract the two percentages. Profit%=((SP-CP)/CP)*100, Loss%=((CP-SP)/CP)*100. Discount is always on Marked Price: SP=MP*(1-discount%/100). Faulty weight dealer: Profit% = [(True weight-False weight)/False weight]*100 (denominator is the ACTUAL/false weight given, not the claimed one). ELIMINATION TRICK: when markup% and discount% are both given, compute via MP and SP step by step — an option that looks like a simple (markup% - discount%) subtraction is almost always the trap.", trapcat: "Profit & Loss (multi-step)", level: "L2 Application" },
    { q: "The present ages of A and B are in the ratio 3:4. After 5 years, the ratio of their ages will become 4:5. Find their present ages.", options: ["A = 12 years, B = 16 years", "A = 20 years, B = 25 years", "A = 12 years, B = 17 years", "A = 15 years, B = 20 years"], answer: 3, explanation: "Let ages = 3x, 4x. (3x+5)/(4x+5) = 4/5 => 5(3x+5) = 4(4x+5) => 15x+25 = 16x+20 => x=5. Ages = 15 and 20 years. 12 and 16 keep the exact 3:4 ratio (12:16=3:4) but fail the SECOND condition (after +5 years, their ratio must become 4:5) when checked — a trap for stopping after satisfying only the first condition.", rule: "For ratio-based age problems with a FUTURE condition, always set up both the current ratio AND the future ratio as two separate relations, then solve for the common multiplier x using the future condition. || FULL IDENTITY BRUSH-UP — Algebra: (a+b)^2=a^2+2ab+b^2 | (a-b)^2=a^2-2ab+b^2 | a^2-b^2=(a+b)(a-b) | (a+b)^3=a^3+b^3+3ab(a+b) | (a-b)^3=a^3-b^3-3ab(a-b) | a^3+b^3=(a+b)(a^2-ab+b^2) | a^3-b^3=(a-b)(a^2+ab+b^2) | a^2+b^2=(a+b)^2-2ab=(a-b)^2+2ab. x+1/x relations: if x+1/x=k, then x^2+1/x^2=k^2-2, and x^3+1/x^3=k^3-3k. If x-1/x=k, then x^2+1/x^2=k^2+2, and x^3-1/x^3=k^3+3k (sign flips vs the + version — a common trap). ELIMINATION TRICK: any option that looks like just 'k^3' or 'k^2' WITHOUT the correction term (-3k or -2) is a near-miss trap testing whether you remember the full identity.", trapcat: "Algebra (ages)", level: "L2 Application" },
    { q: "A metallic sphere of radius 6 cm is melted and recast into smaller spheres, each of radius 2 cm. How many smaller spheres are formed?", options: ["27", "12", "54", "9"], answer: 0, explanation: "Volume is conserved: (4/3)pi(6)^3 = n x (4/3)pi(2)^3 => n = (6/2)^3 = 3^3 = 27. 9 (=3^2) wrongly SQUARES the radius ratio instead of CUBING it — a volume-scaling question always needs the cube of the linear ratio, not the square (which would be appropriate for surface area instead).", rule: "When a solid is melted and recast into smaller identical solids, the COUNT = (ratio of radii/linear dimensions)^3 — always cube for volume problems, square only for area/surface problems. || FULL FORMULA BRUSH-UP — Mensuration (2D): Square: Area=a^2, Perimeter=4a, Diagonal=a*sqrt(2). Rectangle: Area=l*b, Perimeter=2(l+b), Diagonal=sqrt(l^2+b^2). Triangle(general): Area=(1/2)*base*height; Heron's: s=(a+b+c)/2, Area=sqrt(s(s-a)(s-b)(s-c)). Equilateral triangle: Area=(sqrt(3)/4)*a^2, Height=(sqrt(3)/2)*a. Right triangle: Area=(1/2)*base*height(the two legs). Parallelogram: Area=base*height. Rhombus: Area=(1/2)*d1*d2. Trapezium: Area=(1/2)*(sum of parallel sides)*height. Circle: Area=pi*r^2, Circumference=2*pi*r. Sector: Area=(theta/360)*pi*r^2, Arc length=(theta/360)*2*pi*r. FULL FORMULA BRUSH-UP — Mensuration (3D): Cube: Volume=a^3, Surface Area=6a^2. Cuboid: Volume=l*b*h, Surface Area=2(lb+bh+hl). Cylinder: Volume=pi*r^2*h, Curved SA=2*pi*r*h, Total SA=2*pi*r(r+h). Cone: Volume=(1/3)*pi*r^2*h, Slant height l=sqrt(r^2+h^2), Curved SA=pi*r*l. Sphere: Volume=(4/3)*pi*r^3, SA=4*pi*r^2. Hemisphere: Volume=(2/3)*pi*r^3, Curved SA=2*pi*r^2, Total SA=3*pi*r^2. ELIMINATION TRICK: when only ONE linear dimension (radius/side) changes, ratios scale by its POWER matching the quantity asked — length ratios stay as given, area ratios SQUARE it, volume ratios CUBE it. Options using the wrong power are traps.", trapcat: "Mensuration (melting & recasting)", level: "L2 Application" },
    { q: "Find the digit x such that the 5-digit number '4x672' is exactly divisible by 11.", options: ["9", "5", "7", "3"], answer: 1, explanation: "Divisibility by 11: (sum of digits at odd positions) - (sum of digits at even positions) must be 0 or a multiple of 11. From the right: positions are 2,7,6,x,4. Odd positions(1st,3rd,5th)=2+6+4=12. Even positions(2nd,4th)=7+x. Difference=12-(7+x)=5-x. For divisibility, 5-x=0 => x=5. 3, 7, and 9 do not make the alternating digit-sum difference equal to 0 or a multiple of 11 when substituted — always verify by direct substitution if unsure which position convention was used.", rule: "Divisibility by 11: take the alternating sum of digits (from either end, consistently), and check if the result is 0 or a multiple of 11 — always define 'odd/even position' clearly before computing. || FULL BRUSH-UP — Number System: Divisibility rules: by 2(last digit even), by 3(digit sum divisible by 3), by 4(last 2 digits divisible by 4), by 5(last digit 0 or 5), by 6(divisible by both 2 and 3), by 8(last 3 digits divisible by 8), by 9(digit sum divisible by 9), by 11(alternating digit-sum difference divisible by 11). Unit-digit cycles: 2:(2,4,8,6) | 3:(3,9,7,1) | 4:(4,6) | 7:(7,9,3,1) | 8:(8,4,2,6) | 9:(9,1) — cycle length 4 for 2/3/7/8, length 2 for 4/9, and 0/1/5/6 always repeat themselves. 'Divides leaving remainder r' -> subtract r first, then take HCF/LCM. 'Smallest number to subtract/add to be divisible by d' -> use (N mod d) as the subtract value, (d - N mod d) as the add value. ELIMINATION TRICK: for unit-digit/remainder problems, if the exponent is an EXACT multiple of the cycle length, use the LAST value in the cycle (not a 'zero' position) — the most common off-by-one trap.", trapcat: "Number System (divisibility)", level: "L2 Application" }
  ]
}
];
